import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { usePlayers } from '../../hooks/usePlayers';
import Avatar from '../../components/common/Avatar';
import { PositionBadge } from '../../components/common/Badge';
import { PILLARS, getPillarLabel, getScoreColor, getLatestAssessment } from '../../utils/helpers';

const SORT_OPTIONS = [
  { value: 'name', label: 'Po imenu' },
  { value: 'technical', label: 'Tehnički' },
  { value: 'tactical', label: 'Taktički' },
  { value: 'physical', label: 'Fizički' },
  { value: 'psychological', label: 'Psihološki' },
  { value: 'overall', label: 'Ukupni prosek' }
];

function PillarCell({ value }) {
  const color = getScoreColor(value);
  const width = value ? `${(value / 10) * 100}%` : '0%';

  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8, minWidth: 100 }}>
      <div style={{
        flex: 1,
        height: 6,
        background: 'var(--border)',
        borderRadius: 3,
        overflow: 'hidden'
      }}>
        <div style={{
          width,
          height: '100%',
          background: color,
          borderRadius: 3,
          transition: 'width 0.5s ease'
        }} />
      </div>
      <span style={{
        width: 24,
        textAlign: 'right',
        fontSize: '0.82rem',
        fontWeight: 700,
        color: value ? color : 'var(--text-muted)'
      }}>
        {value || '—'}
      </span>
    </div>
  );
}

export default function ProgressOverviewPage() {
  const { players, loading } = usePlayers();
  const navigate = useNavigate();
  const [sortBy, setSortBy] = useState('name');
  const [sortDir, setSortDir] = useState('asc');

  const playersWithScores = useMemo(() => {
    return players.map(player => {
      const latest = getLatestAssessment(player.assessments);
      const scores = {
        technical: latest?.technical || 0,
        tactical: latest?.tactical || 0,
        physical: latest?.physical || 0,
        psychological: latest?.psychological || 0
      };
      const overall = latest
        ? (scores.technical + scores.tactical + scores.physical + scores.psychological) / 4
        : 0;

      return { ...player, scores, overall, hasAssessment: !!latest };
    });
  }, [players]);

  const sorted = useMemo(() => {
    const arr = [...playersWithScores];
    arr.sort((a, b) => {
      let valA, valB;

      if (sortBy === 'name') {
        const nameA = `${a.firstName || ''} ${a.lastName || ''}`.toLowerCase();
        const nameB = `${b.firstName || ''} ${b.lastName || ''}`.toLowerCase();
        valA = nameA; valB = nameB;
        return sortDir === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
      } else if (sortBy === 'overall') {
        valA = a.overall; valB = b.overall;
      } else {
        valA = a.scores[sortBy] || 0;
        valB = b.scores[sortBy] || 0;
      }

      return sortDir === 'asc' ? valA - valB : valB - valA;
    });
    return arr;
  }, [playersWithScores, sortBy, sortDir]);

  const handleSort = (field) => {
    if (sortBy === field) {
      setSortDir(d => d === 'asc' ? 'desc' : 'asc');
    } else {
      setSortBy(field);
      setSortDir('desc');
    }
  };

  const SortIcon = ({ field }) => {
    if (sortBy !== field) return <span style={{ color: 'var(--text-muted)', fontSize: '0.7rem' }}>↕</span>;
    return <span style={{ color: 'var(--gold)', fontSize: '0.7rem' }}>{sortDir === 'asc' ? '↑' : '↓'}</span>;
  };

  if (loading) {
    return <div className="loading-container"><div className="loading-spinner" /></div>;
  }

  // Stats summary
  const withAssessment = playersWithScores.filter(p => p.hasAssessment);
  const avgOverall = withAssessment.length > 0
    ? (withAssessment.reduce((acc, p) => acc + p.overall, 0) / withAssessment.length).toFixed(1)
    : '—';

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">Napredak svih igrača</h1>
          <p className="page-subtitle">
            {players.length} igrača · {withAssessment.length} procenjeno · Prosek ekipe: {avgOverall}
          </p>
        </div>

        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <label className="label" style={{ margin: 0, fontSize: '0.75rem' }}>Sortiraj po:</label>
          <select
            className="input"
            style={{ width: 'auto', fontSize: '0.85rem' }}
            value={sortBy}
            onChange={e => { setSortBy(e.target.value); setSortDir('desc'); }}
          >
            {SORT_OPTIONS.map(o => (
              <option key={o.value} value={o.value}>{o.label}</option>
            ))}
          </select>
        </div>
      </div>

      {players.length === 0 ? (
        <div className="empty-state">
          <div className="empty-state-icon">📊</div>
          <div className="empty-state-title">Nema igrača</div>
          <p className="empty-state-text">Dodaj igrače i proceni ih da vidiš napredak ovde.</p>
        </div>
      ) : (
        <div>
          {/* Table header */}
          <div style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius-lg)',
            overflow: 'hidden'
          }}>
            <div style={{
              display: 'grid',
              gridTemplateColumns: '2fr 1fr 1fr 1fr 1fr 1fr',
              padding: '12px 20px',
              borderBottom: '1px solid var(--border)',
              background: 'var(--bg-primary)'
            }}>
              <div
                onClick={() => handleSort('name')}
                style={{ fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', cursor: 'pointer', display: 'flex', gap: 4, alignItems: 'center' }}
              >
                Igrač <SortIcon field="name" />
              </div>
              {PILLARS.map(p => (
                <div
                  key={p.key}
                  onClick={() => handleSort(p.key)}
                  style={{ fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', cursor: 'pointer', display: 'flex', gap: 4, alignItems: 'center' }}
                >
                  {p.label} <SortIcon field={p.key} />
                </div>
              ))}
              <div
                onClick={() => handleSort('overall')}
                style={{ fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', cursor: 'pointer', display: 'flex', gap: 4, alignItems: 'center' }}
              >
                Prosek <SortIcon field="overall" />
              </div>
            </div>

            {/* Rows */}
            <div>
              {sorted.map((player, idx) => {
                const fullName = `${player.firstName || ''} ${player.lastName || ''}`.trim() || 'Nepoznat';
                const overallColor = getScoreColor(Math.round(player.overall));

                return (
                  <div
                    key={player.id}
                    onClick={() => navigate(`/igrac/${player.id}`)}
                    className="animate-fade-in"
                    style={{
                      display: 'grid',
                      gridTemplateColumns: '2fr 1fr 1fr 1fr 1fr 1fr',
                      padding: '14px 20px',
                      borderBottom: idx < sorted.length - 1 ? '1px solid var(--border)' : 'none',
                      alignItems: 'center',
                      cursor: 'pointer',
                      transition: 'background 0.15s ease',
                      animationDelay: `${idx * 30}ms`
                    }}
                    onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.03)'}
                    onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                  >
                    {/* Player info */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                      <span style={{
                        width: 24,
                        fontSize: '0.75rem',
                        color: 'var(--text-muted)',
                        fontWeight: 700,
                        textAlign: 'right'
                      }}>
                        {idx + 1}
                      </span>
                      <Avatar src={player.photoBase64} name={fullName} size="sm" />
                      <div>
                        <div style={{ fontWeight: 600, fontSize: '0.88rem' }}>{fullName}</div>
                        <div style={{ display: 'flex', gap: 6, marginTop: 3 }}>
                          <PositionBadge position={player.position} />
                          {!player.hasAssessment && (
                            <span style={{
                              fontSize: '0.68rem',
                              color: 'var(--text-muted)',
                              background: 'var(--bg-primary)',
                              border: '1px solid var(--border)',
                              borderRadius: 3,
                              padding: '1px 5px'
                            }}>
                              bez procene
                            </span>
                          )}
                        </div>
                      </div>
                    </div>

                    {/* Pillar scores */}
                    {PILLARS.map(p => (
                      <PillarCell key={p.key} value={player.scores[p.key]} />
                    ))}

                    {/* Overall */}
                    <div style={{ display: 'flex', alignItems: 'center' }}>
                      <span style={{
                        fontSize: '1.1rem',
                        fontWeight: 800,
                        color: player.hasAssessment ? overallColor : 'var(--text-muted)'
                      }}>
                        {player.hasAssessment ? player.overall.toFixed(1) : '—'}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Legend */}
          <div style={{ display: 'flex', gap: 20, marginTop: 14, flexWrap: 'wrap' }}>
            <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Legenda:</div>
            {[
              { color: 'var(--error)', label: '< 4 Osnovno' },
              { color: 'var(--warning)', label: '4–7 Srednje' },
              { color: 'var(--success)', label: '> 7 Odlično' }
            ].map(item => (
              <div key={item.label} style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                <div style={{ width: 10, height: 10, borderRadius: 2, background: item.color }} />
                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>{item.label}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
