import React, { useState, useRef, useEffect } from 'react';
import { usePlayerProcena } from '../../../hooks/usePlayerExtras';

const SEGMENTS = [
  {
    id: 'tehnika',
    label: '1. Tehnički segment',
    hasOcena: true,
    items: [
      'Stav (osnovni)',
      'Hvat (prednji/bočni/visoki)',
      'Rad nogu (dokorak, prekorak)',
      'Padovi (niski, let)',
      'Iskoraci (iskorak, negativ, colaps)',
      'Odbrane sa distance (preko 20m)',
      'Odbrane sa poludistance (u20m)',
      '1v1 situacije'
    ]
  },
  {
    id: 'taktika',
    label: '2. Taktički segment',
    hasOcena: true,
    items: [
      'Pozicioniranje',
      'Praćenje dubine',
      'Reagovanje na centršut',
      'Ulazak u igru',
      'Taktički zahtevi ekipe',
      'Igra nogom – kratko',
      'Igra nogom – dugo'
    ]
  },
  {
    id: 'motoricki',
    label: '3. Motorički / Fizički segment',
    hasOcena: true,
    items: [
      'Brzina reakcije',
      'Eksplozivnost',
      'Snaga',
      'Kondicija',
      'Agilnost'
    ]
  },
  {
    id: 'psiholoski',
    label: '4. Psihološki segment',
    hasOcena: true,
    items: [
      'Reakcija na grešku',
      'Emocionalna kontrola',
      'Samopouzdanje',
      'Fokus',
      'Komunikacija'
    ]
  },
  {
    id: 'radneNavike',
    label: '5. Radne navike',
    hasOcena: false,
    items: [
      'Odnos prema treningu',
      'Koncentracija',
      'Disciplinovanost',
      'Spremnost na korekciju'
    ]
  }
];

function emptyForm() {
  const segments = {};
  SEGMENTS.forEach(seg => {
    segments[seg.id] = {};
    seg.items.forEach((_, i) => {
      segments[seg.id][i] = seg.hasOcena
        ? { zapazanje: '', ocena: '' }
        : { zapazanje: '' };
    });
  });
  return {
    period: '',
    trainingCount: '',
    ...segments,
    prostorZaNapredak: '',
    opstiZakljucak: '',
    ciljZaNaredniPeriod: ''
  };
}

function formFromProcena(p) {
  const segments = {};
  SEGMENTS.forEach(seg => {
    segments[seg.id] = {};
    seg.items.forEach((_, i) => {
      const saved = p[seg.id] ? p[seg.id][i] : null;
      segments[seg.id][i] = saved || (seg.hasOcena ? { zapazanje: '', ocena: '' } : { zapazanje: '' });
    });
  });
  return {
    period: p.period || '',
    trainingCount: p.trainingCount || '',
    ...segments,
    prostorZaNapredak: p.prostorZaNapredak || '',
    opstiZakljucak: p.opstiZakljucak || '',
    ciljZaNaredniPeriod: p.ciljZaNaredniPeriod || ''
  };
}

function formatDate(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  return d.toLocaleDateString('sr-Latn-RS', { day: '2-digit', month: '2-digit', year: 'numeric' });
}

function scoreColor(v) {
  const n = parseFloat(v);
  if (!n) return 'var(--text-muted)';
  if (n >= 8) return '#22c55e';
  if (n >= 6) return 'var(--gold)';
  return '#ef4444';
}

function segmentAvg(formData, seg) {
  if (!seg.hasOcena) return null;
  const scores = seg.items.map((_, i) => parseFloat(formData[seg.id]?.[i]?.ocena)).filter(v => !isNaN(v) && v > 0);
  if (!scores.length) return null;
  return (scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(1);
}

export default function Procena({ player }) {
  const { procenas, loading, addProcena, updateProcena, deleteProcena } = usePlayerProcena(player.id);
  const [view, setView] = useState('list'); // 'list' | 'form' | 'detail'
  const [editingId, setEditingId] = useState(null);
  const [detailId, setDetailId] = useState(null);
  const [form, setForm] = useState(emptyForm());
  const [saveStatus, setSaveStatus] = useState(''); // '' | 'saving' | 'saved'
  const autoSaveTimer = useRef(null);
  const editingIdRef = useRef(null);

  useEffect(() => () => { if (autoSaveTimer.current) clearTimeout(autoSaveTimer.current); }, []);

  const scheduleAutoSave = (newForm) => {
    if (autoSaveTimer.current) clearTimeout(autoSaveTimer.current);
    setSaveStatus('saving');
    autoSaveTimer.current = setTimeout(async () => {
      try {
        if (editingIdRef.current) {
          await updateProcena(editingIdRef.current, newForm);
        } else {
          const id = await addProcena(newForm);
          editingIdRef.current = id;
          setEditingId(id);
        }
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus(''), 2000);
      } catch (e) {
        console.error(e);
        setSaveStatus('');
      }
    }, 700);
  };

  const openNew = () => {
    setForm(emptyForm());
    setEditingId(null);
    editingIdRef.current = null;
    setSaveStatus('');
    setView('form');
  };

  const openEdit = (p) => {
    setForm(formFromProcena(p));
    setEditingId(p.id);
    editingIdRef.current = p.id;
    setSaveStatus('');
    setView('form');
  };

  const openDetail = (p) => {
    setDetailId(p.id);
    setView('detail');
  };

  const handleSave = async () => {
    if (autoSaveTimer.current) {
      clearTimeout(autoSaveTimer.current);
      autoSaveTimer.current = null;
    }
    setSaveStatus('saving');
    try {
      if (editingIdRef.current) {
        await updateProcena(editingIdRef.current, form);
      } else {
        await addProcena(form);
      }
      setView('list');
    } catch (e) {
      console.error(e);
      setSaveStatus('');
    }
  };

  const handleDelete = async (id, e) => {
    e.stopPropagation();
    if (!window.confirm('Obrisati ovu procenu?')) return;
    await deleteProcena(id);
    if (detailId === id) setView('list');
  };

  const setSegItem = (segId, idx, field, value) => {
    setForm(prev => {
      const newForm = {
        ...prev,
        [segId]: { ...prev[segId], [idx]: { ...prev[segId][idx], [field]: value } }
      };
      scheduleAutoSave(newForm);
      return newForm;
    });
  };

  const setOcena = (segId, idx, delta) => {
    const cur = parseFloat(form[segId][idx].ocena) || 0;
    const next = Math.min(10, Math.max(1, Math.round((cur + delta) * 2) / 2));
    setSegItem(segId, idx, 'ocena', next === 0 ? '' : next);
  };

  const setTopField = (field, value) => {
    setForm(prev => {
      const newForm = { ...prev, [field]: value };
      scheduleAutoSave(newForm);
      return newForm;
    });
  };

  if (loading) return <div style={{ padding: 20, color: 'var(--text-muted)', fontSize: '0.85rem' }}>Učitavam...</div>;

  // Detail view
  if (view === 'detail') {
    const p = procenas.find(x => x.id === detailId);
    if (!p) { setView('list'); return null; }
    return (
      <div>
        <div style={{ display: 'flex', gap: 10, marginBottom: 20, alignItems: 'center' }}>
          <button className="btn btn-secondary btn-sm" onClick={() => setView('list')}>← Lista</button>
          <div style={{ flex: 1 }} />
          <button className="btn btn-secondary btn-sm" onClick={() => openEdit(p)}>✏ Uredi</button>
          <button className="btn btn-sm" onClick={e => handleDelete(p.id, e)}
            style={{ color: 'var(--error)', border: '1px solid rgba(239,68,68,0.3)', background: 'transparent' }}>
            Obriši
          </button>
        </div>

        <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: 20, marginBottom: 16 }}>
          <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginBottom: 4 }}>Procena od {formatDate(p.createdAt)}</div>
          <div style={{ display: 'flex', gap: 24, flexWrap: 'wrap' }}>
            {p.period && <div style={{ fontSize: '0.88rem' }}><span style={{ color: 'var(--text-muted)' }}>Period: </span>{p.period}</div>}
            {p.trainingCount && <div style={{ fontSize: '0.88rem' }}><span style={{ color: 'var(--text-muted)' }}>Broj treninga/utakmica: </span>{p.trainingCount}</div>}
          </div>
        </div>

        {SEGMENTS.map(seg => {
          const avg = segmentAvg(formFromProcena(p), seg);
          return (
            <div key={seg.id} style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', marginBottom: 12, overflow: 'hidden' }}>
              <div style={{
                padding: '12px 16px',
                borderBottom: '1px solid var(--border)',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                background: 'var(--bg-primary)'
              }}>
                <span style={{ fontWeight: 700, fontSize: '0.9rem' }}>{seg.label}</span>
                {avg && (
                  <span style={{ fontWeight: 700, fontSize: '0.95rem', color: scoreColor(avg) }}>⌀ {avg}</span>
                )}
              </div>
              <div>
                {seg.items.map((item, i) => {
                  const d = p[seg.id]?.[i];
                  return (
                    <div key={i} style={{
                      display: 'grid',
                      gridTemplateColumns: seg.hasOcena ? '180px 1fr 60px' : '180px 1fr',
                      gap: 12,
                      padding: '10px 16px',
                      borderBottom: i < seg.items.length - 1 ? '1px solid var(--border)' : 'none',
                      alignItems: 'start'
                    }}>
                      <div style={{ fontSize: '0.82rem', fontWeight: 600, color: 'var(--text-secondary)', paddingTop: 2 }}>{item}</div>
                      <div style={{ fontSize: '0.82rem', color: d?.zapazanje ? 'var(--text-primary)' : 'var(--text-muted)', fontStyle: d?.zapazanje ? 'normal' : 'italic' }}>
                        {d?.zapazanje || '—'}
                      </div>
                      {seg.hasOcena && (
                        <div style={{ fontWeight: 700, fontSize: '1rem', color: scoreColor(d?.ocena), textAlign: 'center' }}>
                          {d?.ocena || '—'}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}

        {(p.prostorZaNapredak || p.opstiZakljucak || p.ciljZaNaredniPeriod) && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12, marginTop: 4 }}>
            {[
              { key: 'prostorZaNapredak', label: '6. Prostor za napredak' },
              { key: 'opstiZakljucak', label: '7. Opšti zaključak' },
              { key: 'ciljZaNaredniPeriod', label: '8. Cilj za naredni period (2–3 nedelje)' }
            ].filter(x => p[x.key]).map(({ key, label }) => (
              <div key={key} style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', overflow: 'hidden' }}>
                <div style={{ padding: '10px 16px', borderBottom: '1px solid var(--border)', background: 'var(--bg-primary)', fontWeight: 700, fontSize: '0.9rem' }}>{label}</div>
                <div style={{ padding: '12px 16px', fontSize: '0.88rem', color: 'var(--text-secondary)', lineHeight: 1.6 }}>{p[key]}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  // Form view
  if (view === 'form') {
    return (
      <div>
        <div style={{ display: 'flex', gap: 10, marginBottom: 20, alignItems: 'center' }}>
          <button className="btn btn-secondary btn-sm" onClick={() => { handleSave(); }}>← Zatvori</button>
          <h3 style={{ margin: 0, flex: 1 }}>{editingId ? 'Uredi procenu' : 'Nova procena'}</h3>
          {saveStatus === 'saving' && <span style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>Čuvam...</span>}
          {saveStatus === 'saved' && <span style={{ fontSize: '0.78rem', color: '#22c55e' }}>✓ Sačuvano</span>}
        </div>

        {/* Header info */}
        <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: 16, marginBottom: 16 }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
            <div className="form-group" style={{ margin: 0 }}>
              <label className="label">Period procene</label>
              <input className="input" placeholder="npr. 15.01 – 05.02" value={form.period}
                onChange={e => setTopField('period', e.target.value)} />
            </div>
            <div className="form-group" style={{ margin: 0 }}>
              <label className="label">Broj treninga / utakmica</label>
              <input className="input" placeholder="npr. 12" value={form.trainingCount}
                onChange={e => setTopField('trainingCount', e.target.value)} />
            </div>
          </div>
        </div>

        {/* Segments 1-5 */}
        {SEGMENTS.map(seg => (
          <div key={seg.id} style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', marginBottom: 12, overflow: 'hidden' }}>
            <div style={{
              padding: '12px 16px',
              borderBottom: '1px solid var(--border)',
              background: 'var(--bg-primary)',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}>
              <span style={{ fontWeight: 700, fontSize: '0.9rem' }}>{seg.label}</span>
              {seg.hasOcena && (() => {
                const avg = segmentAvg(form, seg);
                return avg ? <span style={{ fontWeight: 700, fontSize: '0.9rem', color: scoreColor(avg) }}>⌀ {avg}</span> : null;
              })()}
            </div>

            {/* Column headers */}
            <div style={{
              display: 'grid',
              gridTemplateColumns: seg.hasOcena ? '180px 1fr 100px' : '180px 1fr',
              gap: 12,
              padding: '6px 16px',
              borderBottom: '1px solid var(--border)',
              background: 'rgba(255,255,255,0.02)'
            }}>
              <div style={{ fontSize: '0.7rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase' }}>Stavka</div>
              <div style={{ fontSize: '0.7rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase' }}>Zapažanje</div>
              {seg.hasOcena && <div style={{ fontSize: '0.7rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', textAlign: 'center' }}>Ocena (1–10)</div>}
            </div>

            {seg.items.map((item, i) => {
              const data = form[seg.id][i];
              return (
                <div key={i} style={{
                  display: 'grid',
                  gridTemplateColumns: seg.hasOcena ? '180px 1fr 100px' : '180px 1fr',
                  gap: 12,
                  padding: '10px 16px',
                  borderBottom: i < seg.items.length - 1 ? '1px solid var(--border)' : 'none',
                  alignItems: 'center'
                }}>
                  <div style={{ fontSize: '0.82rem', fontWeight: 600, color: 'var(--text-secondary)' }}>{item}</div>
                  <textarea
                    rows={2}
                    className="input"
                    style={{ fontSize: '0.82rem', resize: 'vertical', padding: '6px 10px' }}
                    placeholder="Zapažanje..."
                    value={data.zapazanje}
                    onChange={e => setSegItem(seg.id, i, 'zapazanje', e.target.value)}
                  />
                  {seg.hasOcena && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 4, justifyContent: 'center' }}>
                      <button
                        onClick={() => setOcena(seg.id, i, -1)}
                        style={{ background: 'var(--bg-primary)', border: '1px solid var(--border)', borderRadius: 4, width: 26, height: 26, cursor: 'pointer', color: 'var(--text-secondary)', fontSize: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                      >−</button>
                      <div style={{
                        width: 36, textAlign: 'center',
                        fontFamily: 'monospace',
                        fontSize: '1rem',
                        fontWeight: 700,
                        color: scoreColor(data.ocena)
                      }}>
                        {data.ocena || '—'}
                      </div>
                      <button
                        onClick={() => setOcena(seg.id, i, 1)}
                        style={{ background: 'var(--bg-primary)', border: '1px solid var(--border)', borderRadius: 4, width: 26, height: 26, cursor: 'pointer', color: 'var(--text-secondary)', fontSize: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                      >+</button>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        ))}

        {/* Segments 6-8: text */}
        {[
          { key: 'prostorZaNapredak', label: '6. Prostor za napredak' },
          { key: 'opstiZakljucak', label: '7. Opšti zaključak' },
          { key: 'ciljZaNaredniPeriod', label: '8. Cilj za naredni period (2–3 nedelje)' }
        ].map(({ key, label }) => (
          <div key={key} style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', marginBottom: 12, overflow: 'hidden' }}>
            <div style={{ padding: '10px 16px', borderBottom: '1px solid var(--border)', background: 'var(--bg-primary)', fontWeight: 700, fontSize: '0.9rem' }}>{label}</div>
            <div style={{ padding: 12 }}>
              <textarea
                rows={3}
                className="input"
                style={{ resize: 'vertical' }}
                placeholder="Upiši..."
                value={form[key]}
                onChange={e => setTopField(key, e.target.value)}
              />
            </div>
          </div>
        ))}

        <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: 8 }}>
          <button className="btn btn-secondary" onClick={handleSave}>← Zatvori procenu</button>
        </div>
      </div>
    );
  }

  // List view
  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
        <h3 style={{ margin: 0 }}>Procene igrača</h3>
        <button className="btn btn-primary btn-sm" onClick={openNew}>+ Nova procena</button>
      </div>

      {procenas.length === 0 ? (
        <div style={{
          padding: '40px 20px',
          textAlign: 'center',
          color: 'var(--text-muted)',
          fontSize: '0.88rem',
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius-lg)'
        }}>
          <div style={{ fontSize: '2rem', marginBottom: 12 }}>📋</div>
          Nema procena za ovog igrača.
          <br />
          <button className="btn btn-primary btn-sm" onClick={openNew} style={{ marginTop: 16 }}>
            Dodaj prvu procenu
          </button>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {procenas.map(p => {
            const avgs = SEGMENTS.filter(s => s.hasOcena).map(s => ({
              label: s.label.split('.')[1]?.trim().split(' ')[0],
              val: segmentAvg(formFromProcena(p), s)
            })).filter(x => x.val);

            return (
              <div
                key={p.id}
                onClick={() => openDetail(p)}
                style={{
                  background: 'var(--bg-card)',
                  border: '1px solid var(--border)',
                  borderRadius: 'var(--radius)',
                  padding: '14px 18px',
                  cursor: 'pointer',
                  transition: 'border-color 0.15s'
                }}
                onMouseEnter={e => e.currentTarget.style.borderColor = 'rgba(37,99,235,0.4)'}
                onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 8 }}>
                  <div>
                    <div style={{ fontWeight: 700, fontSize: '0.9rem', marginBottom: 2 }}>
                      {p.period || formatDate(p.createdAt)}
                    </div>
                    <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                      {formatDate(p.createdAt)}
                      {p.trainingCount && ` · ${p.trainingCount} treninga/utakmica`}
                    </div>
                  </div>
                  <div style={{ display: 'flex', gap: 6 }}>
                    <button
                      onClick={e => { e.stopPropagation(); openEdit(p); }}
                      style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)', fontSize: '0.85rem', padding: '2px 6px' }}
                    >✏</button>
                    <button
                      onClick={e => handleDelete(p.id, e)}
                      style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--error)', fontSize: '0.85rem', padding: '2px 6px' }}
                    >✕</button>
                  </div>
                </div>
                {avgs.length > 0 && (
                  <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                    {avgs.map(({ label, val }) => (
                      <div key={label} style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                        <span style={{ fontSize: '0.72rem', color: 'var(--text-muted)' }}>{label}</span>
                        <span style={{ fontSize: '0.85rem', fontWeight: 700, color: scoreColor(val) }}>{val}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
