import React from 'react';
import { useAuth } from '../../auth/AuthContext';
import { useMyPlayer } from '../../hooks/useMyPlayer';

const MONTHS = ['Januar', 'Februar', 'Mart', 'April', 'Maj', 'Jun', 'Jul', 'Avgust', 'Septembar', 'Oktobar', 'Novembar', 'Decembar'];

const STATUS_STYLE = {
  paid:    { background: 'rgba(34,197,94,0.15)',  color: '#22c55e', border: '1px solid rgba(34,197,94,0.3)',  label: '✓ Plaćeno' },
  pending: { background: 'rgba(245,158,11,0.15)', color: '#f59e0b', border: '1px solid rgba(245,158,11,0.3)', label: '~ Na čekanju' },
  unpaid:  { background: 'rgba(239,68,68,0.1)',   color: '#ef4444', border: '1px solid rgba(239,68,68,0.25)', label: '✗ Nije plaćeno' },
};

export default function PlayerClanarina() {
  const { playerId } = useAuth();
  const { player, loading } = useMyPlayer(playerId);

  if (loading) return <div style={{ textAlign: 'center', padding: 20, color: 'var(--text-muted)' }}>Učitavam...</div>;
  if (!player) return null;

  const currentYear = new Date().getFullYear();
  const currentMonth = new Date().getMonth();
  const price = player.monthlyPrice || 0;

  const months = MONTHS.map((name, idx) => {
    const payment = player.payments?.[currentYear]?.[idx];
    const status = payment?.status || 'unpaid';
    return { name, idx, status, amount: payment?.amount || price };
  });

  const paidCount = months.filter(m => m.status === 'paid').length;
  const unpaidMonths = months.filter(m => m.idx <= currentMonth && m.status !== 'paid');
  const totalDebt = unpaidMonths.reduce((s, m) => s + (price || m.amount), 0);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <h1 style={{ fontSize: '1.15rem', fontWeight: 700, margin: 0 }}>💳 Članarina</h1>

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 10 }}>
        {[
          { label: 'Mesečna', val: price ? `${price} RSD` : '—' },
          { label: 'Plaćeno', val: `${paidCount}/12` },
          { label: 'Dug', val: totalDebt > 0 ? `${totalDebt} RSD` : '0' },
        ].map(s => (
          <div key={s.label} style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: '12px 10px', textAlign: 'center' }}>
            <div style={{ fontWeight: 700, fontSize: '0.95rem', color: s.label === 'Dug' && totalDebt > 0 ? '#ef4444' : 'var(--gold)' }}>{s.val}</div>
            <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: 2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* Unpaid alert */}
      {unpaidMonths.length > 0 && (
        <div style={{ background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.25)', borderRadius: 'var(--radius)', padding: '12px 14px' }}>
          <div style={{ fontWeight: 700, fontSize: '0.88rem', color: '#ef4444', marginBottom: 4 }}>⚠️ Neplaćeni meseci</div>
          <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)' }}>
            {unpaidMonths.map(m => m.name).join(', ')}
          </div>
          {totalDebt > 0 && (
            <div style={{ fontSize: '0.82rem', color: '#ef4444', marginTop: 6, fontWeight: 600 }}>
              Ukupno dugovanje: {totalDebt} RSD
            </div>
          )}
        </div>
      )}

      {/* Monthly list */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {months.map(m => {
          const style = STATUS_STYLE[m.status] || STATUS_STYLE.unpaid;
          const isFuture = m.idx > currentMonth;
          return (
            <div
              key={m.idx}
              style={{
                background: isFuture ? 'transparent' : style.background,
                border: isFuture ? '1px solid var(--border)' : style.border,
                borderRadius: 'var(--radius-sm)',
                padding: '10px 14px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                opacity: isFuture ? 0.45 : 1
              }}
            >
              <span style={{ fontSize: '0.88rem', fontWeight: m.idx === currentMonth ? 700 : 400 }}>
                {m.idx === currentMonth && '→ '}{m.name}
              </span>
              <span style={{ fontSize: '0.78rem', fontWeight: 600, color: isFuture ? 'var(--text-muted)' : style.color }}>
                {isFuture ? '—' : style.label}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}
