import React, { useState } from 'react';
import { useAuth } from '../../auth/AuthContext';
import { useMyPlayer } from '../../hooks/useMyPlayer';
import { usePlayerProcena, usePlayerAnalize } from '../../hooks/usePlayerExtras';
import { formatDate } from '../../utils/helpers';

const TABS = [
  { id: 'dolasci', label: 'Dolasci' },
  { id: 'napomene', label: 'Napomene' },
  { id: 'procena', label: 'Procena' },
  { id: 'analiza', label: 'Analiza' },
];

function AttendanceTab({ player }) {
  const attendances = player?.attendances
    ? Object.values(player.attendances).sort((a, b) => (b.date || '').localeCompare(a.date || ''))
    : [];
  const total = attendances.length;
  const present = attendances.filter(a => a.present === true).length;
  const pct = total > 0 ? Math.round((present / total) * 100) : 0;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 8, marginBottom: 8 }}>
        {[
          { label: 'Ukupno', val: total },
          { label: 'Prisutan', val: present },
          { label: 'Prisutnost', val: `${pct}%` },
        ].map(s => (
          <div key={s.label} style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius)',
            padding: '10px',
            textAlign: 'center'
          }}>
            <div style={{ fontWeight: 700, fontSize: '1.2rem', color: 'var(--gold)' }}>{s.val}</div>
            <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: 2 }}>{s.label}</div>
          </div>
        ))}
      </div>
      {attendances.slice(0, 30).map((a, i) => (
        <div key={i} style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius-sm)',
          padding: '8px 12px',
          fontSize: '0.85rem'
        }}>
          <span>{formatDate(a.date)}</span>
          <span style={{ fontWeight: 600, color: a.present === true ? 'var(--success)' : a.present === false ? 'var(--error)' : 'var(--text-muted)' }}>
            {a.present === true ? '✓ Prisutan' : a.present === false ? '✗ Odsutan' : '—'}
          </span>
        </div>
      ))}
      {attendances.length === 0 && (
        <div style={{ textAlign: 'center', color: 'var(--text-muted)', padding: 20 }}>Nema evidencije dolazaka</div>
      )}
    </div>
  );
}

function NotesTab({ player }) {
  const notes = player?.trainingNotes
    ? Object.values(player.trainingNotes).sort((a, b) => b.createdAt.localeCompare(a.createdAt))
    : [];
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      {notes.length === 0 ? (
        <div style={{ textAlign: 'center', color: 'var(--text-muted)', padding: 20 }}>Nema napomena</div>
      ) : notes.map((n, i) => (
        <div key={i} style={{
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius)',
          padding: '12px 14px'
        }}>
          <div style={{ fontSize: '0.85rem', lineHeight: 1.5 }}>{n.note || n.text || '—'}</div>
          <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginTop: 6 }}>
            {formatDate(n.createdAt)}
          </div>
        </div>
      ))}
    </div>
  );
}

function ProcenaTab({ playerId }) {
  const { procenas, loading } = usePlayerProcena(playerId);
  if (loading) return <div style={{ textAlign: 'center', color: 'var(--text-muted)', padding: 20 }}>Učitavam...</div>;
  if (procenas.length === 0) return <div style={{ textAlign: 'center', color: 'var(--text-muted)', padding: 20 }}>Nema procena</div>;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      {procenas.map(p => (
        <div key={p.id} style={{
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius)',
          padding: '14px'
        }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
            <span style={{ fontWeight: 600, fontSize: '0.9rem' }}>Procena</span>
            <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>{formatDate(p.createdAt)}</span>
          </div>
          {p.segments && p.segments.map((seg, i) => (
            <div key={i} style={{ marginBottom: 8 }}>
              <div style={{ fontSize: '0.8rem', fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 4 }}>{seg.title || `Segment ${i + 1}`}</div>
              {seg.items && Object.entries(seg.items).map(([k, v]) => (
                <div key={k} style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.82rem', padding: '2px 0', borderBottom: '1px solid var(--border)' }}>
                  <span style={{ color: 'var(--text-secondary)' }}>{k}</span>
                  <span style={{ fontWeight: 600 }}>{v}/10</span>
                </div>
              ))}
            </div>
          ))}
          {p.generalNote && (
            <div style={{ fontSize: '0.82rem', color: 'var(--text-muted)', marginTop: 8, fontStyle: 'italic' }}>{p.generalNote}</div>
          )}
        </div>
      ))}
    </div>
  );
}

function AnalizaTab({ playerId }) {
  const { analize, loading } = usePlayerAnalize(playerId);
  const [open, setOpen] = useState(null);
  if (loading) return <div style={{ textAlign: 'center', color: 'var(--text-muted)', padding: 20 }}>Učitavam...</div>;
  if (analize.length === 0) return <div style={{ textAlign: 'center', color: 'var(--text-muted)', padding: 20 }}>Nema analiza</div>;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      {analize.map(a => {
        const isUtakmica = a.type?.toLowerCase().includes('utakmic') || a.type?.toLowerCase().includes('meč');
        const typeColor = isUtakmica ? '#f97316' : '#3b82f6';
        return (
        <div key={a.id} style={{ background: 'var(--bg-card)', border: `1px solid var(--border)`, borderRadius: 'var(--radius)', overflow: 'hidden' }}>
          <div
            onClick={() => setOpen(open === a.id ? null : a.id)}
            style={{ padding: '12px 14px', cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}
          >
            <div>
              <div style={{ fontWeight: 700, fontSize: '0.9rem', color: typeColor }}>{a.title || 'Analiza'}</div>
              <div style={{ fontSize: '0.75rem', marginTop: 2 }}>
                {a.type && <span style={{ color: typeColor, fontWeight: 600 }}>{a.type} • </span>}
                <span style={{ color: 'var(--text-muted)' }}>{formatDate(a.date || a.createdAt)}</span>
              </div>
            </div>
            <span style={{ color: 'var(--text-muted)', fontSize: '0.9rem' }}>{open === a.id ? '▲' : '▼'}</span>
          </div>
          {open === a.id && (
            <div style={{ padding: '0 14px 14px', borderTop: '1px solid var(--border)' }}>
              {a.text && <p style={{ fontSize: '0.85rem', lineHeight: 1.6, marginTop: 10 }}>{a.text}</p>}
              {a.videoUrl && (
                <a href={a.videoUrl} target="_blank" rel="noopener noreferrer" style={{ display: 'inline-flex', alignItems: 'center', gap: 6, color: 'var(--gold)', fontSize: '0.85rem', marginTop: 8 }}>
                  🎬 Pogledaj video
                </a>
              )}
              {(a.images?.length > 0 || a.imageBase64) && (
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 10 }}>
                  {(a.images || (a.imageBase64 ? [a.imageBase64] : [])).map((img, i) => (
                    <img key={i} src={img} alt="" style={{ width: 100, height: 76, objectFit: 'cover', borderRadius: 6, border: '1px solid var(--border)' }} />
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
        );
      })}
    </div>
  );
}

export default function PlayerNapredak() {
  const { playerId } = useAuth();
  const { player, loading } = useMyPlayer(playerId);
  const [tab, setTab] = useState('dolasci');

  if (loading) return <div style={{ textAlign: 'center', padding: 20, color: 'var(--text-muted)' }}>Učitavam...</div>;

  return (
    <div>
      <h1 style={{ fontSize: '1.15rem', fontWeight: 700, marginBottom: 16 }}>📊 Moj napredak</h1>

      <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', marginBottom: 16 }}>
        {TABS.map(t => (
          <button
            key={t.id}
            onClick={() => setTab(t.id)}
            style={{
              padding: '5px 14px',
              borderRadius: 20,
              border: '1px solid',
              borderColor: tab === t.id ? 'var(--gold)' : 'var(--border)',
              background: tab === t.id ? 'rgba(37,99,235,0.15)' : 'transparent',
              color: tab === t.id ? 'var(--gold)' : 'var(--text-muted)',
              fontSize: '0.82rem',
              fontWeight: 600,
              cursor: 'pointer'
            }}
          >
            {t.label}
          </button>
        ))}
      </div>

      {tab === 'dolasci' && <AttendanceTab player={player} />}
      {tab === 'napomene' && <NotesTab player={player} />}
      {tab === 'procena' && <ProcenaTab playerId={playerId} />}
      {tab === 'analiza' && <AnalizaTab playerId={playerId} />}
    </div>
  );
}
