import React, { useState } from 'react';
import { usePlayers } from '../../../hooks/usePlayers';
import Modal from '../../../components/common/Modal';
import { formatDate } from '../../../utils/helpers';

function StarRating({ value, onChange, max = 5 }) {
  return (
    <div style={{ display: 'flex', gap: 4 }}>
      {Array.from({ length: max }, (_, i) => i + 1).map(star => (
        <button
          key={star}
          type="button"
          onClick={() => onChange && onChange(star)}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.3rem',
            cursor: onChange ? 'pointer' : 'default',
            color: star <= value ? '#3b82f6' : '#3a3a3a',
            padding: '0 2px',
            transition: 'color 0.15s ease'
          }}
        >
          ★
        </button>
      ))}
    </div>
  );
}

export default function Notes({ player }) {
  const { addTrainingNote, updateTrainingNote, deleteTrainingNote } = usePlayers();
  const [isOpen, setIsOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    date: new Date().toISOString().split('T')[0],
    engagement: 3,
    execution: 3,
    note: ''
  });

  const notes = player.trainingNotes
    ? Object.entries(player.trainingNotes)
        .map(([id, v]) => ({ id, ...v }))
        .sort((a, b) => new Date(b.date) - new Date(a.date))
    : [];

  const openAdd = () => {
    setEditingId(null);
    setForm({ date: new Date().toISOString().split('T')[0], engagement: 3, execution: 3, note: '' });
    setIsOpen(true);
  };

  const openEdit = (note) => {
    setEditingId(note.id);
    setForm({ date: note.date, engagement: note.engagement, execution: note.execution, note: note.note || '' });
    setIsOpen(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) {
        await updateTrainingNote(player.id, editingId, form);
      } else {
        await addTrainingNote(player.id, form);
      }
      setIsOpen(false);
      setEditingId(null);
      setForm({ date: new Date().toISOString().split('T')[0], engagement: 3, execution: 3, note: '' });
    } catch (err) {
      console.error(err);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (noteId) => {
    if (!window.confirm('Obrisati ovu napomenu?')) return;
    try {
      await deleteTrainingNote(player.id, noteId);
    } catch (err) {
      console.error(err);
    }
  };

  const getAvgColor = (engagement, execution) => {
    const avg = (engagement + execution) / 2;
    if (avg >= 4) return { bg: 'rgba(34,197,94,0.08)', border: 'rgba(34,197,94,0.2)', left: '#22c55e' };
    if (avg >= 3) return { bg: 'rgba(37,99,235,0.08)', border: 'rgba(37,99,235,0.2)', left: '#3b82f6' };
    return { bg: 'rgba(239,68,68,0.07)', border: 'rgba(239,68,68,0.2)', left: '#ef4444' };
  };

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
        <h3>Napomene sa treninga</h3>
        <button className="btn btn-primary btn-sm" onClick={openAdd}>
          + Dodaj napomenu
        </button>
      </div>

      {notes.length === 0 ? (
        <div className="empty-state">
          <div className="empty-state-icon">📝</div>
          <div className="empty-state-title">Nema napomena</div>
          <p className="empty-state-text">Dodaj napomenu posle svakog treninga da pratiš razvoj igrača.</p>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {notes.map(note => {
            const colors = getAvgColor(note.engagement, note.execution);
            return (
              <div key={note.id} style={{
                background: colors.bg,
                border: `1px solid ${colors.border}`,
                borderLeft: `3px solid ${colors.left}`,
                borderRadius: 'var(--radius)',
                padding: '16px',
                position: 'relative'
              }}>
                {/* Header */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12 }}>
                  <div style={{ fontWeight: 700, color: 'var(--text-primary)', fontSize: '0.9rem' }}>
                    📅 {formatDate(note.date)}
                  </div>
                  <div style={{ display: 'flex', gap: 4 }}>
                    <button
                      onClick={() => openEdit(note)}
                      style={{ background: 'transparent', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: '0.85rem', padding: '2px 6px' }}
                      title="Izmeni"
                    >
                      ✏️
                    </button>
                    <button
                      onClick={() => handleDelete(note.id)}
                      style={{ background: 'transparent', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: '0.9rem', padding: '2px 4px' }}
                      title="Obriši"
                    >
                      ✕
                    </button>
                  </div>
                </div>

                {/* Ratings */}
                <div style={{ display: 'flex', gap: 24, marginBottom: 10 }}>
                  <div>
                    <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginBottom: 3 }}>
                      ANGAŽOVANOST
                    </div>
                    <StarRating value={note.engagement} max={5} />
                  </div>
                  <div>
                    <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginBottom: 3 }}>
                      KVALITET IZVOĐENJA
                    </div>
                    <StarRating value={note.execution} max={5} />
                  </div>
                  <div style={{ marginLeft: 'auto', textAlign: 'right' }}>
                    <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginBottom: 3 }}>
                      PROSEK
                    </div>
                    <div style={{
                      fontSize: '1.1rem',
                      fontWeight: 800,
                      color: colors.left
                    }}>
                      {((note.engagement + note.execution) / 2).toFixed(1)}
                    </div>
                  </div>
                </div>

                {/* Note text */}
                {note.note && (
                  <div style={{
                    background: 'rgba(0,0,0,0.2)',
                    borderRadius: 6,
                    padding: '10px 12px',
                    fontSize: '0.875rem',
                    color: 'var(--text-secondary)',
                    lineHeight: 1.6
                  }}>
                    {note.note}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Modal */}
      <Modal
        isOpen={isOpen}
        onClose={() => { setIsOpen(false); setEditingId(null); }}
        title={editingId ? 'Izmeni napomenu' : 'Dodaj napomenu sa treninga'}
        width={460}
        footer={
          <>
            <button className="btn btn-secondary" onClick={() => setIsOpen(false)}>Otkaži</button>
            <button className="btn btn-primary" onClick={handleSubmit} disabled={saving}>
              {saving ? 'Čuvam...' : editingId ? 'Sačuvaj izmene' : 'Sačuvaj napomenu'}
            </button>
          </>
        }
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div className="form-group">
            <label className="label">Datum treninga</label>
            <input
              type="date"
              className="input"
              value={form.date}
              onChange={e => setForm(p => ({ ...p, date: e.target.value }))}
            />
          </div>

          <div className="form-group">
            <label className="label">Angažovanost</label>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <StarRating
                value={form.engagement}
                onChange={v => setForm(p => ({ ...p, engagement: v }))}
                max={5}
              />
              <span style={{ color: 'var(--text-muted)', fontSize: '0.85rem' }}>
                {['', 'Minimalna', 'Slaba', 'Prosječna', 'Dobra', 'Odlična'][form.engagement]}
              </span>
            </div>
          </div>

          <div className="form-group">
            <label className="label">Kvalitet izvođenja</label>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <StarRating
                value={form.execution}
                onChange={v => setForm(p => ({ ...p, execution: v }))}
                max={5}
              />
              <span style={{ color: 'var(--text-muted)', fontSize: '0.85rem' }}>
                {['', 'Minimalno', 'Slabo', 'Prosječno', 'Dobro', 'Odlično'][form.execution]}
              </span>
            </div>
          </div>

          <div className="form-group">
            <label className="label">Slobodna napomena</label>
            <textarea
              className="input"
              rows={4}
              placeholder="Kako je igrač izgledao na treningu? Šta je dobro uradio? Šta treba poboljšati?..."
              value={form.note}
              onChange={e => setForm(p => ({ ...p, note: e.target.value }))}
            />
          </div>
        </div>
      </Modal>
    </div>
  );
}
