import React, { useState } from 'react';
import { usePlayerAnalize } from '../../../hooks/usePlayerExtras';
import {
  getDaysInMonth, getFirstDayOfWeek, getMonthName,
  toDateKey, formatDate, DAYS_SHORT
} from '../../../utils/helpers';

const TYPE_OPTIONS = [
  { value: 'trening', label: 'Trening' },
  { value: 'utakmica', label: 'Utakmica' }
];

const TYPE_COLORS = {
  trening: { bg: 'rgba(37,99,235,0.15)', border: 'rgba(37,99,235,0.35)', text: '#60a5fa' },
  utakmica: { bg: 'rgba(245,158,11,0.15)', border: 'rgba(245,158,11,0.35)', text: '#f59e0b' }
};

async function compressImage(file, maxWidth = 900, quality = 0.75) {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let { width, height } = img;
        if (width > maxWidth) { height = Math.round(height * maxWidth / width); width = maxWidth; }
        const canvas = document.createElement('canvas');
        canvas.width = width; canvas.height = height;
        canvas.getContext('2d').drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', quality));
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}

function emptyModal(dateKey) {
  return { type: 'trening', title: '', text: '', images: [], videoUrl: '', date: dateKey || toDateKey(new Date()) };
}

export default function Analiza({ player }) {
  const { analize, loading, addAnaliza, deleteAnaliza } = usePlayerAnalize(player.id);

  const now = new Date();
  const [year, setYear] = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth());
  const [selectedDay, setSelectedDay] = useState(toDateKey(now));
  const [calView, setCalView] = useState(true); // calendar vs list
  const [listSort, setListSort] = useState('desc'); // newest first
  const [modal, setModal] = useState(null); // null | form data
  const [saving, setSaving] = useState(false);
  const [imgLoading, setImgLoading] = useState(false);
  const imgInputRef = React.useRef(null);
  const [expandedId, setExpandedId] = useState(null);

  const today = toDateKey(now);
  const days = getDaysInMonth(year, month);
  const firstDayOfWeek = getFirstDayOfWeek(year, month);

  const prevMonth = () => { if (month === 0) { setMonth(11); setYear(y => y - 1); } else setMonth(m => m - 1); };
  const nextMonth = () => { if (month === 11) { setMonth(0); setYear(y => y + 1); } else setMonth(m => m + 1); };

  const getAnalizeForDay = (dateKey) => analize.filter(a => a.date === dateKey);
  const selectedAnalize = selectedDay ? getAnalizeForDay(selectedDay) : [];

  const handleSave = async () => {
    if (!modal.title.trim()) return;
    setSaving(true);
    try {
      await addAnaliza(modal);
      setModal(null);
    } catch (e) { console.error(e); }
    finally { setSaving(false); }
  };

  const handleDelete = async (id, e) => {
    e.stopPropagation();
    if (!window.confirm('Obrisati analizu?')) return;
    await deleteAnaliza(id);
    if (expandedId === id) setExpandedId(null);
  };

  const handleImage = async (e) => {
    const files = Array.from(e.target.files);
    if (!files.length) return;
    setImgLoading(true);
    try {
      const compressed = await Promise.all(files.map(f => compressImage(f)));
      setModal(prev => ({ ...prev, images: [...(prev.images || []), ...compressed] }));
    } catch (err) { console.error(err); }
    finally { setImgLoading(false); if (imgInputRef.current) imgInputRef.current.value = ''; }
  };

  const removeImage = (idx) => {
    setModal(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== idx) }));
  };

  const sortedList = listSort === 'desc' ? [...analize] : [...analize].sort((a, b) => a.date.localeCompare(b.date));

  if (loading) return <div style={{ padding: 20, color: 'var(--text-muted)', fontSize: '0.85rem' }}>Učitavam...</div>;

  return (
    <div>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <h3 style={{ margin: 0 }}>Analize ({analize.length})</h3>
        <div style={{ display: 'flex', gap: 8 }}>
          <button
            className="btn btn-secondary btn-sm"
            onClick={() => setCalView(v => !v)}
          >
            {calView ? '☰ Lista' : '📅 Kalendar'}
          </button>
          <button className="btn btn-primary btn-sm" onClick={() => setModal(emptyModal(selectedDay))}>
            + Dodaj analizu
          </button>
        </div>
      </div>

      {/* Calendar view */}
      {calView ? (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 260px', gap: 16 }}>
          {/* Calendar */}
          <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', overflow: 'hidden' }}>
            {/* Month nav */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '12px 16px', borderBottom: '1px solid var(--border)' }}>
              <button className="btn btn-secondary btn-sm btn-icon" onClick={prevMonth}>‹</button>
              <div style={{ flex: 1, textAlign: 'center', fontWeight: 700, fontSize: '0.95rem' }}>
                {getMonthName(month)} {year}
              </div>
              <button className="btn btn-secondary btn-sm btn-icon" onClick={nextMonth}>›</button>
            </div>

            {/* Day headers */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', background: 'var(--bg-primary)', borderBottom: '1px solid var(--border)' }}>
              {DAYS_SHORT.map(d => (
                <div key={d} style={{ padding: '8px 2px', textAlign: 'center', fontSize: '0.68rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase' }}>{d}</div>
              ))}
            </div>

            {/* Days */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 1, background: 'var(--border)' }}>
              {Array.from({ length: firstDayOfWeek }).map((_, i) => (
                <div key={`e-${i}`} style={{ background: 'var(--bg-card)', minHeight: 64 }} />
              ))}
              {days.map(day => {
                const dateKey = toDateKey(day);
                const dayAnalize = getAnalizeForDay(dateKey);
                const isToday = dateKey === today;
                const isSelected = dateKey === selectedDay;
                return (
                  <div
                    key={dateKey}
                    onClick={() => setSelectedDay(dateKey)}
                    style={{
                      background: isSelected ? 'rgba(37,99,235,0.14)' : isToday ? 'rgba(37,99,235,0.05)' : 'var(--bg-card)',
                      minHeight: 64,
                      padding: '6px',
                      cursor: 'pointer',
                      transition: 'background 0.12s',
                      borderTop: isToday ? '2px solid var(--gold)' : isSelected ? '2px solid var(--gold)' : '2px solid transparent'
                    }}
                    onMouseEnter={e => { if (!isSelected) e.currentTarget.style.background = 'rgba(255,255,255,0.04)'; }}
                    onMouseLeave={e => { if (!isSelected) e.currentTarget.style.background = isToday ? 'rgba(37,99,235,0.05)' : 'var(--bg-card)'; }}
                  >
                    <div style={{ fontSize: '0.8rem', fontWeight: isToday || isSelected ? 800 : 400, color: isToday || isSelected ? 'var(--gold)' : 'var(--text-secondary)', marginBottom: 4 }}>
                      {day.getDate()}
                    </div>
                    <div style={{ display: 'flex', gap: 3, flexWrap: 'wrap' }}>
                      {dayAnalize.map(a => {
                        const c = TYPE_COLORS[a.type] || TYPE_COLORS.trening;
                        return (
                          <div key={a.id} style={{
                            width: 8, height: 8, borderRadius: '50%',
                            background: c.text, flexShrink: 0
                          }} />
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Legend */}
            <div style={{ display: 'flex', gap: 16, padding: '8px 16px', borderTop: '1px solid var(--border)', fontSize: '0.72rem', color: 'var(--text-muted)' }}>
              <span style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                <span style={{ width: 8, height: 8, borderRadius: '50%', background: '#60a5fa', display: 'inline-block' }} /> Trening
              </span>
              <span style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                <span style={{ width: 8, height: 8, borderRadius: '50%', background: '#f59e0b', display: 'inline-block' }} /> Utakmica
              </span>
            </div>
          </div>

          {/* Day panel */}
          <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
            <div style={{ padding: '12px 14px', borderBottom: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ fontWeight: 700, fontSize: '0.85rem', color: selectedDay === today ? 'var(--gold)' : 'var(--text-primary)' }}>
                {selectedDay ? formatDate(selectedDay) : 'Izaberi dan'}
              </div>
              <button
                className="btn btn-primary btn-sm"
                style={{ fontSize: '0.72rem', padding: '3px 10px' }}
                onClick={() => setModal(emptyModal(selectedDay))}
              >+ Dodaj</button>
            </div>

            <div style={{ flex: 1, overflowY: 'auto', padding: 10 }}>
              {selectedAnalize.length === 0 ? (
                <div style={{ padding: '20px 0', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.82rem' }}>
                  Nema analiza ovog dana.
                </div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {selectedAnalize.map(a => <AnalizaCard key={a.id} a={a} onDelete={handleDelete} />)}
                </div>
              )}
            </div>
          </div>
        </div>
      ) : (
        /* List view */
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>
            <span style={{ fontSize: '0.82rem', color: 'var(--text-muted)' }}>Sortiraj:</span>
            <button
              className="btn btn-sm"
              onClick={() => setListSort(s => s === 'desc' ? 'asc' : 'desc')}
              style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', color: 'var(--text-secondary)', padding: '4px 12px', fontSize: '0.78rem', borderRadius: 6, cursor: 'pointer' }}
            >
              {listSort === 'desc' ? '↓ Najnovije' : '↑ Najstarije'}
            </button>
          </div>
          {sortedList.length === 0 ? (
            <div style={{ padding: '40px 20px', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.88rem', background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)' }}>
              <div style={{ fontSize: '2rem', marginBottom: 12 }}>📊</div>
              Nema analiza. Dodaj prvu!
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {sortedList.map(a => <AnalizaCard key={a.id} a={a} onDelete={handleDelete} showDate />)}
            </div>
          )}
        </div>
      )}

      {/* Add modal */}
      {modal && (
        <div style={{
          position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          zIndex: 1000, padding: 16
        }} onClick={e => e.target === e.currentTarget && setModal(null)}>
          <div style={{
            background: 'var(--bg-card)', border: '1px solid var(--border)',
            borderRadius: 'var(--radius-lg)', width: '100%', maxWidth: 540,
            maxHeight: '90vh', overflow: 'auto', padding: 24
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <h3 style={{ margin: 0 }}>Nova analiza</h3>
              <button onClick={() => setModal(null)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)', fontSize: '1.2rem' }}>✕</button>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="label">Datum</label>
                  <input type="date" className="input" value={modal.date}
                    onChange={e => setModal(p => ({ ...p, date: e.target.value }))} />
                </div>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="label">Tip</label>
                  <select className="input" value={modal.type} onChange={e => setModal(p => ({ ...p, type: e.target.value }))}>
                    {TYPE_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                  </select>
                </div>
              </div>

              <div className="form-group" style={{ margin: 0 }}>
                <label className="label">Naslov *</label>
                <input className="input" placeholder="npr. Analiza utakmice vs. FK Partizan..." value={modal.title}
                  onChange={e => setModal(p => ({ ...p, title: e.target.value }))} />
              </div>

              <div className="form-group" style={{ margin: 0 }}>
                <label className="label">Tekst analize</label>
                <textarea className="input" rows={5} placeholder="Detaljna analiza..." value={modal.text}
                  onChange={e => setModal(p => ({ ...p, text: e.target.value }))}
                  style={{ resize: 'vertical' }} />
              </div>

              <div className="form-group" style={{ margin: 0 }}>
                <label className="label">Video link (opciono)</label>
                <input className="input" placeholder="https://youtube.com/..." value={modal.videoUrl || ''}
                  onChange={e => setModal(p => ({ ...p, videoUrl: e.target.value }))} />
              </div>

              <div className="form-group" style={{ margin: 0 }}>
                <label className="label">Slike ({(modal.images || []).length})</label>
                {(modal.images || []).length > 0 && (
                  <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 8 }}>
                    {(modal.images || []).map((img, idx) => (
                      <div key={idx} style={{ position: 'relative' }}>
                        <img src={img} alt="" style={{ width: 90, height: 70, objectFit: 'cover', borderRadius: 6, border: '1px solid var(--border)' }} />
                        <button onClick={() => removeImage(idx)}
                          style={{ position: 'absolute', top: 3, right: 3, background: 'rgba(0,0,0,0.65)', border: 'none', borderRadius: '50%', width: 20, height: 20, cursor: 'pointer', color: '#fff', fontSize: '0.65rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
                      </div>
                    ))}
                  </div>
                )}
                <label style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '9px 14px', border: '1px dashed var(--border)', borderRadius: 8, cursor: imgLoading ? 'wait' : 'pointer', color: 'var(--text-muted)', fontSize: '0.85rem' }}
                  onMouseEnter={e => e.currentTarget.style.borderColor = 'var(--gold)'}
                  onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}
                >
                  <input ref={imgInputRef} type="file" accept="image/*" multiple onChange={handleImage} style={{ display: 'none' }} disabled={imgLoading} />
                  <span style={{ fontSize: '1.1rem' }}>📷</span>
                  <span>{imgLoading ? 'Učitavam...' : '+ Dodaj slike'}</span>
                </label>
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 10, marginTop: 20 }}>
              <button className="btn btn-secondary" onClick={() => setModal(null)}>Otkaži</button>
              <button className="btn btn-primary" onClick={handleSave} disabled={saving || !modal.title.trim()}>
                {saving ? 'Čuvam...' : 'Sačuvaj analizu'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function AnalizaCard({ a, onDelete, showDate }) {
  const [expanded, setExpanded] = useState(false);
  const c = TYPE_COLORS[a.type] || TYPE_COLORS.trening;

  return (
    <div
      style={{
        background: 'var(--bg-primary)',
        border: '1px solid var(--border)',
        borderRadius: 8,
        overflow: 'hidden',
        transition: 'border-color 0.15s'
      }}
      onMouseEnter={e => e.currentTarget.style.borderColor = 'rgba(37,99,235,0.3)'}
      onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}
    >
      <div
        onClick={() => setExpanded(v => !v)}
        style={{ padding: '10px 14px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 10 }}
      >
        <span style={{ background: c.bg, border: `1px solid ${c.border}`, color: c.text, borderRadius: 4, padding: '1px 7px', fontSize: '0.68rem', fontWeight: 700, flexShrink: 0 }}>
          {a.type === 'trening' ? 'Trening' : 'Utakmica'}
        </span>
        <div style={{ flex: 1, overflow: 'hidden' }}>
          <div style={{ fontWeight: 600, fontSize: '0.85rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{a.title}</div>
          {showDate && <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>{formatDate(a.date)}</div>}
        </div>
        <span style={{ color: 'var(--text-muted)', fontSize: '0.75rem', flexShrink: 0 }}>{expanded ? '▲' : '▼'}</span>
        <button onClick={e => onDelete(a.id, e)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--error)', fontSize: '0.75rem', padding: '2px 4px', flexShrink: 0 }}>✕</button>
      </div>

      {expanded && (
        <div style={{ borderTop: '1px solid var(--border)', padding: '12px 14px' }}>
          {a.text && (
            <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', lineHeight: 1.65, whiteSpace: 'pre-wrap', marginBottom: 10 }}>
              {a.text}
            </div>
          )}
          {a.videoUrl && (
            <a href={a.videoUrl} target="_blank" rel="noopener noreferrer"
              style={{ display: 'inline-flex', alignItems: 'center', gap: 6, fontSize: '0.82rem', color: '#60a5fa', textDecoration: 'none', marginBottom: 10 }}>
              ▶ Video analiza
            </a>
          )}
          {/* backward compat: single imageBase64 */}
          {!a.images && a.imageBase64 && (
            <img src={a.imageBase64} alt="" style={{ width: '100%', maxHeight: 300, objectFit: 'cover', borderRadius: 6, border: '1px solid var(--border)' }} />
          )}
          {a.images && a.images.length > 0 && (
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              {a.images.map((img, i) => (
                <img key={i} src={img} alt="" style={{ width: '100%', maxWidth: 300, maxHeight: 220, objectFit: 'cover', borderRadius: 6, border: '1px solid var(--border)', flex: '1 1 200px' }} />
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
