import React, { useState, useRef, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useCoachNotifications } from '../../hooks/useNotifications';
import { useAuth } from '../../auth/AuthContext';

const pageTitles = {
  '/': 'Golmani',
  '/raspored': 'Raspored Treninga',
  '/vezbe': 'Moje Vežbe',
  '/napredak': 'Napredak Igrača',
  '/izvestaji': 'Izveštaji'
};

const TYPE_ICON = { player_rating: '⭐', training_note: '📝', procena: '📋', analiza: '🎬', new_training: '📅' };

function relTime(iso) {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return 'malopre';
  if (m < 60) return `pre ${m} min`;
  const h = Math.floor(m / 60);
  if (h < 24) return `pre ${h} h`;
  return `pre ${Math.floor(h / 24)} d`;
}

export default function Header({ onMenuClick }) {
  const location = useLocation();
  const navigate = useNavigate();
  const { userRole, logout } = useAuth();
  const { notifications, unreadCount, markRead, markAllRead } = useCoachNotifications();
  const [showNotifs, setShowNotifs] = useState(false);
  const dropRef = useRef(null);

  useEffect(() => {
    const handler = (e) => {
      if (dropRef.current && !dropRef.current.contains(e.target)) setShowNotifs(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const getTitle = () => {
    if (pageTitles[location.pathname]) return pageTitles[location.pathname];
    for (const [path, title] of Object.entries(pageTitles)) {
      if (location.pathname.startsWith(path) && path !== '/') return title;
    }
    return 'JEVRAGKlab';
  };

  const now = new Date();
  const dateStr = now.toLocaleDateString('sr-Latn-RS', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });

  const handleNotifClick = async (notif) => {
    await markRead(notif.id);
    setShowNotifs(false);
    const link = notif.link || '';
    if (link.startsWith('trening:')) navigate(`/trening/${link.replace('trening:', '')}`);
  };

  return (
    <header style={{
      height: 'var(--header-height)',
      borderBottom: '1px solid var(--border)',
      background: 'rgba(17, 17, 17, 0.8)',
      backdropFilter: 'blur(10px)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      padding: '0 24px',
      position: 'sticky',
      top: 0,
      zIndex: 90
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
        <button
          onClick={onMenuClick}
          className="hamburger-btn"
          style={{
            display: 'none',
            width: 36,
            height: 36,
            border: '1px solid var(--border)',
            borderRadius: 6,
            background: 'transparent',
            color: 'var(--text-secondary)',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'pointer',
            fontSize: '1.1rem'
          }}
        >
          ☰
        </button>

        <div>
          <h2 style={{ margin: 0, fontSize: '1.1rem', color: 'var(--text-primary)' }}>
            {getTitle()}
          </h2>
        </div>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
        <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: 8 }}>
          <span>📅</span>
          <span className="date-text">{dateStr}</span>
        </div>

        {/* Coach notification bell */}
        {userRole === 'coach' && (
          <div ref={dropRef} style={{ position: 'relative' }}>
            <button
              onClick={() => setShowNotifs(s => !s)}
              style={{
                position: 'relative',
                background: 'transparent',
                border: '1px solid var(--border)',
                borderRadius: 8,
                width: 36,
                height: 36,
                cursor: 'pointer',
                color: 'var(--text-secondary)',
                fontSize: '1.1rem',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}
            >
              🔔
              {unreadCount > 0 && (
                <span style={{
                  position: 'absolute',
                  top: -4,
                  right: -4,
                  background: 'var(--error)',
                  color: '#fff',
                  borderRadius: '50%',
                  width: 18,
                  height: 18,
                  fontSize: '0.6rem',
                  fontWeight: 700,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}>
                  {unreadCount > 9 ? '9+' : unreadCount}
                </span>
              )}
            </button>

            {showNotifs && (
              <div style={{
                position: 'absolute',
                top: 44,
                right: 0,
                width: 320,
                maxHeight: 400,
                overflowY: 'auto',
                background: 'var(--bg-card)',
                border: '1px solid var(--border)',
                borderRadius: 'var(--radius-lg)',
                boxShadow: 'var(--shadow)',
                zIndex: 200
              }}>
                <div style={{ padding: '12px 16px', borderBottom: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ fontWeight: 700, fontSize: '0.9rem' }}>Obaveštenja</span>
                  {unreadCount > 0 && (
                    <button onClick={markAllRead} style={{ fontSize: '0.72rem', color: 'var(--gold)', background: 'none', border: 'none', cursor: 'pointer' }}>
                      Sve pročitano
                    </button>
                  )}
                </div>
                {notifications.length === 0 ? (
                  <div style={{ padding: '24px 16px', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
                    Nema obaveštenja
                  </div>
                ) : (
                  notifications.slice(0, 20).map(n => (
                    <div
                      key={n.id}
                      onClick={() => handleNotifClick(n)}
                      style={{
                        padding: '10px 16px',
                        borderBottom: '1px solid var(--border)',
                        cursor: 'pointer',
                        background: n.read ? 'transparent' : 'rgba(37,99,235,0.05)',
                        display: 'flex',
                        gap: 10,
                        alignItems: 'flex-start'
                      }}
                    >
                      <span style={{ fontSize: '1rem', flexShrink: 0 }}>{TYPE_ICON[n.type] || '🔔'}</span>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontWeight: n.read ? 500 : 700, fontSize: '0.82rem' }}>{n.title}</div>
                        <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                          {n.message}
                        </div>
                        <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: 2 }}>{relTime(n.createdAt)}</div>
                      </div>
                      {!n.read && <div style={{ width: 7, height: 7, borderRadius: '50%', background: 'var(--gold)', flexShrink: 0, marginTop: 5 }} />}
                    </div>
                  ))
                )}
              </div>
            )}
          </div>
        )}

        {/* Logout */}
        {userRole === 'coach' && (
          <button
            onClick={logout}
            className="logout-btn"
            style={{
              background: 'transparent',
              border: '1px solid var(--border)',
              borderRadius: 6,
              color: 'var(--text-muted)',
              fontSize: '0.75rem',
              padding: '5px 12px',
              cursor: 'pointer'
            }}
          >
            Odjavi
          </button>
        )}
      </div>

      <style>{`
        @media (max-width: 768px) {
          .hamburger-btn { display: flex !important; }
          .date-text { display: none; }
          .logout-btn { display: none; }
        }
      `}</style>
    </header>
  );
}
