import React, { useState, useEffect } from 'react';
import {
  updateEmail, updatePassword, reauthenticateWithCredential,
  EmailAuthProvider, sendPasswordResetEmail
} from 'firebase/auth';
import { auth } from '../../firebase';
import { useAuth } from '../../auth/AuthContext';
import { useSettings } from '../../hooks/useSettings';

export default function SettingsPage() {
  const { user } = useAuth();
  const { settings, loading, updateRatingCriteria } = useSettings();
  const [criteria, setCriteria] = useState([]);
  const [newCriterion, setNewCriterion] = useState('');
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  // Account settings state
  const [accTab, setAccTab] = useState('email'); // 'email' | 'password'
  const [currentPw, setCurrentPw] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newPw, setNewPw] = useState('');
  const [newPw2, setNewPw2] = useState('');
  const [accSaving, setAccSaving] = useState(false);
  const [accMsg, setAccMsg] = useState({ type: '', text: '' });

  useEffect(() => {
    if (!loading) {
      setCriteria(settings.ratingCriteria || []);
    }
  }, [loading, settings]);

  const addCriterion = () => {
    const val = newCriterion.trim();
    if (!val) return;
    setCriteria(prev => [...prev, val]);
    setNewCriterion('');
    setSaved(false);
  };

  const removeCriterion = (i) => {
    setCriteria(prev => prev.filter((_, idx) => idx !== i));
    setSaved(false);
  };

  const moveUp = (i) => {
    if (i === 0) return;
    setCriteria(prev => {
      const arr = [...prev];
      [arr[i - 1], arr[i]] = [arr[i], arr[i - 1]];
      return arr;
    });
    setSaved(false);
  };

  const moveDown = (i) => {
    setCriteria(prev => {
      if (i === prev.length - 1) return prev;
      const arr = [...prev];
      [arr[i], arr[i + 1]] = [arr[i + 1], arr[i]];
      return arr;
    });
    setSaved(false);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await updateRatingCriteria(criteria);
      setSaved(true);
    } catch (e) {
      console.error(e);
    } finally {
      setSaving(false);
    }
  };

  const reauth = async () => {
    const credential = EmailAuthProvider.credential(user.email, currentPw);
    await reauthenticateWithCredential(auth.currentUser, credential);
  };

  const handleEmailChange = async (e) => {
    e.preventDefault();
    if (!newEmail.trim() || !currentPw) return;
    setAccSaving(true);
    setAccMsg({ type: '', text: '' });
    try {
      await reauth();
      await updateEmail(auth.currentUser, newEmail.trim());
      setAccMsg({ type: 'success', text: `Email promenjen na: ${newEmail.trim()}` });
      setNewEmail('');
      setCurrentPw('');
    } catch (err) {
      const code = err.code || '';
      if (code.includes('wrong-password') || code.includes('invalid-credential')) {
        setAccMsg({ type: 'error', text: 'Pogrešna trenutna lozinka.' });
      } else if (code.includes('email-already-in-use')) {
        setAccMsg({ type: 'error', text: 'Email je već u upotrebi.' });
      } else {
        setAccMsg({ type: 'error', text: 'Greška: ' + (err.message || 'Pokušajte ponovo.') });
      }
    } finally {
      setAccSaving(false);
    }
  };

  const handlePasswordChange = async (e) => {
    e.preventDefault();
    if (!newPw || newPw !== newPw2 || !currentPw) return;
    if (newPw.length < 6) { setAccMsg({ type: 'error', text: 'Lozinka mora imati najmanje 6 karaktera.' }); return; }
    setAccSaving(true);
    setAccMsg({ type: '', text: '' });
    try {
      await reauth();
      await updatePassword(auth.currentUser, newPw);
      setAccMsg({ type: 'success', text: 'Lozinka uspešno promenjena.' });
      setCurrentPw('');
      setNewPw('');
      setNewPw2('');
    } catch (err) {
      const code = err.code || '';
      if (code.includes('wrong-password') || code.includes('invalid-credential')) {
        setAccMsg({ type: 'error', text: 'Pogrešna trenutna lozinka.' });
      } else {
        setAccMsg({ type: 'error', text: 'Greška: ' + (err.message || 'Pokušajte ponovo.') });
      }
    } finally {
      setAccSaving(false);
    }
  };

  const handleResetEmail = async () => {
    try {
      await sendPasswordResetEmail(auth, user.email);
      setAccMsg({ type: 'success', text: `Reset link poslat na ${user.email}` });
    } catch {
      setAccMsg({ type: 'error', text: 'Greška pri slanju reset emaila.' });
    }
  };

  if (loading) return <div className="loading-container"><div className="loading-spinner" /></div>;

  return (
    <div style={{ maxWidth: 580 }}>
      <div className="page-header">
        <div>
          <h1 className="page-title">Podešavanja</h1>
          <p className="page-subtitle">Konfiguracija aplikacije</p>
        </div>
      </div>

      <div style={{
        background: 'var(--bg-card)',
        border: '1px solid var(--border)',
        borderRadius: 'var(--radius-lg)',
        padding: 24
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20 }}>
          <div>
            <h3 style={{ margin: 0, marginBottom: 4 }}>Kriterijumi ocenjivanja</h3>
            <p style={{ margin: 0, fontSize: '0.82rem', color: 'var(--text-muted)' }}>
              Koriste se pri ocenjivanju igrača na kraju svakog treninga.
            </p>
          </div>
          <button
            className="btn btn-primary btn-sm"
            onClick={handleSave}
            disabled={saving || saved}
            style={{ flexShrink: 0 }}
          >
            {saving ? 'Čuvam...' : saved ? '✓ Sačuvano' : 'Sačuvaj'}
          </button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 6, marginBottom: 16 }}>
          {criteria.length === 0 && (
            <div style={{
              padding: '20px',
              textAlign: 'center',
              color: 'var(--text-muted)',
              fontSize: '0.85rem',
              border: '1px dashed var(--border)',
              borderRadius: 8
            }}>
              Nema definisanih kriterijuma.
            </div>
          )}
          {criteria.map((c, i) => (
            <div key={i} style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              background: 'var(--bg-primary)',
              border: '1px solid var(--border)',
              borderRadius: 8,
              padding: '9px 14px'
            }}>
              <span style={{
                width: 22,
                height: 22,
                borderRadius: '50%',
                background: 'rgba(37,99,235,0.15)',
                color: 'var(--gold)',
                fontSize: '0.7rem',
                fontWeight: 700,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0
              }}>
                {i + 1}
              </span>
              <div style={{ flex: 1, fontSize: '0.9rem' }}>{c}</div>
              <div style={{ display: 'flex', gap: 2 }}>
                <button
                  onClick={() => moveUp(i)}
                  disabled={i === 0}
                  style={{
                    background: 'none', border: 'none',
                    cursor: i === 0 ? 'default' : 'pointer',
                    opacity: i === 0 ? 0.25 : 0.7,
                    color: 'var(--text-secondary)',
                    padding: '2px 6px', fontSize: '0.9rem',
                    borderRadius: 4
                  }}
                >↑</button>
                <button
                  onClick={() => moveDown(i)}
                  disabled={i === criteria.length - 1}
                  style={{
                    background: 'none', border: 'none',
                    cursor: i === criteria.length - 1 ? 'default' : 'pointer',
                    opacity: i === criteria.length - 1 ? 0.25 : 0.7,
                    color: 'var(--text-secondary)',
                    padding: '2px 6px', fontSize: '0.9rem',
                    borderRadius: 4
                  }}
                >↓</button>
                <button
                  onClick={() => { removeCriterion(i); setSaved(false); }}
                  style={{
                    background: 'none', border: 'none',
                    cursor: 'pointer',
                    color: 'var(--error)',
                    padding: '2px 8px', fontSize: '0.85rem',
                    borderRadius: 4
                  }}
                >✕</button>
              </div>
            </div>
          ))}
        </div>

        <div style={{ display: 'flex', gap: 8 }}>
          <input
            className="input"
            placeholder="Novi kriterijum..."
            value={newCriterion}
            onChange={e => { setNewCriterion(e.target.value); setSaved(false); }}
            onKeyDown={e => e.key === 'Enter' && addCriterion()}
            style={{ flex: 1 }}
          />
          <button
            className="btn btn-secondary"
            onClick={addCriterion}
            disabled={!newCriterion.trim()}
          >
            + Dodaj
          </button>
        </div>
      </div>

      {/* Account settings */}
      <div style={{
        background: 'var(--bg-card)',
        border: '1px solid var(--border)',
        borderRadius: 'var(--radius-lg)',
        padding: 24,
        marginTop: 20
      }}>
        <h3 style={{ margin: '0 0 4px' }}>Nalog</h3>
        <p style={{ margin: '0 0 16px', fontSize: '0.82rem', color: 'var(--text-muted)' }}>
          Prijavljen kao: <strong style={{ color: 'var(--text-secondary)' }}>{user?.email}</strong>
        </p>

        {/* Tabs */}
        <div style={{ display: 'flex', gap: 4, marginBottom: 16 }}>
          {[{ id: 'email', label: 'Promeni email' }, { id: 'password', label: 'Promeni lozinku' }].map(t => (
            <button
              key={t.id}
              onClick={() => { setAccTab(t.id); setAccMsg({ type: '', text: '' }); }}
              style={{
                padding: '5px 14px',
                borderRadius: 20,
                border: '1px solid',
                borderColor: accTab === t.id ? 'var(--gold)' : 'var(--border)',
                background: accTab === t.id ? 'rgba(37,99,235,0.12)' : 'transparent',
                color: accTab === t.id ? 'var(--gold)' : 'var(--text-muted)',
                fontSize: '0.82rem',
                fontWeight: 600,
                cursor: 'pointer'
              }}
            >
              {t.label}
            </button>
          ))}
        </div>

        {accMsg.text && (
          <div style={{
            background: accMsg.type === 'success' ? 'var(--success-bg)' : 'var(--error-bg)',
            border: `1px solid ${accMsg.type === 'success' ? 'var(--success)' : 'var(--error)'}`,
            borderRadius: 'var(--radius-sm)',
            padding: '8px 12px',
            fontSize: '0.82rem',
            color: accMsg.type === 'success' ? 'var(--success)' : 'var(--error)',
            marginBottom: 12
          }}>
            {accMsg.text}
          </div>
        )}

        {accTab === 'email' && (
          <form onSubmit={handleEmailChange} style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            <div className="form-group">
              <label className="label">Novi email</label>
              <input
                className="input"
                type="email"
                placeholder="novi@email.com"
                value={newEmail}
                onChange={e => setNewEmail(e.target.value)}
                disabled={accSaving}
              />
            </div>
            <div className="form-group">
              <label className="label">Trenutna lozinka (potvrda)</label>
              <input
                className="input"
                type="password"
                placeholder="••••••••"
                value={currentPw}
                onChange={e => setCurrentPw(e.target.value)}
                disabled={accSaving}
              />
            </div>
            <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
              <button
                type="submit"
                className="btn btn-primary"
                disabled={accSaving || !newEmail.trim() || !currentPw}
                style={{ flexShrink: 0 }}
              >
                {accSaving ? 'Čuvam...' : 'Promeni email'}
              </button>
              <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>ili</span>
              <button
                type="button"
                onClick={handleResetEmail}
                style={{ fontSize: '0.78rem', color: 'var(--gold)', background: 'none', border: 'none', cursor: 'pointer' }}
              >
                Pošalji reset link na {user?.email}
              </button>
            </div>
          </form>
        )}

        {accTab === 'password' && (
          <form onSubmit={handlePasswordChange} style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            <div className="form-group">
              <label className="label">Trenutna lozinka</label>
              <input
                className="input"
                type="password"
                placeholder="••••••••"
                value={currentPw}
                onChange={e => setCurrentPw(e.target.value)}
                disabled={accSaving}
              />
            </div>
            <div className="form-group">
              <label className="label">Nova lozinka</label>
              <input
                className="input"
                type="password"
                placeholder="Najmanje 6 karaktera"
                value={newPw}
                onChange={e => setNewPw(e.target.value)}
                disabled={accSaving}
              />
            </div>
            <div className="form-group">
              <label className="label">Potvrdi novu lozinku</label>
              <input
                className="input"
                type="password"
                placeholder="Ponovi lozinku"
                value={newPw2}
                onChange={e => setNewPw2(e.target.value)}
                disabled={accSaving}
              />
              {newPw && newPw2 && newPw !== newPw2 && (
                <span style={{ fontSize: '0.78rem', color: 'var(--error)', marginTop: 4 }}>Lozinke se ne poklapaju.</span>
              )}
            </div>
            <button
              type="submit"
              className="btn btn-primary"
              disabled={accSaving || !currentPw || !newPw || newPw !== newPw2}
              style={{ alignSelf: 'flex-start' }}
            >
              {accSaving ? 'Čuvam...' : 'Promeni lozinku'}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}
