import React from 'react';
import { HashRouter as Router, Routes, Route, Navigate, Outlet } from 'react-router-dom';
import { AuthProvider, useAuth } from './auth/AuthContext';
import LoginPage from './auth/LoginPage';
import InviteRegister from './auth/InviteRegister';
import Layout from './components/Layout/Layout';
import PlayersPage from './pages/Players/PlayersPage';
import PlayerProfile from './pages/Players/PlayerProfile';
import SchedulePage from './pages/Schedule/SchedulePage';
import ExercisesPage from './pages/Exercises/ExercisesPage';
import ProgressOverviewPage from './pages/ProgressOverview/ProgressOverviewPage';
import ReportsPage from './pages/Reports/ReportsPage';
import MembershipPage from './pages/Membership/MembershipPage';
import TrainingsListPage from './pages/Trainings/TrainingsListPage';
import TrainingSessionPage from './pages/Trainings/TrainingSessionPage';
import SettingsPage from './pages/Settings/SettingsPage';
import PlayerApp from './player/PlayerApp';
import DashboardPage from './pages/Dashboard/DashboardPage';

function CoachLayout() {
  return (
    <Layout>
      <Outlet />
    </Layout>
  );
}

function AppRoutes() {
  const { user, userRole, authLoading } = useAuth();

  if (authLoading) {
    return (
      <div style={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: 'var(--bg-primary)'
      }}>
        <div className="loading-spinner" />
      </div>
    );
  }

  if (!user) {
    return (
      <Routes>
        <Route path="/login" element={<LoginPage />} />
        <Route path="/pozivnica/:token" element={<InviteRegister />} />
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    );
  }

  if (userRole === 'player') {
    return (
      <Routes>
        <Route path="/player/*" element={<PlayerApp />} />
        <Route path="*" element={<Navigate to="/player/pocetna" replace />} />
      </Routes>
    );
  }

  // Coach
  return (
    <Routes>
      <Route path="/pozivnica/:token" element={<InviteRegister />} />
      <Route element={<CoachLayout />}>
        <Route path="/" element={<DashboardPage />} />
        <Route path="/golmani" element={<PlayersPage />} />
        <Route path="/igrac/:id" element={<PlayerProfile />} />
        <Route path="/raspored" element={<SchedulePage />} />
        <Route path="/vezbe" element={<ExercisesPage />} />
        <Route path="/napredak" element={<ProgressOverviewPage />} />
        <Route path="/izvestaji" element={<ReportsPage />} />
        <Route path="/clanarine" element={<MembershipPage />} />
        <Route path="/treninzi" element={<TrainingsListPage />} />
        <Route path="/trening/:id" element={<TrainingSessionPage />} />
        <Route path="/podesavanja" element={<SettingsPage />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Route>
    </Routes>
  );
}

export default function App() {
  return (
    <Router>
      <AuthProvider>
        <AppRoutes />
      </AuthProvider>
    </Router>
  );
}
