import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../auth/AuthContext';
import { useNotifications } from '../../hooks/useNotifications';

const TYPE_ICON = {
  training_completed: '⭐',
  new_training: '📅',
  training_note: '📝',
  procena: '📋',
  analiza: '🎬',
};

function relTime(iso) {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return 'malopre';
  if (m < 60) return `pre ${m} min`;
  const h = Math.floor(m / 60);
  if (h < 24) return `pre ${h} h`;
  const d = Math.floor(h / 24);
  return `pre ${d} d`;
}

export default function PlayerNotifications() {
  const { playerId } = useAuth();
  const { notifications, unreadCount, markRead, markAllRead } = useNotifications(playerId);
  const navigate = useNavigate();

  const handleClick = async (notif) => {
    await markRead(notif.id);
    const link = notif.link || '';
    if (link.startsWith('trening:')) {
      navigate(`/player/trening/${link.replace('trening:', '')}`);
    } else if (link === 'planer') {
      navigate('/player/planer');
    } else if (['napomene', 'procena', 'analiza'].includes(link)) {
      navigate('/player/napredak');
    }
  };

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <h1 style={{ fontSize: '1.15rem', fontWeight: 700, margin: 0 }}>
          🔔 Obaveštenja {unreadCount > 0 && <span style={{ fontSize: '0.8rem', color: 'var(--warning)', marginLeft: 6 }}>({unreadCount} novo)</span>}
        </h1>
        {unreadCount > 0 && (
          <button
            onClick={markAllRead}
            style={{ fontSize: '0.78rem', color: 'var(--gold)', background: 'none', border: 'none', cursor: 'pointer' }}
          >
            Označi sve kao pročitano
          </button>
        )}
      </div>

      {notifications.length === 0 ? (
        <div style={{
          textAlign: 'center',
          padding: '40px 20px',
          color: 'var(--text-muted)',
          background: 'var(--bg-card)',
          borderRadius: 'var(--radius)',
          border: '1px solid var(--border)'
        }}>
          <div style={{ fontSize: '2.5rem', marginBottom: 8 }}>📭</div>
          <div>Nema obaveštenja</div>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          {notifications.map(n => (
            <div
              key={n.id}
              onClick={() => handleClick(n)}
              style={{
                background: n.read ? 'var(--bg-card)' : 'rgba(37,99,235,0.07)',
                border: `1px solid ${n.read ? 'var(--border)' : 'rgba(37,99,235,0.3)'}`,
                borderRadius: 'var(--radius)',
                padding: '12px 14px',
                cursor: 'pointer',
                display: 'flex',
                gap: 12,
                alignItems: 'flex-start',
                transition: 'background 0.15s'
              }}
            >
              <span style={{ fontSize: '1.3rem', flexShrink: 0 }}>
                {TYPE_ICON[n.type] || '🔔'}
              </span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontWeight: n.read ? 500 : 700, fontSize: '0.9rem' }}>{n.title}</div>
                <div style={{ fontSize: '0.82rem', color: 'var(--text-muted)', marginTop: 3 }}>{n.message}</div>
                <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginTop: 4 }}>{relTime(n.createdAt)}</div>
              </div>
              {!n.read && (
                <div style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--gold)', flexShrink: 0, marginTop: 6 }} />
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
