import React, { useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { usePlayers } from '../../hooks/usePlayers';
import { useTrainings } from '../../hooks/useTrainings';
import { useCoachNotifications } from '../../hooks/useNotifications';
import { formatDate } from '../../utils/helpers';

function toDateKey(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function relTime(iso) {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return 'malopre';
  if (m < 60) return `pre ${m} min`;
  const h = Math.floor(m / 60);
  if (h < 24) return `pre ${h} h`;
  return `pre ${Math.floor(h / 24)} d`;
}

const TYPE_ICON = {
  player_rating: '⭐',
  training_note: '📝',
  procena: '📋',
  analiza: '🎬',
  new_training: '📅'
};

const QUICK_LINKS = [
  { icon: '🧤', label: 'Golmani', path: '/golmani', color: '#3b82f6' },
  { icon: '📅', label: 'Planer', path: '/treninzi', color: '#8b5cf6' },
  { icon: '📊', label: 'Napredak', path: '/napredak', color: '#22c55e' },
  { icon: '💳', label: 'Članarine', path: '/clanarine', color: '#f59e0b' },
  { icon: '📋', label: 'Izveštaji', path: '/izvestaji', color: '#ef4444' },
  { icon: '⚽', label: 'Vežbe', path: '/vezbe', color: '#06b6d4' },
];

export default function DashboardPage() {
  const navigate = useNavigate();
  const { players, loading: pLoad } = usePlayers();
  const { trainings, loading: tLoad } = useTrainings();
  const { notifications, unreadCount, markRead } = useCoachNotifications();

  const today = toDateKey(new Date());
  const in7 = toDateKey(new Date(Date.now() + 7 * 86400000));
  const thisMonth = new Date().toISOString().substring(0, 7);

  const upcomingTrainings = useMemo(() =>
    trainings
      .filter(t => t.date >= today && t.date <= in7)
      .sort((a, b) => (a.date + (a.time || '')).localeCompare(b.date + (b.time || '')))
      .slice(0, 5),
    [trainings, today, in7]
  );

  const thisMonthTrainings = useMemo(() =>
    trainings.filter(t => t.date?.startsWith(thisMonth)),
    [trainings, thisMonth]
  );

  const totalDebt = useMemo(() => {
    const year = new Date().getFullYear();
    const month = new Date().getMonth();
    return players.reduce((sum, p) => {
      const price = p.monthlyPrice || 0;
      let debt = 0;
      for (let m = 0; m <= month; m++) {
        const pay = p.payments?.[year]?.[m];
        if (!pay || pay.status !== 'paid') debt += price;
      }
      return sum + debt;
    }, 0);
  }, [players]);

  const unpaidCount = useMemo(() => {
    const year = new Date().getFullYear();
    const month = new Date().getMonth();
    return players.filter(p => {
      const pay = p.payments?.[year]?.[month];
      return !pay || pay.status !== 'paid';
    }).length;
  }, [players]);

  const recentNotifs = notifications.slice(0, 6);

  const handleNotifClick = async (notif) => {
    await markRead(notif.id);
    const link = notif.link || '';
    if (link.startsWith('trening:')) navigate(`/trening/${link.replace('trening:', '')}`);
  };

  const now = new Date();
  const greeting = now.getHours() < 12 ? 'Dobro jutro' : now.getHours() < 18 ? 'Dobar dan' : 'Dobro veče';

  if (pLoad || tLoad) return <div className="loading-container"><div className="loading-spinner" /></div>;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>

      {/* Greeting */}
      <div style={{
        background: 'linear-gradient(135deg, rgba(37,99,235,0.12) 0%, rgba(37,99,235,0.04) 100%)',
        border: '1px solid rgba(37,99,235,0.2)',
        borderRadius: 'var(--radius-lg)',
        padding: '20px 24px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center'
      }}>
        <div>
          <h1 style={{ fontSize: '1.4rem', fontWeight: 800, margin: 0 }}>
            {greeting} 👋
          </h1>
          <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginTop: 4 }}>
            {now.toLocaleDateString('sr-Latn-RS', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
          </div>
        </div>
        <img
          src={`${process.env.PUBLIC_URL}/logo.png`}
          alt="JGK"
          style={{ width: 52, height: 52, objectFit: 'contain', opacity: 0.85 }}
        />
      </div>

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 12 }}>
        {[
          { icon: '🧤', label: 'Golmana', val: players.length, color: '#3b82f6', onClick: () => navigate('/golmani') },
          { icon: '📅', label: 'Treninga ovog meseca', val: thisMonthTrainings.length, color: '#8b5cf6', onClick: () => navigate('/treninzi') },
          { icon: '⏰', label: 'Predstojećih', val: upcomingTrainings.length, color: '#22c55e', onClick: () => navigate('/treninzi') },
          { icon: '💳', label: 'Neplaćenih', val: unpaidCount, color: unpaidCount > 0 ? '#ef4444' : '#22c55e', onClick: () => navigate('/clanarine') },
        ].map(s => (
          <div
            key={s.label}
            onClick={s.onClick}
            style={{
              background: 'var(--bg-card)',
              border: '1px solid var(--border)',
              borderRadius: 'var(--radius)',
              padding: '16px',
              cursor: 'pointer',
              transition: 'border-color 0.15s',
              textAlign: 'center'
            }}
            onMouseEnter={e => e.currentTarget.style.borderColor = s.color}
            onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}
          >
            <div style={{ fontSize: '1.5rem', marginBottom: 6 }}>{s.icon}</div>
            <div style={{ fontSize: '1.6rem', fontWeight: 800, color: s.color }}>{s.val}</div>
            <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginTop: 3 }}>{s.label}</div>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>

        {/* Predstojeći treninzi */}
        <div>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
            <h2 style={{ fontSize: '0.9rem', fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.05em', margin: 0 }}>
              Predstojeći treninzi
            </h2>
            <button onClick={() => navigate('/treninzi')} style={{ fontSize: '0.75rem', color: 'var(--gold)', background: 'none', border: 'none', cursor: 'pointer' }}>
              Svi →
            </button>
          </div>
          {upcomingTrainings.length === 0 ? (
            <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: '24px', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
              Nema treninga u sledećih 7 dana
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {upcomingTrainings.map(t => {
                const firstImg = t.images?.[0] || t.imageBase64 || null;
                return (
                  <div
                    key={t.id}
                    onClick={() => navigate(`/trening/${t.id}`)}
                    style={{
                      background: 'var(--bg-card)',
                      border: `1px solid ${t.date === today ? 'rgba(37,99,235,0.4)' : 'var(--border)'}`,
                      borderRadius: 'var(--radius)',
                      padding: '12px 14px',
                      cursor: 'pointer',
                      display: 'flex',
                      gap: 10,
                      alignItems: 'flex-start'
                    }}
                  >
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 600, fontSize: '0.9rem' }}>{t.name}</div>
                      <div style={{ fontSize: '0.76rem', color: 'var(--text-muted)', marginTop: 2 }}>
                        📅 {formatDate(t.date)} {t.time && `• 🕐 ${t.time}`} {t.duration && `• ${t.duration} min`}
                      </div>
                      {t.note && (
                        <div style={{ fontSize: '0.74rem', color: 'var(--text-secondary)', marginTop: 3, fontStyle: 'italic' }}>
                          {t.note}
                        </div>
                      )}
                      {t.playerIds?.length > 0 && (
                        <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginTop: 3 }}>
                          🧤 {t.playerIds.length} {t.playerIds.length === 1 ? 'golman' : 'golmana'}
                        </div>
                      )}
                    </div>
                    {firstImg && (
                      <img src={firstImg} alt="" style={{ width: 48, height: 36, objectFit: 'cover', borderRadius: 5, flexShrink: 0, border: '1px solid var(--border)' }} />
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Nedavna aktivnost */}
        <div>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
            <h2 style={{ fontSize: '0.9rem', fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.05em', margin: 0 }}>
              Aktivnost igrača
              {unreadCount > 0 && (
                <span style={{ marginLeft: 8, background: 'var(--error)', color: '#fff', borderRadius: 10, padding: '1px 7px', fontSize: '0.68rem', fontWeight: 700 }}>
                  {unreadCount}
                </span>
              )}
            </h2>
          </div>
          {recentNotifs.length === 0 ? (
            <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: '24px', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
              Nema novih aktivnosti
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              {recentNotifs.map(n => (
                <div
                  key={n.id}
                  onClick={() => handleNotifClick(n)}
                  style={{
                    background: n.read ? 'var(--bg-card)' : 'rgba(37,99,235,0.06)',
                    border: `1px solid ${n.read ? 'var(--border)' : 'rgba(37,99,235,0.2)'}`,
                    borderRadius: 'var(--radius)',
                    padding: '10px 12px',
                    cursor: 'pointer',
                    display: 'flex',
                    gap: 10,
                    alignItems: 'flex-start'
                  }}
                >
                  <span style={{ fontSize: '1rem', flexShrink: 0 }}>{TYPE_ICON[n.type] || '🔔'}</span>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: n.read ? 500 : 700, fontSize: '0.82rem' }}>{n.title}</div>
                    <div style={{ fontSize: '0.74rem', color: 'var(--text-muted)', marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                      {n.message}
                    </div>
                  </div>
                  <div style={{ fontSize: '0.68rem', color: 'var(--text-muted)', flexShrink: 0, marginTop: 2 }}>
                    {relTime(n.createdAt)}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Brzi pristup */}
      <div>
        <h2 style={{ fontSize: '0.9rem', fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 12 }}>
          Brzi pristup
        </h2>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(6, 1fr)', gap: 10 }}>
          {QUICK_LINKS.map(l => (
            <div
              key={l.path}
              onClick={() => navigate(l.path)}
              style={{
                background: 'var(--bg-card)',
                border: '1px solid var(--border)',
                borderRadius: 'var(--radius)',
                padding: '16px 8px',
                textAlign: 'center',
                cursor: 'pointer',
                transition: 'border-color 0.15s, background 0.15s'
              }}
              onMouseEnter={e => { e.currentTarget.style.borderColor = l.color; e.currentTarget.style.background = 'var(--bg-primary)'; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--border)'; e.currentTarget.style.background = 'var(--bg-card)'; }}
            >
              <div style={{ fontSize: '1.6rem', marginBottom: 6 }}>{l.icon}</div>
              <div style={{ fontSize: '0.72rem', fontWeight: 600, color: 'var(--text-secondary)' }}>{l.label}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Dug */}
      {totalDebt > 0 && (
        <div
          onClick={() => navigate('/clanarine')}
          style={{
            background: 'rgba(239,68,68,0.06)',
            border: '1px solid rgba(239,68,68,0.2)',
            borderRadius: 'var(--radius)',
            padding: '14px 18px',
            cursor: 'pointer',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center'
          }}
        >
          <div>
            <div style={{ fontWeight: 700, fontSize: '0.9rem', color: '#ef4444' }}>⚠️ Ukupno neplaćenih članarina</div>
            <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginTop: 2 }}>{unpaidCount} {unpaidCount === 1 ? 'golman' : 'golmana'} nije platilo ovaj mesec</div>
          </div>
          <div style={{ fontSize: '1.2rem', fontWeight: 800, color: '#ef4444' }}>{totalDebt.toLocaleString()} RSD</div>
        </div>
      )}

    </div>
  );
}
