import React, { useState } from 'react';
import { sendPasswordResetEmail } from 'firebase/auth';
import { auth } from '../firebase';
import { useAuth } from './AuthContext';

export default function LoginPage() {
  const { login } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [resetMode, setResetMode] = useState(false);
  const [resetEmail, setResetEmail] = useState('');
  const [resetSent, setResetSent] = useState(false);
  const [resetLoading, setResetLoading] = useState(false);
  const [resetError, setResetError] = useState('');

  const handleReset = async (e) => {
    e.preventDefault();
    if (!resetEmail.trim()) return;
    setResetLoading(true);
    setResetError('');
    try {
      await sendPasswordResetEmail(auth, resetEmail.trim());
      setResetSent(true);
    } catch (err) {
      const code = err.code || '';
      if (code.includes('user-not-found') || code.includes('invalid-email')) {
        setResetError('Email adresa nije pronađena.');
      } else {
        setResetError('Greška. Pokušajte ponovo.');
      }
    } finally {
      setResetLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!email.trim() || !password) return;
    setLoading(true);
    setError('');
    try {
      await login(email.trim(), password);
    } catch (err) {
      const code = err.code || '';
      if (code.includes('user-not-found') || code.includes('invalid-credential') || code.includes('wrong-password')) {
        setError('Pogrešan email ili lozinka.');
      } else if (code.includes('too-many-requests')) {
        setError('Previše neuspelih pokušaja. Sačekajte malo.');
      } else {
        setError('Greška pri prijavi. Pokušajte ponovo.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'var(--bg-primary)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 20
    }}>
      <div style={{
        width: '100%',
        maxWidth: 380,
        background: 'var(--bg-card)',
        border: '1px solid var(--border)',
        borderRadius: 'var(--radius-lg)',
        padding: '32px 28px'
      }}>
        <div style={{ textAlign: 'center', marginBottom: 28 }}>
          <div style={{ fontSize: '2.5rem', marginBottom: 8 }}>⚽</div>
          <h1 style={{ fontSize: '1.4rem', fontWeight: 700, margin: 0 }}>JEVRAGKlab</h1>
          <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginTop: 6 }}>
            Prijavite se na vaš nalog
          </p>
        </div>

        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <div className="form-group">
            <label className="label">Email</label>
            <input
              className="input"
              type="email"
              placeholder="email@primer.com"
              value={email}
              onChange={e => setEmail(e.target.value)}
              autoComplete="email"
              disabled={loading}
            />
          </div>

          <div className="form-group">
            <label className="label">Lozinka</label>
            <input
              className="input"
              type="password"
              placeholder="••••••••"
              value={password}
              onChange={e => setPassword(e.target.value)}
              autoComplete="current-password"
              disabled={loading}
            />
          </div>

          {error && (
            <div style={{
              background: 'var(--error-bg)',
              border: '1px solid var(--error)',
              borderRadius: 'var(--radius-sm)',
              padding: '8px 12px',
              fontSize: '0.82rem',
              color: 'var(--error)'
            }}>
              {error}
            </div>
          )}

          <button
            type="submit"
            className="btn btn-primary"
            disabled={loading || !email.trim() || !password}
            style={{ marginTop: 4, height: 44, fontSize: '0.95rem' }}
          >
            {loading ? 'Prijavljujem...' : 'Prijavi se'}
          </button>
        </form>

        <p style={{ textAlign: 'center', fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 16 }}>
          <span
            onClick={() => { setResetMode(true); setResetEmail(email); setResetError(''); setResetSent(false); }}
            style={{ color: 'var(--gold)', cursor: 'pointer' }}
          >
            Zaboravili ste lozinku?
          </span>
        </p>

        {/* Reset lozinke panel */}
        {resetMode && (
          <div style={{
            marginTop: 12,
            background: 'rgba(37,99,235,0.06)',
            border: '1px solid rgba(37,99,235,0.2)',
            borderRadius: 'var(--radius)',
            padding: '14px 16px'
          }}>
            <div style={{ fontSize: '0.82rem', fontWeight: 700, marginBottom: 8 }}>Reset lozinke</div>
            {resetSent ? (
              <div style={{ fontSize: '0.82rem', color: 'var(--success)' }}>
                ✓ Link za reset je poslat na <strong>{resetEmail}</strong>. Proverite inbox.
              </div>
            ) : (
              <form onSubmit={handleReset} style={{ display: 'flex', gap: 8 }}>
                <input
                  className="input"
                  type="email"
                  placeholder="Email adresa"
                  value={resetEmail}
                  onChange={e => setResetEmail(e.target.value)}
                  style={{ flex: 1, fontSize: '0.85rem' }}
                  disabled={resetLoading}
                />
                <button
                  type="submit"
                  className="btn btn-secondary"
                  disabled={resetLoading || !resetEmail.trim()}
                  style={{ fontSize: '0.82rem', padding: '0 12px', flexShrink: 0 }}
                >
                  {resetLoading ? '...' : 'Pošalji'}
                </button>
              </form>
            )}
            {resetError && <div style={{ fontSize: '0.78rem', color: 'var(--error)', marginTop: 6 }}>{resetError}</div>}
            <button
              onClick={() => setResetMode(false)}
              style={{ fontSize: '0.72rem', color: 'var(--text-muted)', background: 'none', border: 'none', cursor: 'pointer', marginTop: 6 }}
            >
              Zatvori
            </button>
          </div>
        )}

        <p style={{ textAlign: 'center', fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 16 }}>
          Igrač? Koristite pozivni link od trenera.
        </p>
      </div>
    </div>
  );
}
