import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { usePlayers } from '../../hooks/usePlayers';
import Avatar from '../../components/common/Avatar';
import { PositionBadge, MembershipBadge } from '../../components/common/Badge';
import PlayerData from './tabs/PlayerData';
import Attendance from './tabs/Attendance';
import Payment from './tabs/Payment';
import Progress from './tabs/Progress';
import Notes from './tabs/Notes';
import Procena from './tabs/Procena';
import Analiza from './tabs/Analiza';
import { getAge, getCategory } from '../../utils/helpers';

const TABS = [
  { id: 'podaci', label: 'Podaci' },
  { id: 'dolasci', label: 'Dolasci' },
  { id: 'placanje', label: 'Plaćanje' },
  { id: 'napredak', label: 'Napredak' },
  { id: 'napomene', label: 'Napomene' },
  { id: 'procena', label: 'Procena' },
  { id: 'analiza', label: 'Analiza' }
];

export default function PlayerProfile() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { players, loading, updatePlayer, deletePlayer } = usePlayers();
  const [activeTab, setActiveTab] = useState('podaci');
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [copied, setCopied] = useState(false);

  const sortedPlayers = [...players].sort((a, b) =>
    `${a.firstName} ${a.lastName}`.localeCompare(`${b.firstName} ${b.lastName}`)
  );
  const currentIndex = sortedPlayers.findIndex(p => p.id === id);
  const prevPlayer = currentIndex > 0 ? sortedPlayers[currentIndex - 1] : null;
  const nextPlayer = currentIndex < sortedPlayers.length - 1 ? sortedPlayers[currentIndex + 1] : null;

  const player = players.find(p => p.id === id);

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner" />
      </div>
    );
  }

  if (!player) {
    return (
      <div className="empty-state">
        <div className="empty-state-icon">👤</div>
        <div className="empty-state-title">Igrač nije pronađen</div>
        <button className="btn btn-secondary" onClick={() => navigate('/')} style={{ marginTop: 16 }}>
          ← Nazad na listu
        </button>
      </div>
    );
  }

  const fullName = `${player.firstName || ''} ${player.lastName || ''}`.trim() || 'Nepoznat';
  const age = getAge(player.birthYear);
  const category = getCategory(player.birthYear);
  const inviteUrl = `https://fudbalskilab-hkr.github.io/JGK/#/pozivnica/${player.id}`;

  const handleToggleMembership = async (newStatus) => {
    await updatePlayer(player.id, {
      membershipStatus: newStatus,
      membershipDate: newStatus === 'paid' ? new Date().toISOString() : null
    });
  };

  const handleDelete = async () => {
    await deletePlayer(player.id);
    navigate('/');
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(inviteUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const renderTab = () => {
    switch (activeTab) {
      case 'podaci': return <PlayerData player={player} />;
      case 'dolasci': return <Attendance player={player} />;
      case 'placanje': return <Payment player={player} />;
      case 'napredak': return <Progress player={player} />;
      case 'napomene': return <Notes player={player} />;
      case 'procena': return <Procena player={player} />;
      case 'analiza': return <Analiza player={player} />;
      default: return <PlayerData player={player} />;
    }
  };

  return (
    <div>
      {/* Back + navigacija */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 20, flexWrap: 'wrap' }}>
        <button className="btn btn-secondary btn-sm" onClick={() => navigate('/')}>
          ← Igrači
        </button>
        <div style={{ flex: 1 }} />
        <button
          className="btn btn-secondary btn-sm"
          onClick={() => navigate(`/igrac/${prevPlayer.id}`)}
          disabled={!prevPlayer}
          title={prevPlayer ? `${prevPlayer.firstName} ${prevPlayer.lastName}` : ''}
          style={{ opacity: prevPlayer ? 1 : 0.3, minWidth: 52, height: 40, fontSize: '1.8rem', lineHeight: 1, padding: '0 12px' }}
        >‹</button>
        <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)', userSelect: 'none' }}>
          {currentIndex + 1} / {sortedPlayers.length}
        </span>
        <button
          className="btn btn-secondary btn-sm"
          onClick={() => navigate(`/igrac/${nextPlayer.id}`)}
          disabled={!nextPlayer}
          title={nextPlayer ? `${nextPlayer.firstName} ${nextPlayer.lastName}` : ''}
          style={{ opacity: nextPlayer ? 1 : 0.3, minWidth: 52, height: 40, fontSize: '1.8rem', lineHeight: 1, padding: '0 12px' }}
        >›</button>
      </div>

      {/* Player header card */}
      <div style={{
        background: 'var(--bg-card)',
        border: '1px solid var(--border)',
        borderRadius: 'var(--radius-lg)',
        padding: 24,
        marginBottom: 20,
        display: 'flex',
        alignItems: 'flex-start',
        gap: 24,
        flexWrap: 'wrap'
      }}>
        <Avatar src={player.photoBase64} name={fullName} size="xl" />

        <div style={{ flex: 1, minWidth: 200 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 8, flexWrap: 'wrap' }}>
            <h1 style={{ fontSize: '1.5rem', margin: 0 }}>{fullName}</h1>
            <PositionBadge position={player.position} />
            <span style={{
              background: 'rgba(255,255,255,0.07)',
              border: '1px solid var(--border)',
              borderRadius: 4,
              padding: '2px 8px',
              fontSize: '0.72rem',
              color: 'var(--text-muted)',
              fontWeight: 700
            }}>
              {category}
            </span>
          </div>

          <div style={{ display: 'flex', gap: 20, flexWrap: 'wrap', marginBottom: 12 }}>
            {player.club && <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>🏟 {player.club}</div>}
            {age && <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>🎂 {age} godina ({player.birthYear})</div>}
            {player.height && <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>📏 {player.height} cm</div>}
            {player.weight && <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>⚖ {player.weight} kg</div>}
            {player.dominantFoot && (
              <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                👟 {player.dominantFoot === 'desna' ? 'Desna noga' : player.dominantFoot === 'leva' ? 'Leva noga' : 'Obe noge'}
              </div>
            )}
          </div>

          <MembershipBadge player={player} onToggle={handleToggleMembership} />
        </div>

        {/* Actions */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, alignItems: 'flex-end' }}>
          {/* Pozivnica */}
          <button
            className="btn btn-sm btn-secondary"
            onClick={() => setShowInvite(s => !s)}
            style={{ fontSize: '0.8rem' }}
          >
            🔗 Pozivnica
          </button>

          {/* Delete */}
          {!confirmDelete ? (
            <button
              className="btn btn-sm"
              onClick={() => setConfirmDelete(true)}
              style={{ background: 'transparent', border: '1px solid var(--border)', color: 'var(--text-muted)', fontSize: '0.8rem' }}
            >
              🗑 Obriši
            </button>
          ) : (
            <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <span style={{ fontSize: '0.8rem', color: 'var(--error)' }}>Obrisati?</span>
              <button className="btn btn-danger btn-sm" onClick={handleDelete}>Da</button>
              <button className="btn btn-secondary btn-sm" onClick={() => setConfirmDelete(false)}>Ne</button>
            </div>
          )}
        </div>
      </div>

      {/* Invite panel */}
      {showInvite && (
        <div style={{
          background: 'rgba(37,99,235,0.06)',
          border: '1px solid rgba(37,99,235,0.25)',
          borderRadius: 'var(--radius-lg)',
          padding: '16px 20px',
          marginBottom: 20,
          display: 'flex',
          gap: 20,
          alignItems: 'flex-start',
          flexWrap: 'wrap'
        }}>
          <div style={{ flex: 1, minWidth: 200 }}>
            <div style={{ fontSize: '0.82rem', fontWeight: 700, color: 'var(--gold)', marginBottom: 8 }}>
              🔗 Pozivni link za {fullName}
            </div>
            <div style={{ display: 'flex', gap: 8 }}>
              <input
                readOnly
                value={inviteUrl}
                style={{
                  flex: 1,
                  background: 'var(--bg-primary)',
                  border: '1px solid var(--border)',
                  borderRadius: 6,
                  color: 'var(--text-secondary)',
                  fontSize: '0.78rem',
                  padding: '7px 10px'
                }}
                onClick={e => e.target.select()}
              />
              <button
                className="btn btn-primary btn-sm"
                onClick={handleCopy}
                style={{ flexShrink: 0 }}
              >
                {copied ? '✓ Kopirano' : 'Kopiraj'}
              </button>
            </div>
            <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 8, marginBottom: 0 }}>
              Igrač otvara link na telefonu i kreira nalog. Link je uvek važeći.
            </p>
          </div>
          <img
            src={`https://api.qrserver.com/v1/create-qr-code/?size=110x110&data=${encodeURIComponent(inviteUrl)}`}
            alt="QR kod"
            style={{ width: 110, height: 110, borderRadius: 6, border: '1px solid var(--border)' }}
          />
        </div>
      )}

      {/* Tabs */}
      <div className="tabs" style={{ marginBottom: 20 }}>
        {TABS.map(tab => (
          <button
            key={tab.id}
            className={`tab-btn ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => setActiveTab(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab content */}
      <div className="animate-fade-in" key={activeTab}>
        {renderTab()}
      </div>
    </div>
  );
}
