import React from 'react';
import { useNavigate } from 'react-router-dom';
import Avatar from '../../components/common/Avatar';
import { MembershipBadge } from '../../components/common/Badge';
import { getAge, getCategory } from '../../utils/helpers';
import { usePlayers } from '../../hooks/usePlayers';

export default function PlayerCard({ player }) {
  const navigate = useNavigate();
  const { updatePlayer } = usePlayers();

  const fullName = `${player.firstName || ''} ${player.lastName || ''}`.trim() || 'Nepoznat';

  const handleToggleMembership = async (e) => {
    e.stopPropagation();
    const newStatus = player.membershipStatus === 'paid' ? 'unpaid' : 'paid';
    try {
      await updatePlayer(player.id, {
        membershipStatus: newStatus,
        membershipDate: newStatus === 'paid' ? new Date().toISOString() : null
      });
    } catch (err) {
      console.error('Failed to toggle membership:', err);
    }
  };

  const age = getAge(player.birthYear);
  const category = getCategory(player.birthYear);

  return (
    <div
      onClick={() => navigate(`/igrac/${player.id}`)}
      style={{
        background: 'var(--bg-card)',
        border: '1px solid var(--border)',
        borderRadius: 'var(--radius)',
        padding: 20,
        cursor: 'pointer',
        transition: 'all 0.2s ease',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        textAlign: 'center',
        gap: 12,
        position: 'relative',
        overflow: 'hidden'
      }}
      onMouseEnter={e => {
        e.currentTarget.style.borderColor = 'var(--gold)';
        e.currentTarget.style.boxShadow = '0 8px 30px rgba(37, 99, 235, 0.15)';
        e.currentTarget.style.transform = 'translateY(-2px)';
      }}
      onMouseLeave={e => {
        e.currentTarget.style.borderColor = 'var(--border)';
        e.currentTarget.style.boxShadow = 'none';
        e.currentTarget.style.transform = 'translateY(0)';
      }}
      className="animate-fade-in"
    >
      {/* Background decoration */}
      <div style={{
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        height: 60,
        background: 'linear-gradient(180deg, rgba(37,99,235,0.06) 0%, transparent 100%)',
        pointerEvents: 'none'
      }} />

      {/* Avatar */}
      <div style={{ position: 'relative' }}>
        <Avatar
          src={player.photoBase64}
          name={fullName}
          size="lg"
        />
        <span style={{
          position: 'absolute',
          bottom: -4,
          right: -4,
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 4,
          padding: '1px 5px',
          fontSize: '0.65rem',
          fontWeight: 700,
          color: 'var(--text-muted)'
        }}>
          {category}
        </span>
      </div>

      {/* Name */}
      <div>
        <div style={{
          fontSize: '0.95rem',
          fontWeight: 700,
          color: 'var(--text-primary)',
        }}>
          {fullName}
        </div>
      </div>

      {/* Info row */}
      <div style={{
        display: 'flex',
        gap: 16,
        fontSize: '0.78rem',
        color: 'var(--text-muted)',
        width: '100%',
        justifyContent: 'center'
      }}>
        {age && (
          <span>
            <span style={{ color: 'var(--text-secondary)', fontWeight: 600 }}>{age}</span> god.
          </span>
        )}
        {player.birthYear && (
          <span>
            <span style={{ color: 'var(--text-secondary)', fontWeight: 600 }}>{player.birthYear}</span> gšt.
          </span>
        )}
      </div>

      {/* Club */}
      {player.club && (
        <div style={{
          fontSize: '0.8rem',
          color: 'var(--text-secondary)',
          background: 'var(--bg-primary)',
          border: '1px solid var(--border)',
          borderRadius: 4,
          padding: '3px 10px',
          width: '100%',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          whiteSpace: 'nowrap'
        }}>
          🏟 {player.club}
        </div>
      )}

      {/* Membership badge */}
      <div onClick={handleToggleMembership} style={{ marginTop: 'auto' }}>
        <MembershipBadge player={player} onToggle={() => {}} />
      </div>
    </div>
  );
}
