import { useState, useEffect } from 'react';
import { ref, onValue, push, set, update, remove } from 'firebase/database';
import { db } from '../firebase';
import { notifyPlayer } from '../utils/notifications';

export function useTrainings() {
  const [trainings, setTrainings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const trainingsRef = ref(db, 'trainings');

    const unsubscribe = onValue(
      trainingsRef,
      (snapshot) => {
        const data = snapshot.val();
        if (data) {
          const trainingsArray = Object.entries(data).map(([id, val]) => ({
            id,
            ...val
          }));
          setTrainings(trainingsArray);
        } else {
          setTrainings([]);
        }
        setLoading(false);
      },
      (err) => {
        console.error('Error fetching trainings:', err);
        setError(err.message);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, []);

  const addTraining = async (data) => {
    try {
      const trainingsRef = ref(db, 'trainings');
      const newRef = push(trainingsRef);
      await set(newRef, { ...data, createdAt: new Date().toISOString() });
      if (data.playerIds?.length) {
        data.playerIds.forEach(pid =>
          notifyPlayer(pid, {
            type: 'new_training',
            title: 'Novi trening',
            message: `${data.name || 'Trening'} — ${data.date || ''}`,
            link: `trening:${newRef.key}`
          })
        );
      }
      return newRef.key;
    } catch (err) {
      console.error('Error adding training:', err);
      throw err;
    }
  };

  const updateTraining = async (id, data) => {
    try {
      const trainingRef = ref(db, `trainings/${id}`);
      await update(trainingRef, data);
    } catch (err) {
      console.error('Error updating training:', err);
      throw err;
    }
  };

  const deleteTraining = async (id) => {
    try {
      const trainingRef = ref(db, `trainings/${id}`);
      await remove(trainingRef);
    } catch (err) {
      console.error('Error deleting training:', err);
      throw err;
    }
  };

  const getTrainingsByDate = (dateKey) => {
    return trainings.filter(t => t.date === dateKey);
  };

  const getTrainingsByMonth = (year, month) => {
    const prefix = `${year}-${String(month + 1).padStart(2, '0')}`;
    return trainings.filter(t => t.date && t.date.startsWith(prefix));
  };

  const completeTraining = async (id, completionData) => {
    try {
      const training = trainings.find(t => t.id === id);
      const trainingRef = ref(db, `trainings/${id}`);
      await update(trainingRef, {
        completed: true,
        completedAt: new Date().toISOString(),
        ...completionData
      });
      if (completionData.attendance) {
        Object.entries(completionData.attendance)
          .filter(([, present]) => present)
          .forEach(([pid]) =>
            notifyPlayer(pid, {
              type: 'training_completed',
              title: 'Trening završen — oceni ga!',
              message: training?.name || 'Trening',
              link: `trening:${id}`
            })
          );
      }
    } catch (err) {
      console.error('Error completing training:', err);
      throw err;
    }
  };

  return {
    trainings,
    loading,
    error,
    addTraining,
    updateTraining,
    deleteTraining,
    completeTraining,
    getTrainingsByDate,
    getTrainingsByMonth
  };
}

