export function useHashtagGroups() {
  const [groups, setGroups] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const groupsRef = ref(db, 'hashtagGroups');
    const unsubscribe = onValue(groupsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setGroups(Object.entries(data).map(([id, val]) => ({ id, ...val })));
      } else {
        setGroups([]);
      }
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  const addGroup = async (label) => {
    const groupsRef = ref(db, 'hashtagGroups');
    const newRef = push(groupsRef);
    await set(newRef, { label, tags: [] });
    return newRef.key;
  };

  const updateGroup = async (id, data) => {
    const { id: _id, ...rest } = data;
    await set(ref(db, `hashtagGroups/${id}`), rest);
  };

  const deleteGroup = async (id) => {
    await remove(ref(db, `hashtagGroups/${id}`));
  };

  const restoreGroup = async (group) => {
    const { id, ...data } = group;
    await set(ref(db, `hashtagGroups/${id}`), data);
  };

  return { groups, loading, addGroup, updateGroup, deleteGroup, restoreGroup };
}
