import React from 'react';
import { getInitials } from '../../utils/helpers';

const sizeMap = {
  xs: { size: 28, fontSize: '0.65rem' },
  sm: { size: 36, fontSize: '0.75rem' },
  md: { size: 48, fontSize: '1rem' },
  lg: { size: 72, fontSize: '1.5rem' },
  xl: { size: 96, fontSize: '2rem' }
};

export default function Avatar({ src, name, size = 'md', style = {} }) {
  const { size: px, fontSize } = sizeMap[size] || sizeMap.md;

  const containerStyle = {
    width: px,
    height: px,
    borderRadius: '50%',
    overflow: 'hidden',
    flexShrink: 0,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: src ? 'transparent' : 'linear-gradient(135deg, #3b82f6, #1d4ed8)',
    border: '2px solid rgba(200, 134, 10, 0.3)',
    fontSize,
    fontWeight: 700,
    color: '#000',
    ...style
  };

  if (src) {
    return (
      <div style={containerStyle}>
        <img
          src={src}
          alt={name || 'Player'}
          style={{ width: '100%', height: '100%', objectFit: 'cover' }}
          onError={(e) => {
            e.target.style.display = 'none';
            e.target.parentElement.style.background = 'linear-gradient(135deg, #3b82f6, #1d4ed8)';
          }}
        />
      </div>
    );
  }

  return (
    <div style={containerStyle}>
      {getInitials(name)}
    </div>
  );
}
