import React, { useState, useRef } from 'react';
import { useExercises, useHashtagGroups } from '../../hooks/useTrainings';
import Modal from '../../components/common/Modal';

async function compressImage(file, maxWidth = 900, quality = 0.75) {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let { width, height } = img;
        if (width > maxWidth) { height = Math.round(height * maxWidth / width); width = maxWidth; }
        const canvas = document.createElement('canvas');
        canvas.width = width; canvas.height = height;
        canvas.getContext('2d').drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', quality));
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}

const CHIP = {
  base: {
    padding: '3px 10px',
    borderRadius: 20,
    border: '1px solid',
    fontSize: '0.76rem',
    fontWeight: 600,
    cursor: 'pointer',
    transition: 'all 0.15s',
  },
  active: { borderColor: 'var(--gold)', background: 'rgba(37,99,235,0.18)', color: 'var(--gold)' },
  inactive: { borderColor: 'var(--border)', background: 'transparent', color: 'var(--text-muted)' },
  selected: { borderColor: 'var(--gold)', background: 'rgba(37,99,235,0.18)', color: 'var(--gold)' },
  suggestion: { borderColor: 'var(--border)', background: 'transparent', color: 'var(--text-secondary)' },
};

export default function ExercisesPage() {
  const { exercises, loading, addExercise, deleteExercise } = useExercises();
  const { groups, addGroup, updateGroup, deleteGroup } = useHashtagGroups();

  // ── Add exercise modal ──────────────────────────────
  const [isOpen, setIsOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState('');
  const [form, setForm] = useState({ name: '', description: '', hashtags: [], videoUrl: '', images: [] });
  const [customTagInput, setCustomTagInput] = useState('');
  const [imgLoading, setImgLoading] = useState(false);
  const imgInputRef = useRef(null);

  // ── Manage groups modal ─────────────────────────────
  const [showGroupsModal, setShowGroupsModal] = useState(false);
  const [newGroupLabel, setNewGroupLabel] = useState('');
  const [newTagInputs, setNewTagInputs] = useState({}); // { groupId: string }

  // ── Filter ──────────────────────────────────────────
  const [search, setSearch] = useState('');
  const [hashtagFilter, setHashtagFilter] = useState('');

  // ── Helpers ─────────────────────────────────────────
  const allHashtags = [...new Set(exercises.flatMap(e => e.hashtags || []))].sort();
  const knownTags = new Set(groups.flatMap(g => g.tags || []));
  const ungroupedTags = allHashtags.filter(t => !knownTags.has(t));

  const filtered = exercises.filter(e => {
    const matchSearch = !search ||
      e.name.toLowerCase().includes(search.toLowerCase()) ||
      (e.description || '').toLowerCase().includes(search.toLowerCase());
    const matchTag = !hashtagFilter || (e.hashtags || []).includes(hashtagFilter);
    return matchSearch && matchTag;
  });

  // ── Add exercise ─────────────────────────────────────
  const toggleFormTag = (tag) => {
    setForm(prev => ({
      ...prev,
      hashtags: prev.hashtags.includes(tag)
        ? prev.hashtags.filter(t => t !== tag)
        : [...prev.hashtags, tag]
    }));
  };

  const addCustomTag = () => {
    const tag = customTagInput.trim().replace(/^#/, '').toLowerCase();
    if (!tag) return;
    if (!form.hashtags.includes(tag)) {
      setForm(prev => ({ ...prev, hashtags: [...prev.hashtags, tag] }));
    }
    setCustomTagInput('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;
    setSaving(true);
    setSaveError('');
    try {
      await addExercise({ ...form });
      setIsOpen(false);
      setForm({ name: '', description: '', hashtags: [], videoUrl: '', images: [] });
      setCustomTagInput('');
    } catch (err) {
      console.error(err);
      setSaveError('Greška pri čuvanju: ' + (err?.message || 'Provjeri Firebase pravila pristupa.'));
    } finally {
      setSaving(false);
    }
  };

  const handleExerciseImages = async (e) => {
    const files = Array.from(e.target.files);
    if (!files.length) return;
    setImgLoading(true);
    try {
      const compressed = await Promise.all(files.map(f => compressImage(f)));
      setForm(prev => ({ ...prev, images: [...(prev.images || []), ...compressed] }));
    } catch (err) { console.error(err); }
    finally { setImgLoading(false); if (imgInputRef.current) imgInputRef.current.value = ''; }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Obrisati ovu vežbu?')) {
      await deleteExercise(id);
    }
  };

  // ── Groups management ────────────────────────────────
  const handleAddGroup = async () => {
    const label = newGroupLabel.trim();
    if (!label) return;
    await addGroup(label);
    setNewGroupLabel('');
  };

  const handleDeleteGroup = async (group) => {
    if (window.confirm(`Obrisati grupu "${group.label}"?`)) {
      await deleteGroup(group.id);
    }
  };

  const handleAddTagToGroup = async (group) => {
    const tag = (newTagInputs[group.id] || '').trim().replace(/^#/, '').toLowerCase();
    if (!tag) return;
    const tags = [...(group.tags || [])];
    if (!tags.includes(tag)) {
      await updateGroup(group.id, { ...group, tags: [...tags, tag] });
    }
    setNewTagInputs(prev => ({ ...prev, [group.id]: '' }));
  };

  const handleRemoveTagFromGroup = async (group, tag) => {
    await updateGroup(group.id, { ...group, tags: (group.tags || []).filter(t => t !== tag) });
  };

  if (loading) {
    return <div className="loading-container"><div className="loading-spinner" /></div>;
  }

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">Moje Vežbe</h1>
          <p className="page-subtitle">{exercises.length} vežbi ukupno</p>
        </div>
        <div style={{ display: 'flex', gap: 10 }}>
          <button className="btn btn-secondary" onClick={() => setShowGroupsModal(true)}>
            ⚙ Grupe tagova
          </button>
          <button className="btn btn-primary" onClick={() => setIsOpen(true)}>
            + Dodaj Vežbu
          </button>
        </div>
      </div>

      {/* ── Search ── */}
      <div style={{ marginBottom: 20 }}>
        <input
          type="text"
          className="input"
          placeholder="🔍  Pretraži vežbe..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={{ maxWidth: 360, marginBottom: 14 }}
        />

        {allHashtags.length > 0 && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {/* "Sve" */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <button
                onClick={() => setHashtagFilter('')}
                style={{ ...CHIP.base, ...(!hashtagFilter ? CHIP.active : CHIP.inactive) }}
              >
                Sve
              </button>
            </div>

            {/* Groups */}
            {groups.map(group => {
              const activeTags = (group.tags || []).filter(t => allHashtags.includes(t));
              if (activeTags.length === 0) return null;
              return (
                <div key={group.id} style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                  <span style={{ fontSize: '0.72rem', color: 'var(--text-muted)', fontWeight: 600, minWidth: 80 }}>
                    {group.label}
                  </span>
                  {activeTags.map(tag => (
                    <button
                      key={tag}
                      onClick={() => setHashtagFilter(hashtagFilter === tag ? '' : tag)}
                      style={{ ...CHIP.base, ...(hashtagFilter === tag ? CHIP.active : CHIP.inactive) }}
                    >
                      #{tag}
                    </button>
                  ))}
                </div>
              );
            })}

            {/* Ungrouped */}
            {ungroupedTags.length > 0 && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                <span style={{ fontSize: '0.72rem', color: 'var(--text-muted)', fontWeight: 600, minWidth: 80 }}>
                  Ostalo
                </span>
                {ungroupedTags.map(tag => (
                  <button
                    key={tag}
                    onClick={() => setHashtagFilter(hashtagFilter === tag ? '' : tag)}
                    style={{ ...CHIP.base, ...(hashtagFilter === tag ? CHIP.active : CHIP.inactive) }}
                  >
                    #{tag}
                  </button>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* ── Exercise grid ── */}
      {filtered.length === 0 ? (
        <div className="empty-state">
          <div className="empty-state-icon">⚽</div>
          <div className="empty-state-title">
            {exercises.length === 0 ? 'Nema vežbi' : 'Nema rezultata'}
          </div>
          <p className="empty-state-text">
            {exercises.length === 0
              ? 'Dodaj svoju prvu vežbu klikom na dugme gore desno.'
              : 'Pokušaj sa drugačijim filterom.'}
          </p>
        </div>
      ) : (
        <div
          className="stagger-children"
          style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 16, marginBottom: 100 }}
        >
          {filtered.map(exercise => (
            <div
              key={exercise.id}
              style={{
                background: 'var(--bg-card)', border: '1px solid var(--border)',
                borderRadius: 'var(--radius)', padding: 20,
                transition: 'all 0.2s ease', display: 'flex', flexDirection: 'column', gap: 10
              }}
              onMouseEnter={e => { e.currentTarget.style.borderColor = '#3a3a3a'; e.currentTarget.style.transform = 'translateY(-1px)'; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--border)'; e.currentTarget.style.transform = 'translateY(0)'; }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <h4 style={{ margin: 0, fontSize: '0.95rem' }}>{exercise.name}</h4>
                <button
                  onClick={() => handleDelete(exercise.id)}
                  style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: '0.9rem', padding: '2px 4px', flexShrink: 0 }}
                >✕</button>
              </div>

              {exercise.description && (
                <p style={{
                  margin: 0, fontSize: '0.82rem', color: 'var(--text-secondary)', lineHeight: 1.6,
                  display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden'
                }}>
                  {exercise.description}
                </p>
              )}

              {exercise.hashtags && exercise.hashtags.length > 0 && (
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5 }}>
                  {exercise.hashtags.map(tag => (
                    <span
                      key={tag}
                      onClick={() => setHashtagFilter(tag)}
                      style={{
                        padding: '2px 8px', borderRadius: 20,
                        background: 'rgba(37,99,235,0.1)', color: 'var(--gold)',
                        fontSize: '0.72rem', fontWeight: 600,
                        border: '1px solid rgba(37,99,235,0.2)', cursor: 'pointer'
                      }}
                    >
                      #{tag}
                    </span>
                  ))}
                </div>
              )}

              {exercise.images && exercise.images.length > 0 && (
                <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginTop: 4 }}>
                  {exercise.images.map((img, i) => (
                    <img key={i} src={img} alt="" style={{ width: 72, height: 54, objectFit: 'cover', borderRadius: 5, border: '1px solid var(--border)' }} />
                  ))}
                </div>
              )}
              {exercise.videoUrl && (
                <a
                  href={exercise.videoUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  style={{
                    display: 'flex', alignItems: 'center', gap: 6,
                    fontSize: '0.8rem', color: 'var(--gold)', textDecoration: 'none',
                    padding: '6px 10px', background: 'rgba(37,99,235,0.08)',
                    borderRadius: 6, border: '1px solid rgba(37,99,235,0.2)', marginTop: 'auto'
                  }}
                >
                  <span>▶</span><span>Pogledaj video</span>
                </a>
              )}
            </div>
          ))}
        </div>
      )}

      {/* ── Bottom banner ── */}
      <div style={{
        position: 'fixed', bottom: 0, left: 'var(--sidebar-width)', right: 0,
        background: 'linear-gradient(90deg, rgba(37,99,235,0.1), rgba(37,99,235,0.05))',
        borderTop: '1px solid rgba(37,99,235,0.2)',
        padding: '12px 24px', display: 'flex', alignItems: 'center', gap: 12, zIndex: 80
      }}>
        <span style={{ fontSize: '1.2rem' }}>⚽</span>
        <div>
          <div style={{ fontSize: '0.85rem', fontWeight: 700, color: 'var(--gold)' }}>Filter App Integracija Dolazi Uskoro</div>
          <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Pretraži hiljade vežbi po poziciji, uzrastu, težini i cilju treninga</div>
        </div>
      </div>

      {/* ── Manage Groups Modal ── */}
      <Modal
        isOpen={showGroupsModal}
        onClose={() => setShowGroupsModal(false)}
        title="⚙ Upravljaj grupama tagova"
        width={520}
        footer={<button className="btn btn-secondary" onClick={() => setShowGroupsModal(false)}>Zatvori</button>}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
          {groups.length === 0 && (
            <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', textAlign: 'center', margin: 0 }}>
              Nema grupa. Dodaj prvu grupu ispod.
            </p>
          )}

          {groups.map(group => (
            <div key={group.id} style={{ background: 'var(--bg-main)', borderRadius: 8, padding: 14, border: '1px solid var(--border)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
                <span style={{ fontWeight: 700, fontSize: '0.9rem' }}>{group.label}</span>
                <button
                  onClick={() => handleDeleteGroup(group)}
                  style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: '0.85rem' }}
                >
                  🗑 Obriši grupu
                </button>
              </div>

              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 10 }}>
                {(group.tags || []).map(tag => (
                  <span
                    key={tag}
                    style={{
                      display: 'flex', alignItems: 'center', gap: 4,
                      padding: '2px 8px', borderRadius: 20,
                      background: 'rgba(37,99,235,0.1)', color: 'var(--gold)',
                      fontSize: '0.76rem', fontWeight: 600,
                      border: '1px solid rgba(37,99,235,0.25)'
                    }}
                  >
                    #{tag}
                    <button
                      onClick={() => handleRemoveTagFromGroup(group, tag)}
                      style={{ background: 'none', border: 'none', color: 'var(--gold)', cursor: 'pointer', fontSize: '0.7rem', padding: '0 0 0 2px', opacity: 0.7 }}
                    >✕</button>
                  </span>
                ))}
                {(group.tags || []).length === 0 && (
                  <span style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>Nema tagova</span>
                )}
              </div>

              <div style={{ display: 'flex', gap: 8 }}>
                <input
                  className="input"
                  placeholder="Novi tag..."
                  value={newTagInputs[group.id] || ''}
                  onChange={e => setNewTagInputs(prev => ({ ...prev, [group.id]: e.target.value }))}
                  onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); handleAddTagToGroup(group); } }}
                  style={{ flex: 1, padding: '6px 12px', fontSize: '0.82rem' }}
                />
                <button className="btn btn-secondary" onClick={() => handleAddTagToGroup(group)} style={{ padding: '6px 14px', fontSize: '0.82rem' }}>
                  + Dodaj
                </button>
              </div>
            </div>
          ))}

          {/* New group */}
          <div style={{ borderTop: '1px solid var(--border)', paddingTop: 16 }}>
            <label className="label" style={{ marginBottom: 8, display: 'block' }}>Nova grupa</label>
            <div style={{ display: 'flex', gap: 8 }}>
              <input
                className="input"
                placeholder="Naziv grupe (npr. Tehnika, Uzrast...)"
                value={newGroupLabel}
                onChange={e => setNewGroupLabel(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); handleAddGroup(); } }}
                style={{ flex: 1 }}
              />
              <button className="btn btn-primary" onClick={handleAddGroup} disabled={!newGroupLabel.trim()}>
                Dodaj grupu
              </button>
            </div>
          </div>
        </div>
      </Modal>

      {/* ── Add Exercise Modal ── */}
      <Modal
        isOpen={isOpen}
        onClose={() => setIsOpen(false)}
        title="Dodaj novu vežbu"
        width={540}
        footer={
          <>
            {saveError && (
              <span style={{ color: 'var(--error)', fontSize: '0.78rem', flex: 1 }}>{saveError}</span>
            )}
            <button className="btn btn-secondary" onClick={() => setIsOpen(false)}>Otkaži</button>
            <button className="btn btn-primary" onClick={handleSubmit} disabled={saving || !form.name.trim()}>
              {saving ? 'Čuvam...' : 'Dodaj vežbu'}
            </button>
          </>
        }
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div className="form-group">
            <label className="label">Naziv vežbe *</label>
            <input
              className="input"
              placeholder="npr. Zig-zag dribling"
              value={form.name}
              onChange={e => setForm(p => ({ ...p, name: e.target.value }))}
            />
          </div>

          <div className="form-group">
            <label className="label">Opis</label>
            <textarea
              className="input"
              rows={3}
              placeholder="Detaljni opis izvođenja vežbe..."
              value={form.description}
              onChange={e => setForm(p => ({ ...p, description: e.target.value }))}
            />
          </div>

          <div className="form-group">
            <label className="label">Hashtagovi</label>

            {/* Selected tags */}
            {form.hashtags.length > 0 && (
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 10 }}>
                {form.hashtags.map(tag => (
                  <span
                    key={tag}
                    style={{
                      display: 'flex', alignItems: 'center', gap: 4,
                      padding: '3px 10px', borderRadius: 20,
                      background: 'rgba(37,99,235,0.18)', color: 'var(--gold)',
                      fontSize: '0.76rem', fontWeight: 600,
                      border: '1px solid rgba(37,99,235,0.4)'
                    }}
                  >
                    #{tag}
                    <button
                      onClick={() => toggleFormTag(tag)}
                      style={{ background: 'none', border: 'none', color: 'var(--gold)', cursor: 'pointer', fontSize: '0.7rem', padding: 0 }}
                    >✕</button>
                  </span>
                ))}
              </div>
            )}

            {/* Group suggestions */}
            {groups.length > 0 && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 10 }}>
                {groups.map(group => (
                  (group.tags || []).length > 0 && (
                    <div key={group.id} style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                      <span style={{ fontSize: '0.72rem', color: 'var(--text-muted)', fontWeight: 600, minWidth: 80 }}>
                        {group.label}
                      </span>
                      {group.tags.map(tag => (
                        <button
                          key={tag}
                          onClick={() => toggleFormTag(tag)}
                          style={{
                            ...CHIP.base,
                            ...(form.hashtags.includes(tag) ? CHIP.selected : CHIP.suggestion)
                          }}
                        >
                          #{tag}
                        </button>
                      ))}
                    </div>
                  )
                ))}
              </div>
            )}

            {/* Custom tag input */}
            <div style={{ display: 'flex', gap: 8 }}>
              <input
                className="input"
                placeholder="Sopstveni tag..."
                value={customTagInput}
                onChange={e => setCustomTagInput(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter' || e.key === ',') { e.preventDefault(); addCustomTag(); } }}
                style={{ flex: 1, fontSize: '0.85rem' }}
              />
              <button className="btn btn-secondary" onClick={addCustomTag} style={{ padding: '8px 14px', fontSize: '0.82rem' }}>
                + Dodaj
              </button>
            </div>
            <p style={{ fontSize: '0.73rem', color: 'var(--text-muted)', marginTop: 4 }}>
              Klikni na tag iz grupe ili upiši sopstveni
            </p>
          </div>

          <div className="form-group">
            <label className="label">Video link</label>
            <input
              className="input"
              placeholder="https://youtube.com/..."
              type="url"
              value={form.videoUrl}
              onChange={e => setForm(p => ({ ...p, videoUrl: e.target.value }))}
            />
          </div>

          <div className="form-group">
            <label className="label">Slike vežbe ({(form.images || []).length})</label>
            {(form.images || []).length > 0 && (
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 8 }}>
                {(form.images || []).map((img, idx) => (
                  <div key={idx} style={{ position: 'relative' }}>
                    <img src={img} alt="" style={{ width: 90, height: 70, objectFit: 'cover', borderRadius: 6, border: '1px solid var(--border)' }} />
                    <button onClick={() => setForm(p => ({ ...p, images: p.images.filter((_, i) => i !== idx) }))}
                      style={{ position: 'absolute', top: 3, right: 3, background: 'rgba(0,0,0,0.65)', border: 'none', borderRadius: '50%', width: 20, height: 20, cursor: 'pointer', color: '#fff', fontSize: '0.65rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
                  </div>
                ))}
              </div>
            )}
            <label style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '9px 14px', border: '1px dashed var(--border)', borderRadius: 8, cursor: imgLoading ? 'wait' : 'pointer', color: 'var(--text-muted)', fontSize: '0.85rem' }}
              onMouseEnter={e => e.currentTarget.style.borderColor = 'var(--gold)'}
              onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}
            >
              <input ref={imgInputRef} type="file" accept="image/*" multiple onChange={handleExerciseImages} style={{ display: 'none' }} disabled={imgLoading} />
              <span style={{ fontSize: '1.1rem' }}>📷</span>
              <span>{imgLoading ? 'Učitavam...' : '+ Dodaj slike'}</span>
            </label>
          </div>
        </div>
      </Modal>
    </div>
  );
}
