import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../auth/AuthContext';
import { useTrainings } from '../../hooks/useTrainings';
import { formatDate } from '../../utils/helpers';

function toDateKey(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

const MONTHS_SR = ['Januar', 'Februar', 'Mart', 'April', 'Maj', 'Jun', 'Jul', 'Avgust', 'Septembar', 'Oktobar', 'Novembar', 'Decembar'];
const DAYS_SHORT = ['Ned', 'Pon', 'Uto', 'Sre', 'Čet', 'Pet', 'Sub'];

export default function PlayerPlaner() {
  const { playerId } = useAuth();
  const { trainings, loading } = useTrainings();
  const navigate = useNavigate();
  const [view, setView] = useState('list');
  const [calDate, setCalDate] = useState(new Date());

  const myTrainings = useMemo(() =>
    trainings
      .filter(t => t.playerIds?.includes(playerId))
      .sort((a, b) => (b.date + (b.time || '')).localeCompare(a.date + (a.time || ''))),
    [trainings, playerId]
  );

  const today = toDateKey(new Date());

  // Calendar
  const year = calDate.getFullYear();
  const month = calDate.getMonth();
  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const trainingDays = new Set(myTrainings.filter(t => t.date?.startsWith(`${year}-${String(month + 1).padStart(2, '0')}`)).map(t => t.date));

  const prevMonth = () => setCalDate(new Date(year, month - 1, 1));
  const nextMonth = () => setCalDate(new Date(year, month + 1, 1));

  if (loading) return <div style={{ textAlign: 'center', padding: 20, color: 'var(--text-muted)' }}>Učitavam...</div>;

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <h1 style={{ fontSize: '1.15rem', fontWeight: 700, margin: 0 }}>📅 Planer treninga</h1>
        <div style={{ display: 'flex', gap: 4 }}>
          {['list', 'cal'].map(v => (
            <button
              key={v}
              onClick={() => setView(v)}
              style={{
                padding: '4px 12px',
                borderRadius: 20,
                border: '1px solid',
                borderColor: view === v ? 'var(--gold)' : 'var(--border)',
                background: view === v ? 'rgba(37,99,235,0.15)' : 'transparent',
                color: view === v ? 'var(--gold)' : 'var(--text-muted)',
                fontSize: '0.78rem',
                fontWeight: 600,
                cursor: 'pointer'
              }}
            >
              {v === 'list' ? 'Lista' : 'Kalendar'}
            </button>
          ))}
        </div>
      </div>

      {view === 'cal' && (
        <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: 16, marginBottom: 16 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
            <button onClick={prevMonth} style={{ background: 'none', border: 'none', color: 'var(--text-secondary)', fontSize: '1.2rem', cursor: 'pointer' }}>‹</button>
            <span style={{ fontWeight: 700 }}>{MONTHS_SR[month]} {year}</span>
            <button onClick={nextMonth} style={{ background: 'none', border: 'none', color: 'var(--text-secondary)', fontSize: '1.2rem', cursor: 'pointer' }}>›</button>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2, textAlign: 'center' }}>
            {DAYS_SHORT.map(d => (
              <div key={d} style={{ fontSize: '0.7rem', color: 'var(--text-muted)', padding: '4px 0', fontWeight: 600 }}>{d}</div>
            ))}
            {Array.from({ length: firstDay }, (_, i) => <div key={`e${i}`} />)}
            {Array.from({ length: daysInMonth }, (_, i) => {
              const day = i + 1;
              const dk = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const hasTraining = trainingDays.has(dk);
              const isToday = dk === today;
              return (
                <div
                  key={day}
                  style={{
                    padding: '6px 0',
                    borderRadius: 6,
                    fontSize: '0.85rem',
                    fontWeight: isToday ? 700 : 400,
                    background: isToday ? 'rgba(37,99,235,0.2)' : 'transparent',
                    color: isToday ? 'var(--gold)' : 'var(--text-primary)',
                    position: 'relative'
                  }}
                >
                  {day}
                  {hasTraining && (
                    <div style={{ width: 5, height: 5, borderRadius: '50%', background: 'var(--gold)', margin: '2px auto 0' }} />
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* List */}
      {myTrainings.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '32px 20px', background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', color: 'var(--text-muted)' }}>
          <div style={{ fontSize: '2rem', marginBottom: 8 }}>📅</div>
          <div>Nema treninga</div>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          {myTrainings.map(t => {
            const isPast = t.date < today;
            const isCompleted = t.completed;
            return (
              <div
                key={t.id}
                onClick={() => isCompleted && navigate(`/player/trening/${t.id}`)}
                style={{
                  background: 'var(--bg-card)',
                  border: `1px solid ${t.date === today ? 'rgba(37,99,235,0.4)' : 'var(--border)'}`,
                  borderRadius: 'var(--radius)',
                  padding: '12px 14px',
                  cursor: isCompleted ? 'pointer' : 'default',
                  opacity: isPast && !isCompleted ? 0.6 : 1
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 10 }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 600, fontSize: '0.95rem' }}>{t.name}</div>
                    <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', marginTop: 3 }}>
                      📅 {formatDate(t.date)} {t.time && `• 🕐 ${t.time}`} {t.duration && `• ${t.duration} min`}
                    </div>
                    {t.note && (
                      <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', marginTop: 4, fontStyle: 'italic' }}>
                        📋 {t.note}
                      </div>
                    )}
                    {isCompleted && t.trainingNote && (
                      <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', marginTop: 4 }}>
                        🗒 {t.trainingNote}
                      </div>
                    )}
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 6, flexShrink: 0 }}>
                    <div style={{ fontSize: '0.75rem', fontWeight: 600 }}>
                      {isCompleted
                        ? <span style={{ color: 'var(--success)' }}>✓ Završen</span>
                        : t.date > today
                          ? <span style={{ color: 'var(--gold)' }}>Predstojeći</span>
                          : <span style={{ color: 'var(--text-muted)' }}>Nije završen</span>
                      }
                    </div>
                    {(() => { const img = t.images?.[0] || t.imageBase64; return img ? <img src={img} alt="" style={{ width: 52, height: 40, objectFit: 'cover', borderRadius: 5, border: '1px solid var(--border)' }} /> : null; })()}
                  </div>
                </div>
                {isCompleted && (
                  <div style={{ marginTop: 6, fontSize: '0.75rem', color: 'var(--gold)' }}>
                    Tap za ocenu treninga →
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
