import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { createUserWithEmailAndPassword } from 'firebase/auth';
import { ref, get, set } from 'firebase/database';
import { auth, db } from '../firebase';

export default function InviteRegister() {
  const { token } = useParams(); // token = player.id
  const navigate = useNavigate();
  const [player, setPlayer] = useState(null);
  const [loadError, setLoadError] = useState('');
  const [loadDone, setLoadDone] = useState(false);

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [password2, setPassword2] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!token) { setLoadError('Nevažeći link.'); setLoadDone(true); return; }
    get(ref(db, `players/${token}`)).then(snap => {
      const data = snap.val();
      if (!data) {
        setLoadError('Igrač nije pronađen.');
      } else {
        setPlayer({ id: token, ...data });
      }
      setLoadDone(true);
    }).catch(() => {
      setLoadError('Greška pri učitavanju.');
      setLoadDone(true);
    });
  }, [token]);

  const handleRegister = async (e) => {
    e.preventDefault();
    if (!email.trim() || !password || password !== password2) return;
    if (password.length < 6) { setError('Lozinka mora imati najmanje 6 karaktera.'); return; }
    setLoading(true);
    setError('');
    try {
      const cred = await createUserWithEmailAndPassword(auth, email.trim(), password);
      await set(ref(db, `users/${cred.user.uid}`), {
        role: 'player',
        playerId: token,
        email: email.trim(),
        createdAt: new Date().toISOString()
      });
      window.location.replace('https://fudbalskilab-hkr.github.io/JGK/#/player/pocetna');
    } catch (err) {
      const code = err.code || '';
      if (code.includes('email-already-in-use')) {
        setError('Ovaj email je već registrovan. Prijavi se na login stranici.');
      } else if (code.includes('invalid-email')) {
        setError('Nevažeća email adresa.');
      } else {
        setError('Greška pri registraciji. Pokušajte ponovo.');
      }
    } finally {
      setLoading(false);
    }
  };

  if (!loadDone) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg-primary)' }}>
        <div className="loading-spinner" />
      </div>
    );
  }

  if (loadError) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg-primary)', padding: 20 }}>
        <div style={{ textAlign: 'center', maxWidth: 340 }}>
          <div style={{ fontSize: '3rem', marginBottom: 12 }}>⚠️</div>
          <h2 style={{ marginBottom: 8 }}>Nevažeći link</h2>
          <p style={{ color: 'var(--text-muted)', fontSize: '0.9rem', marginBottom: 20 }}>{loadError}</p>
          <button className="btn btn-secondary" onClick={() => navigate('/login')}>← Prijava</button>
        </div>
      </div>
    );
  }

  const fullName = `${player.firstName || ''} ${player.lastName || ''}`.trim() || 'Igrač';

  return (
    <div style={{
      minHeight: '100vh',
      background: 'var(--bg-primary)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 20
    }}>
      <div style={{
        width: '100%',
        maxWidth: 380,
        background: 'var(--bg-card)',
        border: '1px solid var(--border)',
        borderRadius: 'var(--radius-lg)',
        padding: '32px 28px'
      }}>
        <div style={{ textAlign: 'center', marginBottom: 24 }}>
          <div style={{ fontSize: '2.5rem', marginBottom: 8 }}>⚽</div>
          <h1 style={{ fontSize: '1.3rem', fontWeight: 700, margin: 0 }}>Registracija igrača</h1>
          <div style={{
            marginTop: 10,
            background: 'rgba(59,130,246,0.1)',
            border: '1px solid rgba(59,130,246,0.3)',
            borderRadius: 8,
            padding: '8px 12px',
            fontSize: '0.85rem',
            color: 'var(--gold)'
          }}>
            👋 Zdravo, <strong>{fullName}</strong>
          </div>
        </div>

        <form onSubmit={handleRegister} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <div className="form-group">
            <label className="label">Email adresa</label>
            <input
              className="input"
              type="email"
              placeholder="tvoj@email.com"
              value={email}
              onChange={e => setEmail(e.target.value)}
              autoComplete="email"
              disabled={loading}
            />
          </div>

          <div className="form-group">
            <label className="label">Lozinka</label>
            <input
              className="input"
              type="password"
              placeholder="Najmanje 6 karaktera"
              value={password}
              onChange={e => setPassword(e.target.value)}
              autoComplete="new-password"
              disabled={loading}
            />
          </div>

          <div className="form-group">
            <label className="label">Potvrdi lozinku</label>
            <input
              className="input"
              type="password"
              placeholder="Ponovi lozinku"
              value={password2}
              onChange={e => setPassword2(e.target.value)}
              autoComplete="new-password"
              disabled={loading}
            />
            {password && password2 && password !== password2 && (
              <span style={{ fontSize: '0.78rem', color: 'var(--error)', marginTop: 4 }}>Lozinke se ne poklapaju.</span>
            )}
          </div>

          {error && (
            <div style={{ background: 'var(--error-bg)', border: '1px solid var(--error)', borderRadius: 'var(--radius-sm)', padding: '8px 12px', fontSize: '0.82rem', color: 'var(--error)' }}>
              {error}
            </div>
          )}

          <button
            type="submit"
            className="btn btn-primary"
            disabled={loading || !email.trim() || !password || password !== password2}
            style={{ marginTop: 4, height: 44, fontSize: '0.95rem' }}
          >
            {loading ? 'Registrujem...' : 'Kreiraj nalog'}
          </button>
        </form>

        <p style={{ textAlign: 'center', fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 16 }}>
          Već imaš nalog? <span style={{ color: 'var(--gold)', cursor: 'pointer' }} onClick={() => navigate('/login')}>Prijavi se</span>
        </p>
      </div>
    </div>
  );
}
