import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../auth/AuthContext';
import { useMyPlayer } from '../../hooks/useMyPlayer';
import Avatar from '../../components/common/Avatar';
import { getAge, getCategory } from '../../utils/helpers';

async function compressImage(file, maxWidth = 600, quality = 0.75) {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let { width, height } = img;
        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        canvas.getContext('2d').drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', quality));
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}

export default function PlayerMyProfile() {
  const { playerId, logout } = useAuth();
  const { player, loading, updateMyPlayer } = useMyPlayer(playerId);
  const photoInputRef = useRef(null);

  const [editMode, setEditMode] = useState(false);
  const [form, setForm] = useState({
    phone: '', email: '', personalGoal: '', goal6months: '', goal12months: '', photoBase64: ''
  });
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [photoLoading, setPhotoLoading] = useState(false);

  useEffect(() => {
    if (player) {
      setForm({
        phone: player.phone || '',
        email: player.email || '',
        personalGoal: player.personalGoal || '',
        goal6months: player.goal6months || '',
        goal12months: player.goal12months || '',
        photoBase64: player.photoBase64 || ''
      });
    }
  }, [player]);

  const handlePhotoChange = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setPhotoLoading(true);
    try {
      const compressed = await compressImage(file);
      setForm(p => ({ ...p, photoBase64: compressed }));
    } finally {
      setPhotoLoading(false);
      if (photoInputRef.current) photoInputRef.current.value = '';
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await updateMyPlayer({
        phone: form.phone.trim(),
        email: form.email.trim(),
        personalGoal: form.personalGoal.trim(),
        goal6months: form.goal6months.trim(),
        goal12months: form.goal12months.trim(),
        ...(form.photoBase64 ? { photoBase64: form.photoBase64 } : {})
      });
      setSaved(true);
      setEditMode(false);
      setTimeout(() => setSaved(false), 2500);
    } finally {
      setSaving(false);
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: 20, color: 'var(--text-muted)' }}>Učitavam...</div>;
  if (!player) return <div style={{ textAlign: 'center', padding: 20, color: 'var(--text-muted)' }}>Igrač nije pronađen</div>;

  const fullName = `${player.firstName || ''} ${player.lastName || ''}`.trim() || 'Nepoznat';
  const age = getAge(player.birthYear);
  const category = getCategory(player.birthYear);
  const displayPhoto = editMode ? form.photoBase64 : player.photoBase64;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      {/* Header */}
      <div style={{
        background: 'var(--bg-card)',
        border: '1px solid var(--border)',
        borderRadius: 'var(--radius-lg)',
        padding: 20,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        textAlign: 'center',
        gap: 10
      }}>
        <div style={{ position: 'relative' }}>
          <Avatar src={displayPhoto} name={fullName} size="xl" />
          {editMode && (
            <>
              <button
                onClick={() => photoInputRef.current?.click()}
                disabled={photoLoading}
                style={{
                  position: 'absolute',
                  bottom: 0,
                  right: 0,
                  width: 28,
                  height: 28,
                  borderRadius: '50%',
                  background: 'var(--gold)',
                  border: 'none',
                  cursor: 'pointer',
                  fontSize: '0.8rem',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
              >
                {photoLoading ? '...' : '📷'}
              </button>
              <input ref={photoInputRef} type="file" accept="image/*" style={{ display: 'none' }} onChange={handlePhotoChange} />
            </>
          )}
        </div>
        <div>
          <h1 style={{ fontSize: '1.2rem', fontWeight: 700, margin: 0 }}>{fullName}</h1>
          <div style={{ fontSize: '0.82rem', color: 'var(--text-muted)', marginTop: 4 }}>
            {category} {age && `• ${age} god.`} {player.club && `• ${player.club}`}
          </div>
        </div>
        {saved && (
          <div style={{ fontSize: '0.82rem', color: 'var(--success)', fontWeight: 600 }}>✓ Sačuvano</div>
        )}
      </div>

      {/* Kontakt podaci */}
      <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '16px 20px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
          <h2 style={{ fontSize: '0.95rem', fontWeight: 700, margin: 0 }}>Kontakt podaci</h2>
          {!editMode ? (
            <button onClick={() => setEditMode(true)} style={{ fontSize: '0.8rem', color: 'var(--gold)', background: 'none', border: 'none', cursor: 'pointer' }}>✏️ Uredi</button>
          ) : (
            <div style={{ display: 'flex', gap: 8 }}>
              <button onClick={() => setEditMode(false)} style={{ fontSize: '0.78rem', color: 'var(--text-muted)', background: 'none', border: 'none', cursor: 'pointer' }}>Otkaži</button>
              <button onClick={handleSave} disabled={saving} style={{ fontSize: '0.78rem', color: 'var(--gold)', background: 'none', border: 'none', cursor: 'pointer', fontWeight: 700 }}>
                {saving ? 'Čuvam...' : 'Sačuvaj'}
              </button>
            </div>
          )}
        </div>

        {editMode ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            <div className="form-group">
              <label className="label">Telefon</label>
              <input className="input" type="tel" value={form.phone} onChange={e => setForm(p => ({ ...p, phone: e.target.value }))} placeholder="+381..." />
            </div>
            <div className="form-group">
              <label className="label">Email</label>
              <input className="input" type="email" value={form.email} onChange={e => setForm(p => ({ ...p, email: e.target.value }))} placeholder="tvoj@email.com" />
            </div>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            <InfoRow icon="📱" label="Telefon" value={player.phone || '—'} />
            <InfoRow icon="📧" label="Email" value={player.email || '—'} />
            {player.height && <InfoRow icon="📏" label="Visina" value={`${player.height} cm`} />}
            {player.weight && <InfoRow icon="⚖️" label="Težina" value={`${player.weight} kg`} />}
            {player.dominantFoot && (
              <InfoRow icon="👟" label="Noga" value={player.dominantFoot === 'desna' ? 'Desna' : player.dominantFoot === 'leva' ? 'Leva' : 'Obe'} />
            )}
          </div>
        )}
      </div>

      {/* Ciljevi */}
      <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '16px 20px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
          <h2 style={{ fontSize: '0.95rem', fontWeight: 700, margin: 0 }}>🎯 Moji ciljevi</h2>
          {!editMode && (
            <button onClick={() => setEditMode(true)} style={{ fontSize: '0.8rem', color: 'var(--gold)', background: 'none', border: 'none', cursor: 'pointer' }}>✏️ Uredi</button>
          )}
        </div>
        {editMode ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            <div className="form-group">
              <label className="label">Cilj za 6 meseci</label>
              <textarea className="input" rows={2} placeholder="Šta želiš da postigneš za 6 meseci?" value={form.goal6months} onChange={e => setForm(p => ({ ...p, goal6months: e.target.value }))} />
            </div>
            <div className="form-group">
              <label className="label">Cilj za godinu dana</label>
              <textarea className="input" rows={2} placeholder="Šta želiš da postigneš za godinu dana?" value={form.goal12months} onChange={e => setForm(p => ({ ...p, goal12months: e.target.value }))} />
            </div>
            <div className="form-group">
              <label className="label">Lični cilj (opšte)</label>
              <textarea className="input" rows={2} placeholder="Šta je tvoj cilj ove sezone?" value={form.personalGoal} onChange={e => setForm(p => ({ ...p, personalGoal: e.target.value }))} />
            </div>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            <GoalRow label="Za 6 meseci" value={player.goal6months} />
            <GoalRow label="Za godinu dana" value={player.goal12months} />
            <GoalRow label="Lični cilj" value={player.personalGoal} />
          </div>
        )}
      </div>

      <button
        onClick={logout}
        style={{ background: 'transparent', border: '1px solid var(--border)', borderRadius: 'var(--radius)', color: 'var(--error)', padding: '12px', cursor: 'pointer', fontSize: '0.9rem', fontWeight: 600 }}
      >
        Odjavi se
      </button>
    </div>
  );
}

function InfoRow({ icon, label, value }) {
  return (
    <div style={{ display: 'flex', gap: 10, alignItems: 'center', fontSize: '0.85rem' }}>
      <span style={{ width: 20 }}>{icon}</span>
      <span style={{ color: 'var(--text-muted)', width: 60 }}>{label}</span>
      <span style={{ fontWeight: 500 }}>{value}</span>
    </div>
  );
}

function GoalRow({ label, value }) {
  return (
    <div>
      <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginBottom: 3, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.04em' }}>{label}</div>
      <div style={{ fontSize: '0.88rem', color: value ? 'var(--text-primary)' : 'var(--text-muted)', fontStyle: value ? 'normal' : 'italic' }}>
        {value || 'Nije postavljeno'}
      </div>
    </div>
  );
}
