import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { usePlayers } from '../../hooks/usePlayers';

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'Maj', 'Jun', 'Jul', 'Avg', 'Sep', 'Okt', 'Nov', 'Dec'];

const STATUS_CYCLE = { unpaid: 'paid', paid: 'pending', pending: 'unpaid' };

const STATUS_STYLE = {
  paid:    { background: 'rgba(34,197,94,0.15)',  color: '#22c55e', border: '1px solid rgba(34,197,94,0.3)',  label: '✓' },
  pending: { background: 'rgba(245,158,11,0.15)', color: '#f59e0b', border: '1px solid rgba(245,158,11,0.3)', label: '~' },
  unpaid:  { background: 'rgba(239,68,68,0.1)',   color: '#ef4444', border: '1px solid rgba(239,68,68,0.25)', label: '✗' },
};

export default function MembershipPage() {
  const { players, loading, updatePayment } = usePlayers();
  const navigate = useNavigate();
  const currentYear = new Date().getFullYear();
  const [year, setYear] = useState(currentYear);

  const sorted = [...players].sort((a, b) =>
    `${a.firstName} ${a.lastName}`.localeCompare(`${b.firstName} ${b.lastName}`)
  );

  const getPayment = (player, month) => {
    return player.payments?.[year]?.[month] || { status: 'unpaid' };
  };

  const handleCellClick = async (player, month) => {
    const current = getPayment(player, month);
    const nextStatus = STATUS_CYCLE[current.status] || 'paid';
    await updatePayment(player.id, year, month, {
      status: nextStatus,
      amount: player.monthlyPrice || 0,
      date: nextStatus === 'paid' ? new Date().toISOString() : null
    });
  };

  const getDebt = (player) => {
    const price = player.monthlyPrice || 0;
    let debt = 0;
    for (let m = 0; m < 12; m++) {
      const p = getPayment(player, m);
      if (p.status !== 'paid') debt += price;
    }
    return debt;
  };

  const totalDebt = sorted.reduce((sum, p) => sum + getDebt(p), 0);

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner" />
      </div>
    );
  }

  return (
    <div>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 24, flexWrap: 'wrap', gap: 12 }}>
        <div>
          <h1 style={{ fontSize: '1.4rem', margin: 0 }}>Evidencija članarina</h1>
          {totalDebt > 0 && (
            <div style={{ fontSize: '0.82rem', color: '#ef4444', marginTop: 4 }}>
              Ukupan dug: {totalDebt.toLocaleString('sr-RS')} RSD
            </div>
          )}
        </div>

        {/* Year selector */}
        <div style={{ display: 'flex', gap: 6 }}>
          {[currentYear - 1, currentYear, currentYear + 1].map(y => (
            <button
              key={y}
              className={`btn btn-sm ${year === y ? '' : 'btn-secondary'}`}
              onClick={() => setYear(y)}
              style={year === y ? { background: 'var(--gold)', color: '#000', fontWeight: 700 } : {}}
            >
              {y}
            </button>
          ))}
        </div>
      </div>

      {/* Legenda */}
      <div style={{ display: 'flex', gap: 16, marginBottom: 16, flexWrap: 'wrap' }}>
        {Object.entries(STATUS_STYLE).map(([key, s]) => (
          <div key={key} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: '0.78rem', color: 'var(--text-secondary)' }}>
            <span style={{ ...cellBase, ...s, width: 24, height: 24, fontSize: '0.75rem' }}>{s.label}</span>
            {key === 'paid' ? 'Plaćeno' : key === 'pending' ? 'Na čekanju' : 'Nije plaćeno'}
          </div>
        ))}
        <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', marginLeft: 'auto' }}>
          Klik na ćeliju menja status
        </div>
      </div>

      {/* Tabela */}
      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: 900 }}>
          <thead>
            <tr>
              <th style={thStyle}>Igrač</th>
              {MONTHS.map(m => (
                <th key={m} style={{ ...thStyle, textAlign: 'center', width: 52 }}>{m}</th>
              ))}
              <th style={{ ...thStyle, textAlign: 'right' }}>Dug</th>
            </tr>
          </thead>
          <tbody>
            {sorted.length === 0 && (
              <tr>
                <td colSpan={14} style={{ textAlign: 'center', padding: 40, color: 'var(--text-muted)' }}>
                  Nema igrača
                </td>
              </tr>
            )}
            {sorted.map((player, i) => {
              const debt = getDebt(player);
              const fullName = `${player.firstName || ''} ${player.lastName || ''}`.trim();
              return (
                <tr key={player.id} style={{ background: i % 2 === 0 ? 'transparent' : 'rgba(255,255,255,0.02)' }}>
                  <td style={tdStyle}>
                    <span
                      onClick={() => navigate(`/igrac/${player.id}`)}
                      style={{ cursor: 'pointer', color: 'var(--text-primary)', fontWeight: 500, fontSize: '0.88rem' }}
                      onMouseEnter={e => e.currentTarget.style.color = 'var(--gold)'}
                      onMouseLeave={e => e.currentTarget.style.color = 'var(--text-primary)'}
                    >
                      {fullName || 'Nepoznat'}
                    </span>
                  </td>
                  {Array.from({ length: 12 }, (_, m) => {
                    const pay = getPayment(player, m);
                    const s = STATUS_STYLE[pay.status] || STATUS_STYLE.unpaid;
                    const isCurrentMonth = year === currentYear && m === new Date().getMonth();
                    return (
                      <td key={m} style={{ ...tdStyle, textAlign: 'center', padding: '8px 4px' }}>
                        <button
                          onClick={() => handleCellClick(player, m)}
                          title={pay.date ? new Date(pay.date).toLocaleDateString('sr-RS') : ''}
                          style={{
                            ...cellBase,
                            ...s,
                            outline: isCurrentMonth ? '2px solid var(--gold)' : 'none',
                            outlineOffset: 1
                          }}
                        >
                          {s.label}
                        </button>
                      </td>
                    );
                  })}
                  <td style={{ ...tdStyle, textAlign: 'right', fontSize: '0.82rem', color: debt > 0 ? '#ef4444' : '#22c55e', fontWeight: 600 }}>
                    {debt > 0 ? `${debt.toLocaleString('sr-RS')} RSD` : '✓'}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const thStyle = {
  padding: '10px 12px',
  textAlign: 'left',
  fontSize: '0.72rem',
  fontWeight: 700,
  color: 'var(--text-muted)',
  letterSpacing: '0.08em',
  textTransform: 'uppercase',
  borderBottom: '1px solid var(--border)',
  background: 'var(--bg-card)',
  position: 'sticky',
  top: 0
};

const tdStyle = {
  padding: '10px 12px',
  borderBottom: '1px solid rgba(255,255,255,0.04)',
  verticalAlign: 'middle'
};

const cellBase = {
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  width: 30,
  height: 30,
  borderRadius: 6,
  fontSize: '0.8rem',
  fontWeight: 700,
  cursor: 'pointer',
  transition: 'opacity 0.15s',
  background: 'none',
  padding: 0
};
