import * as XLSX from 'xlsx';
import { getCategory } from './helpers';

// ── IMPORT ────────────────────────────────────────────────────────────────────

const COL_MAP = {
  'ime': 'firstName',
  'prezime': 'lastName',
  'pozicija': 'position',
  'godiste': 'birthYear',
  'godište': 'birthYear',
  'klub': 'club',
  'dominantna noga': 'dominantFoot',
  'visina (cm)': 'height',
  'visina': 'height',
  'tezina (kg)': 'weight',
  'težina (kg)': 'weight',
  'tezina': 'weight',
  'težina': 'weight',
  'kontakt roditelja': 'parentContact',
  'mesecna cena (rsd)': 'monthlyPrice',
  'mesečna cena (rsd)': 'monthlyPrice',
  'mesecna cena': 'monthlyPrice',
  'mesečna cena': 'monthlyPrice',
};

const FOOT_MAP = {
  'desna': 'desna', 'leva': 'leva', 'obe': 'obe',
  'right': 'desna', 'left': 'leva', 'both': 'obe',
};

export function parseExcelImport(file, existingPlayers) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const wb = XLSX.read(e.target.result, { type: 'array' });
        const ws = wb.Sheets[wb.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

        if (rows.length < 2) {
          resolve({ added: [], skipped: [], errors: ['Fajl je prazan.'] });
          return;
        }

        // Map header row to field names
        const headers = rows[0].map(h => (h || '').toString().toLowerCase().trim());
        const fieldMap = {};
        headers.forEach((h, i) => {
          if (COL_MAP[h]) fieldMap[i] = COL_MAP[h];
        });

        const added = [];
        const skipped = [];
        const errors = [];

        // Existing players set for duplicate check
        const existingSet = new Set(
          existingPlayers.map(p =>
            `${(p.firstName || '').toLowerCase()}|${(p.lastName || '').toLowerCase()}|${p.birthYear || ''}`
          )
        );

        for (let i = 1; i < rows.length; i++) {
          const row = rows[i];
          if (row.every(cell => !cell && cell !== 0)) continue; // skip empty rows

          const player = {
            firstName: '', lastName: '', position: 'ST', birthYear: null,
            club: '', dominantFoot: 'desna', height: null, weight: null,
            parentContact: '', monthlyPrice: 0,
          };

          Object.entries(fieldMap).forEach(([colIdx, field]) => {
            const val = (row[colIdx] || '').toString().trim();
            if (!val) return;
            if (field === 'birthYear' || field === 'height' || field === 'weight') {
              player[field] = parseInt(val) || null;
            } else if (field === 'monthlyPrice') {
              player[field] = parseFloat(val) || 0;
            } else if (field === 'dominantFoot') {
              player[field] = FOOT_MAP[val.toLowerCase()] || 'desna';
            } else {
              player[field] = val;
            }
          });

          if (!player.firstName || !player.lastName) {
            errors.push(`Red ${i + 1}: nedostaje ime ili prezime`);
            continue;
          }

          const key = `${player.firstName.toLowerCase()}|${player.lastName.toLowerCase()}|${player.birthYear || ''}`;
          if (existingSet.has(key)) {
            skipped.push(`${player.firstName} ${player.lastName}`);
          } else {
            existingSet.add(key);
            added.push(player);
          }
        }

        resolve({ added, skipped, errors });
      } catch (err) {
        reject(new Error('Greška pri čitanju fajla: ' + err.message));
      }
    };
    reader.onerror = () => reject(new Error('Greška pri učitavanju fajla.'));
    reader.readAsArrayBuffer(file);
  });
}

// ── EXPORT ────────────────────────────────────────────────────────────────────

export function exportPlayersToExcel(players, filterLabel = 'Svi') {
  const headers = [
    'Ime', 'Prezime', 'Pozicija', 'Godište', 'Klub',
    'Dominantna noga', 'Visina (cm)', 'Težina (kg)',
    'Kontakt roditelja', 'Mesečna cena (RSD)', 'Kategorija', 'Članarina'
  ];

  const footLabel = { desna: 'Desna', leva: 'Leva', obe: 'Obe' };
  const memberLabel = { paid: 'Plaćeno', unpaid: 'Nije plaćeno', pending: 'Na čekanju' };

  const rows = players.map(p => [
    p.firstName || '',
    p.lastName || '',
    p.position || '',
    p.birthYear || '',
    p.club || '',
    footLabel[p.dominantFoot] || p.dominantFoot || '',
    p.height || '',
    p.weight || '',
    p.parentContact || '',
    p.monthlyPrice || 0,
    getCategory(p.birthYear) || '',
    memberLabel[p.membershipStatus] || 'Nije plaćeno',
  ]);

  const ws = XLSX.utils.aoa_to_sheet([headers, ...rows]);
  ws['!cols'] = [
    {wch:12},{wch:15},{wch:10},{wch:8},{wch:20},
    {wch:16},{wch:10},{wch:10},{wch:22},{wch:18},{wch:10},{wch:14}
  ];

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Igrači');

  const date = new Date().toISOString().split('T')[0];
  const safeName = filterLabel.replace(/[^a-zA-Z0-9]/g, '_');
  XLSX.writeFile(wb, `Igraci_${safeName}_${date}.xlsx`);
}
