import { useState, useEffect } from 'react';
import { ref, onValue, push, set, update, remove } from 'firebase/database';
import { db } from '../firebase';
import { notifyPlayer } from '../utils/notifications';

export function usePlayers() {
  const [players, setPlayers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const playersRef = ref(db, 'players');

    const unsubscribe = onValue(
      playersRef,
      (snapshot) => {
        const data = snapshot.val();
        if (data) {
          const playersArray = Object.entries(data).map(([id, val]) => ({
            id,
            ...val
          }));
          setPlayers(playersArray);
        } else {
          setPlayers([]);
        }
        setLoading(false);
      },
      (err) => {
        console.error('Error fetching players:', err);
        setError(err.message);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, []);

  const addPlayer = async (data) => {
    try {
      const playersRef = ref(db, 'players');
      const newRef = push(playersRef);
      await set(newRef, {
        ...data,
        createdAt: new Date().toISOString(),
        membershipStatus: 'unpaid'
      });
      return newRef.key;
    } catch (err) {
      console.error('Error adding player:', err);
      throw err;
    }
  };

  const updatePlayer = async (id, data) => {
    try {
      const playerRef = ref(db, `players/${id}`);
      await update(playerRef, data);
    } catch (err) {
      console.error('Error updating player:', err);
      throw err;
    }
  };

  const deletePlayer = async (id) => {
    try {
      const playerRef = ref(db, `players/${id}`);
      await remove(playerRef);
    } catch (err) {
      console.error('Error deleting player:', err);
      throw err;
    }
  };

  const updateAttendance = async (playerId, dateKey, present) => {
    try {
      const attendanceRef = ref(db, `players/${playerId}/attendances/${dateKey}`);
      await set(attendanceRef, { present, date: dateKey });
    } catch (err) {
      console.error('Error updating attendance:', err);
      throw err;
    }
  };

  const updatePayment = async (playerId, year, month, data) => {
    try {
      const paymentRef = ref(db, `players/${playerId}/payments/${year}/${month}`);
      await set(paymentRef, data);
    } catch (err) {
      console.error('Error updating payment:', err);
      throw err;
    }
  };

  const addAssessment = async (playerId, data) => {
    try {
      const assessRef = ref(db, `players/${playerId}/assessments`);
      const newRef = push(assessRef);
      await set(newRef, { ...data, createdAt: new Date().toISOString() });
      return newRef.key;
    } catch (err) {
      console.error('Error adding assessment:', err);
      throw err;
    }
  };

  const addGoal = async (playerId, data) => {
    try {
      const goalRef = ref(db, `players/${playerId}/goals`);
      const newRef = push(goalRef);
      await set(newRef, { ...data, createdAt: new Date().toISOString() });
      return newRef.key;
    } catch (err) {
      console.error('Error adding goal:', err);
      throw err;
    }
  };

  const updateGoal = async (playerId, goalId, data) => {
    try {
      const goalRef = ref(db, `players/${playerId}/goals/${goalId}`);
      await update(goalRef, data);
    } catch (err) {
      console.error('Error updating goal:', err);
      throw err;
    }
  };

  const deleteGoal = async (playerId, goalId) => {
    try {
      const goalRef = ref(db, `players/${playerId}/goals/${goalId}`);
      await remove(goalRef);
    } catch (err) {
      console.error('Error deleting goal:', err);
      throw err;
    }
  };

  const addTrainingNote = async (playerId, data) => {
    try {
      const noteRef = ref(db, `players/${playerId}/trainingNotes`);
      const newRef = push(noteRef);
      await set(newRef, { ...data, createdAt: new Date().toISOString() });
      notifyPlayer(playerId, {
        type: 'training_note',
        title: 'Nova napomena',
        message: (data.note || data.text || 'Trener je dodao napomenu').substring(0, 80),
        link: 'napomene'
      });
      return newRef.key;
    } catch (err) {
      console.error('Error adding training note:', err);
      throw err;
    }
  };

  const deleteTrainingNote = async (playerId, noteId) => {
    try {
      const noteRef = ref(db, `players/${playerId}/trainingNotes/${noteId}`);
      await remove(noteRef);
    } catch (err) {
      console.error('Error deleting training note:', err);
      throw err;
    }
  };

  const updateTrainingNote = async (playerId, noteId, data) => {
    try {
      const noteRef = ref(db, `players/${playerId}/trainingNotes/${noteId}`);
      await update(noteRef, data);
    } catch (err) {
      console.error('Error updating training note:', err);
      throw err;
    }
  };

  return {
    players,
    loading,
    error,
    addPlayer,
    updatePlayer,
    deletePlayer,
    updateAttendance,
    updatePayment,
    addAssessment,
    addGoal,
    updateGoal,
    deleteGoal,
    addTrainingNote,
    updateTrainingNote,
    deleteTrainingNote
  };
}
