import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { formatDate, getMonthName, PILLARS, getInitials, calculateAttendanceStats } from '../../utils/helpers';

const GOLD = [200, 134, 10];
const WHITE = [255, 255, 255];
const DARK = [26, 26, 26];
const GRAY = [100, 100, 100];
const LIGHT_GRAY = [40, 40, 40];
const SUCCESS_COLOR = [34, 197, 94];
const ERROR_COLOR = [239, 68, 68];
const WARNING_COLOR = [245, 158, 11];

function hexToRgb(hex) {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return [r, g, b];
}

function getScoreRgb(score) {
  if (!score) return GRAY;
  if (score < 4) return ERROR_COLOR;
  if (score < 7) return WARNING_COLOR;
  return SUCCESS_COLOR;
}

export async function generatePlayerReport(player, trainings, period) {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4'
  });

  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 20;
  const contentWidth = pageWidth - margin * 2;

  const fullName = `${player.firstName || ''} ${player.lastName || ''}`.trim();
  const today = new Date();
  const periodLabel = period === '3m' ? '3 meseca' : '6 meseci';

  // Calculate period start date
  const periodMonths = period === '3m' ? 3 : 6;
  const periodStart = new Date(today);
  periodStart.setMonth(periodStart.getMonth() - periodMonths);

  // Filter trainings for period
  const relevantTrainings = trainings.filter(t => {
    if (!t.playerIds || !t.playerIds.includes(player.id)) return false;
    if (!t.date) return false;
    const tDate = new Date(t.date);
    return tDate >= periodStart && tDate <= today;
  });

  // Attendance stats
  const attendanceStats = calculateAttendanceStats(player.attendances);

  // Get assessments
  const assessments = player.assessments
    ? Object.values(player.assessments).sort((a, b) => new Date(a.date) - new Date(b.date))
    : [];
  const initialAssessment = assessments[0];
  const latestAssessment = assessments[assessments.length - 1];

  // Goals
  const goals = player.goals
    ? Object.values(player.goals)
    : [];

  // Notes (last 10)
  const notes = player.trainingNotes
    ? Object.values(player.trainingNotes)
        .sort((a, b) => new Date(b.date) - new Date(a.date))
        .slice(0, 10)
    : [];

  // ============================================================
  // PAGE 1 - HEADER
  // ============================================================
  let y = margin;

  // Dark header background
  doc.setFillColor(15, 15, 15);
  doc.rect(0, 0, pageWidth, 55, 'F');

  // Gold accent line
  doc.setFillColor(...GOLD);
  doc.rect(0, 0, 4, 55, 'F');

  // Logo / Brand
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(...GOLD);
  doc.text('JEVRAGKlab', margin, 22);

  doc.setFontSize(11);
  doc.setTextColor(...GRAY);
  doc.text('G.K.lab · Individual Training App', margin, 30);

  // Report title
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(...GRAY);
  doc.text(`IZVEŠTAJ IGRAČA · ${periodLabel.toUpperCase()}`, pageWidth - margin, 20, { align: 'right' });
  doc.setFontSize(8);
  doc.text(`Generisano: ${formatDate(today)}`, pageWidth - margin, 28, { align: 'right' });

  y = 65;

  // ============================================================
  // PLAYER INFO SECTION
  // ============================================================

  // Player photo or initials circle
  const circleX = margin + 15;
  const circleY = y + 15;
  const circleR = 14;

  if (player.photoBase64 && player.photoBase64.startsWith('data:image')) {
    try {
      const format = player.photoBase64.includes('png') ? 'PNG' : 'JPEG';
      doc.addImage(
        player.photoBase64,
        format,
        circleX - circleR,
        circleY - circleR,
        circleR * 2,
        circleR * 2
      );
    } catch (e) {
      // Fallback to initials
      doc.setFillColor(...GOLD);
      doc.circle(circleX, circleY, circleR, 'F');
      doc.setFontSize(14);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(0, 0, 0);
      doc.text(getInitials(fullName), circleX, circleY + 5, { align: 'center' });
    }
  } else {
    doc.setFillColor(...GOLD);
    doc.circle(circleX, circleY, circleR, 'F');
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(0, 0, 0);
    doc.text(getInitials(fullName), circleX, circleY + 5, { align: 'center' });
  }

  // Player name and details
  const infoX = circleX + circleR + 10;

  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(255, 255, 255);
  doc.text(fullName || 'Nepoznat', infoX, y + 8);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(...GRAY);

  const details = [
    player.position && `Pozicija: ${player.position}`,
    player.club && `Klub: ${player.club}`,
    player.birthYear && `Godište: ${player.birthYear}`,
    player.height && `Visina: ${player.height} cm`,
    player.weight && `Težina: ${player.weight} kg`
  ].filter(Boolean);

  let detailY = y + 16;
  details.forEach(d => {
    doc.text(d, infoX, detailY);
    detailY += 6;
  });

  y = Math.max(y + 40, detailY + 5);

  // Period line
  doc.setFillColor(...LIGHT_GRAY);
  doc.roundedRect(margin, y, contentWidth, 12, 3, 3, 'F');
  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(...GRAY);
  doc.text(
    `Izveštajni period: ${formatDate(periodStart)} — ${formatDate(today)} (${periodLabel})`,
    pageWidth / 2,
    y + 8,
    { align: 'center' }
  );

  y += 20;

  // ============================================================
  // TRAINING STATISTICS
  // ============================================================

  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(...GOLD);
  doc.text('STATISTIKE TRENINGA', margin, y);

  // Gold underline
  doc.setDrawColor(...GOLD);
  doc.setLineWidth(0.5);
  doc.line(margin, y + 2, margin + 60, y + 2);

  y += 8;

  // Stats boxes
  const statBoxes = [
    {
      label: 'Treninga u periodu',
      value: relevantTrainings.length.toString(),
      color: GOLD
    },
    {
      label: 'Ukupno dolazaka',
      value: attendanceStats.present.toString(),
      color: SUCCESS_COLOR
    },
    {
      label: 'Propuštenih',
      value: attendanceStats.absent.toString(),
      color: ERROR_COLOR
    },
    {
      label: 'Procenat dolazaka',
      value: `${attendanceStats.percentage}%`,
      color: attendanceStats.percentage >= 80 ? SUCCESS_COLOR : attendanceStats.percentage >= 60 ? WARNING_COLOR : ERROR_COLOR
    }
  ];

  const boxWidth = (contentWidth - 12) / 4;
  statBoxes.forEach((box, i) => {
    const bx = margin + i * (boxWidth + 4);
    doc.setFillColor(...LIGHT_GRAY);
    doc.roundedRect(bx, y, boxWidth, 22, 2, 2, 'F');
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...box.color);
    doc.text(box.value, bx + boxWidth / 2, y + 12, { align: 'center' });
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(...GRAY);
    doc.text(box.label, bx + boxWidth / 2, y + 19, { align: 'center' });
  });

  y += 30;

  // ============================================================
  // PROGRESS SECTION
  // ============================================================

  if (assessments.length > 0) {
    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...GOLD);
    doc.text('NAPREDAK PO STUBOVIMA', margin, y);
    doc.setDrawColor(...GOLD);
    doc.line(margin, y + 2, margin + 70, y + 2);
    y += 10;

    // Progress table
    const tableData = PILLARS.map(pillar => {
      const initVal = initialAssessment ? (initialAssessment[pillar.key] || 0) : null;
      const latestVal = latestAssessment ? (latestAssessment[pillar.key] || 0) : null;
      const diff = (initVal !== null && latestVal !== null) ? latestVal - initVal : null;
      const diffStr = diff !== null ? (diff > 0 ? `+${diff}` : String(diff)) : '—';

      return [
        pillar.label,
        initVal !== null ? `${initVal}/10` : '—',
        latestVal !== null ? `${latestVal}/10` : '—',
        diffStr
      ];
    });

    doc.autoTable({
      startY: y,
      head: [['Stub', 'Početak', 'Trenutno', 'Razlika']],
      body: tableData,
      theme: 'grid',
      margin: { left: margin, right: margin },
      styles: {
        fillColor: [26, 26, 26],
        textColor: [200, 200, 200],
        fontSize: 9,
        cellPadding: 4,
        lineColor: [40, 40, 40],
        lineWidth: 0.3
      },
      headStyles: {
        fillColor: [30, 30, 30],
        textColor: GOLD,
        fontStyle: 'bold',
        fontSize: 9
      },
      columnStyles: {
        0: { fontStyle: 'bold' },
        3: {
          fontStyle: 'bold'
        }
      },
      didParseCell: (data) => {
        if (data.section === 'body' && data.column.index === 3) {
          const val = data.cell.raw;
          if (val && val.startsWith('+')) {
            data.cell.styles.textColor = SUCCESS_COLOR;
          } else if (val && val.startsWith('-')) {
            data.cell.styles.textColor = ERROR_COLOR;
          }
        }
        if (data.section === 'body' && (data.column.index === 1 || data.column.index === 2)) {
          const val = parseInt(data.cell.raw);
          if (!isNaN(val)) {
            data.cell.styles.textColor = getScoreRgb(val);
          }
        }
      }
    });

    y = doc.lastAutoTable.finalY + 10;

    // Assessment dates
    if (initialAssessment) {
      doc.setFontSize(8);
      doc.setFont('helvetica', 'italic');
      doc.setTextColor(...GRAY);
      const dateText = `Početna procena: ${formatDate(initialAssessment.date)}` +
        (latestAssessment && latestAssessment !== initialAssessment
          ? ` · Poslednja procena: ${formatDate(latestAssessment.date)}`
          : '');
      doc.text(dateText, margin, y);
      y += 8;
    }
  }

  // ============================================================
  // GOALS SECTION
  // ============================================================

  if (goals.length > 0) {
    // Check if we need a new page
    if (y > pageHeight - 60) {
      doc.addPage();
      doc.setFillColor(15, 15, 15);
      doc.rect(0, 0, pageWidth, 15, 'F');
      doc.setFillColor(...GOLD);
      doc.rect(0, 0, 4, 15, 'F');
      y = 25;
    }

    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...GOLD);
    doc.text('NAPREDAK KA CILJEVIMA', margin, y);
    doc.setDrawColor(...GOLD);
    doc.line(margin, y + 2, margin + 70, y + 2);
    y += 10;

    const goalsData = goals.map(goal => {
      const statusMap = { active: 'Aktivan', completed: 'Završen', missed: 'Propušten' };
      return [
        goal.title || '—',
        goal.targetDate ? formatDate(goal.targetDate) : '—',
        statusMap[goal.status] || '—',
        goal.notes || ''
      ];
    });

    doc.autoTable({
      startY: y,
      head: [['Cilj', 'Rok', 'Status', 'Napomena']],
      body: goalsData,
      theme: 'grid',
      margin: { left: margin, right: margin },
      styles: {
        fillColor: [26, 26, 26],
        textColor: [200, 200, 200],
        fontSize: 8,
        cellPadding: 3,
        lineColor: [40, 40, 40],
        lineWidth: 0.3,
        overflow: 'linebreak'
      },
      headStyles: {
        fillColor: [30, 30, 30],
        textColor: GOLD,
        fontStyle: 'bold'
      },
      columnStyles: {
        0: { cellWidth: 60 },
        1: { cellWidth: 25 },
        2: { cellWidth: 22 },
        3: { cellWidth: 'auto' }
      },
      didParseCell: (data) => {
        if (data.section === 'body' && data.column.index === 2) {
          const val = data.cell.raw;
          if (val === 'Završen') data.cell.styles.textColor = SUCCESS_COLOR;
          else if (val === 'Propušten') data.cell.styles.textColor = ERROR_COLOR;
          else data.cell.styles.textColor = WARNING_COLOR;
        }
      }
    });

    y = doc.lastAutoTable.finalY + 10;
  }

  // ============================================================
  // TRAINER NOTES SECTION
  // ============================================================

  if (notes.length > 0) {
    if (y > pageHeight - 60) {
      doc.addPage();
      doc.setFillColor(15, 15, 15);
      doc.rect(0, 0, pageWidth, 15, 'F');
      doc.setFillColor(...GOLD);
      doc.rect(0, 0, 4, 15, 'F');
      y = 25;
    }

    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...GOLD);
    doc.text('NAPOMENE TRENERA', margin, y);
    doc.setDrawColor(...GOLD);
    doc.line(margin, y + 2, margin + 50, y + 2);
    y += 10;

    const notesData = notes.map(note => {
      const stars = (n) => '★'.repeat(n) + '☆'.repeat(5 - n);
      const avg = ((note.engagement + note.execution) / 2).toFixed(1);
      return [
        formatDate(note.date),
        stars(note.engagement),
        stars(note.execution),
        avg,
        note.note || ''
      ];
    });

    doc.autoTable({
      startY: y,
      head: [['Datum', 'Angažovanost', 'Izvođenje', 'Prosek', 'Napomena']],
      body: notesData,
      theme: 'grid',
      margin: { left: margin, right: margin },
      styles: {
        fillColor: [26, 26, 26],
        textColor: [200, 200, 200],
        fontSize: 8,
        cellPadding: 3,
        lineColor: [40, 40, 40],
        lineWidth: 0.3,
        overflow: 'linebreak'
      },
      headStyles: {
        fillColor: [30, 30, 30],
        textColor: GOLD,
        fontStyle: 'bold'
      },
      columnStyles: {
        0: { cellWidth: 22 },
        1: { cellWidth: 28, textColor: [200, 134, 10] },
        2: { cellWidth: 28, textColor: [200, 134, 10] },
        3: { cellWidth: 18 },
        4: { cellWidth: 'auto' }
      },
      didParseCell: (data) => {
        if (data.section === 'body' && data.column.index === 3) {
          const val = parseFloat(data.cell.raw);
          if (val >= 4) data.cell.styles.textColor = SUCCESS_COLOR;
          else if (val >= 3) data.cell.styles.textColor = WARNING_COLOR;
          else data.cell.styles.textColor = ERROR_COLOR;
        }
      }
    });

    y = doc.lastAutoTable.finalY + 10;
  }

  // ============================================================
  // FOOTER on all pages
  // ============================================================

  const pageCount = doc.internal.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    const fY = pageHeight - 12;

    doc.setFillColor(20, 20, 20);
    doc.rect(0, fY - 5, pageWidth, 17, 'F');

    doc.setFontSize(8);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(...GRAY);
    doc.text('JEVRAGKlab · Individual Training App', margin, fY + 2);
    doc.text(
      `Generisano: ${formatDate(today)} · Strana ${i}/${pageCount}`,
      pageWidth - margin,
      fY + 2,
      { align: 'right' }
    );
  }

  // ============================================================
  // DOWNLOAD
  // ============================================================

  const safeName = fullName.replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_ćčđšž]/gi, '') || 'Igrac';
  const dateStr = today.toISOString().split('T')[0];
  doc.save(`IzvestajIgraca_${safeName}_${dateStr}.pdf`);
}
