import React, { useState } from 'react';
import { usePlayers } from '../../../hooks/usePlayers';
import { getMonthName, formatDate } from '../../../utils/helpers';

const STATUSES = ['unpaid', 'paid', 'pending'];
const STATUS_LABELS = { paid: 'Plaćeno', unpaid: 'Nije plaćeno', pending: 'Na čekanju' };
const STATUS_COLORS = {
  paid: { bg: 'rgba(34,197,94,0.12)', color: '#22c55e', border: 'rgba(34,197,94,0.25)' },
  unpaid: { bg: 'rgba(239,68,68,0.12)', color: '#ef4444', border: 'rgba(239,68,68,0.25)' },
  pending: { bg: 'rgba(245,158,11,0.12)', color: '#f59e0b', border: 'rgba(245,158,11,0.25)' }
};

export default function Payment({ player }) {
  const [year, setYear] = useState(new Date().getFullYear());
  const { updatePayment } = usePlayers();

  const payments = player.payments || {};
  const yearPayments = payments[year] || {};
  const monthlyPrice = parseFloat(player.monthlyPrice) || 0;

  const getPayment = (monthIdx) => yearPayments[monthIdx] || { status: 'unpaid' };

  const cycleStatus = async (monthIdx) => {
    const current = getPayment(monthIdx);
    const currentStatus = current.status || 'unpaid';
    const nextIdx = (STATUSES.indexOf(currentStatus) + 1) % STATUSES.length;
    const nextStatus = STATUSES[nextIdx];

    const newData = {
      status: nextStatus,
      amount: monthlyPrice,
      date: nextStatus === 'paid' ? new Date().toISOString() : current.date || null
    };

    try {
      await updatePayment(player.id, year, monthIdx, newData);
    } catch (err) {
      console.error('Error updating payment:', err);
    }
  };

  // Calculate stats
  let totalPaid = 0;
  let totalDebt = 0;
  let paidCount = 0;
  let unpaidCount = 0;

  for (let i = 0; i < 12; i++) {
    const p = getPayment(i);
    if (p.status === 'paid') {
      totalPaid += monthlyPrice;
      paidCount++;
    } else if (p.status === 'unpaid') {
      totalDebt += monthlyPrice;
      unpaidCount++;
    }
  }

  const months = Array.from({ length: 12 }, (_, i) => i);

  return (
    <div>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
        <h3>Plaćanje</h3>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <button
            className="btn btn-secondary btn-sm btn-icon"
            onClick={() => setYear(y => y - 1)}
          >
            ‹
          </button>
          <span style={{ fontWeight: 700, fontSize: '1.1rem', minWidth: 60, textAlign: 'center' }}>
            {year}
          </span>
          <button
            className="btn btn-secondary btn-sm btn-icon"
            onClick={() => setYear(y => y + 1)}
          >
            ›
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="stats-row" style={{ marginBottom: 24 }}>
        <div className="stat-item">
          <div className="stat-label">Ukupno plaćeno</div>
          <div className="stat-value success">{totalPaid.toLocaleString()} RSD</div>
        </div>
        <div className="stat-item">
          <div className="stat-label">Dugovanje</div>
          <div className="stat-value error">{totalDebt.toLocaleString()} RSD</div>
        </div>
        <div className="stat-item">
          <div className="stat-label">Plaćenih meseci</div>
          <div className="stat-value">{paidCount}/12</div>
        </div>
        {monthlyPrice > 0 && (
          <div className="stat-item">
            <div className="stat-label">Mesečna cena</div>
            <div className="stat-value gold">{monthlyPrice.toLocaleString()} RSD</div>
          </div>
        )}
      </div>

      {monthlyPrice === 0 && (
        <div style={{
          background: 'rgba(245,158,11,0.1)',
          border: '1px solid rgba(245,158,11,0.3)',
          borderRadius: 8,
          padding: '12px 16px',
          marginBottom: 20,
          fontSize: '0.85rem',
          color: '#f59e0b'
        }}>
          ⚠️ Mesečna cena nije postavljena. Idite na tab "Podaci" da je postavite.
        </div>
      )}

      {/* Month grid */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))',
        gap: 12
      }}>
        {months.map(i => {
          const payment = getPayment(i);
          const status = payment.status || 'unpaid';
          const cfg = STATUS_COLORS[status];
          const isCurrentMonth = i === new Date().getMonth() && year === new Date().getFullYear();

          return (
            <div
              key={i}
              onClick={() => cycleStatus(i)}
              style={{
                background: cfg.bg,
                border: `1px solid ${isCurrentMonth ? 'var(--gold)' : cfg.border}`,
                borderRadius: 'var(--radius)',
                padding: '16px',
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                position: 'relative',
                overflow: 'hidden'
              }}
              onMouseEnter={e => {
                e.currentTarget.style.transform = 'translateY(-1px)';
                e.currentTarget.style.boxShadow = `0 6px 20px ${cfg.color}20`;
              }}
              onMouseLeave={e => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = 'none';
              }}
            >
              {isCurrentMonth && (
                <div style={{
                  position: 'absolute',
                  top: 8,
                  right: 8,
                  fontSize: '0.65rem',
                  fontWeight: 700,
                  color: 'var(--gold)',
                  background: 'rgba(37,99,235,0.15)',
                  border: '1px solid rgba(37,99,235,0.3)',
                  borderRadius: 3,
                  padding: '1px 5px'
                }}>
                  AKTUELNI
                </div>
              )}

              <div style={{ fontSize: '0.85rem', fontWeight: 700, marginBottom: 6, color: 'var(--text-primary)' }}>
                {getMonthName(i)}
              </div>

              <div style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 4,
                padding: '3px 10px',
                borderRadius: 20,
                fontSize: '0.75rem',
                fontWeight: 600,
                background: cfg.bg,
                color: cfg.color,
                border: `1px solid ${cfg.border}`,
                marginBottom: 6
              }}>
                <span style={{ fontSize: '0.6rem' }}>●</span>
                {STATUS_LABELS[status]}
              </div>

              {status === 'paid' && payment.date && (
                <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginTop: 4 }}>
                  Plaćeno: {formatDate(payment.date)}
                </div>
              )}

              {monthlyPrice > 0 && (
                <div style={{ fontSize: '0.8rem', fontWeight: 600, color: 'var(--text-secondary)', marginTop: 4 }}>
                  {monthlyPrice.toLocaleString()} RSD
                </div>
              )}

              <div style={{ fontSize: '0.68rem', color: 'var(--text-muted)', marginTop: 4 }}>
                Klikni za promenu statusa
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
