import React, { useState } from 'react';
import { usePlayers } from '../../../hooks/usePlayers';
import { useTrainings } from '../../../hooks/useTrainings';
import {
  getMonthName,
  getMonthAttendanceStats,
  getAllMonths,
  toDateKey,
  getDaysInMonth,
  getFirstDayOfWeek,
  DAYS_SHORT
} from '../../../utils/helpers';

export default function Attendance({ player }) {
  const now = new Date();
  const [year, setYear] = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth()); // null = cela godina
  const [viewMode, setViewMode] = useState('month'); // 'month' | 'year'
  const { updateAttendance } = usePlayers();
  const { trainings } = useTrainings();

  const attendances = player.attendances || {};
  const MONTHS = getAllMonths();

  // Year range: prethodna, tekuća, sledeća
  const years = [now.getFullYear() - 1, now.getFullYear(), now.getFullYear() + 1];

  // ── Month view helpers ───────────────────────────────────────────────────────

  const stats = getMonthAttendanceStats(attendances, year, month);
  const days = getDaysInMonth(year, month);
  const firstDayOfWeek = getFirstDayOfWeek(year, month);

  const hasTraining = (day) => {
    const dateKey = toDateKey(day);
    return trainings.some(t => t.date === dateKey && (t.playerIds || []).includes(player.id));
  };

  const getAttendanceStatus = (dateKey) => {
    const record = attendances[dateKey];
    if (!record) return null;
    return record.present;
  };

  const handleDayClick = async (day) => {
    const dateKey = toDateKey(day);
    const currentRecord = attendances[dateKey];
    const currentStatus = currentRecord?.present;

    let newPresent;
    if (currentStatus === undefined || currentStatus === null) {
      newPresent = true;
    } else if (currentStatus === true) {
      newPresent = false;
    } else {
      try { await updateAttendance(player.id, dateKey, null); } catch (e) {}
      return;
    }
    try { await updateAttendance(player.id, dateKey, newPresent); } catch (e) {}
  };

  const isToday = (day) => {
    const t = new Date();
    return day.getDate() === t.getDate() &&
      day.getMonth() === t.getMonth() &&
      day.getFullYear() === t.getFullYear();
  };

  // ── Year view helpers ────────────────────────────────────────────────────────

  const getYearStats = () => {
    return MONTHS.map((name, i) => {
      const s = getMonthAttendanceStats(attendances, year, i);
      return { name, index: i, ...s };
    });
  };

  // ── Render ───────────────────────────────────────────────────────────────────

  return (
    <div>
      {/* Header */}
      <div style={{ marginBottom: 20 }}>
        <h3 style={{ marginBottom: 14 }}>Evidencija dolazaka</h3>

        {/* Year pills */}
        <div style={{ display: 'flex', gap: 6, marginBottom: 10 }}>
          {years.map(y => (
            <button
              key={y}
              onClick={() => setYear(y)}
              style={{
                padding: '5px 14px', borderRadius: 20, border: '1px solid',
                borderColor: year === y ? 'var(--gold)' : 'var(--border)',
                background: year === y ? 'rgba(37,99,235,0.15)' : 'transparent',
                color: year === y ? 'var(--gold)' : 'var(--text-muted)',
                fontSize: '0.82rem', fontWeight: 700, cursor: 'pointer',
                transition: 'all 0.15s'
              }}
            >
              {y}
            </button>
          ))}
        </div>

        {/* Month pills + Cela godina */}
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
          {MONTHS.map((name, i) => (
            <button
              key={i}
              onClick={() => { setMonth(i); setViewMode('month'); }}
              style={{
                padding: '4px 10px', borderRadius: 20, border: '1px solid',
                borderColor: viewMode === 'month' && month === i ? 'var(--gold)' : 'var(--border)',
                background: viewMode === 'month' && month === i ? 'rgba(37,99,235,0.15)' : 'transparent',
                color: viewMode === 'month' && month === i ? 'var(--gold)' : 'var(--text-secondary)',
                fontSize: '0.78rem', fontWeight: 600, cursor: 'pointer',
                transition: 'all 0.15s'
              }}
            >
              {name.slice(0, 3)}
            </button>
          ))}
          <button
            onClick={() => setViewMode('year')}
            style={{
              padding: '4px 12px', borderRadius: 20, border: '1px solid',
              borderColor: viewMode === 'year' ? 'var(--gold)' : 'var(--border)',
              background: viewMode === 'year' ? 'rgba(37,99,235,0.15)' : 'transparent',
              color: viewMode === 'year' ? 'var(--gold)' : 'var(--text-secondary)',
              fontSize: '0.78rem', fontWeight: 700, cursor: 'pointer',
              transition: 'all 0.15s'
            }}
          >
            Cela godina
          </button>
        </div>
      </div>

      {/* ── MONTH VIEW ── */}
      {viewMode === 'month' && (
        <>
          {/* Stats */}
          <div className="stats-row" style={{ marginBottom: 20 }}>
            <div className="stat-item">
              <div className="stat-label">Ukupno</div>
              <div className="stat-value">{stats.total}</div>
            </div>
            <div className="stat-item">
              <div className="stat-label">Dolazaka</div>
              <div className="stat-value success">{stats.present}</div>
            </div>
            <div className="stat-item">
              <div className="stat-label">Propuštenih</div>
              <div className="stat-value error">{stats.absent}</div>
            </div>
            <div className="stat-item">
              <div className="stat-label">Procenat</div>
              <div className="stat-value gold">{stats.percentage}%</div>
            </div>
          </div>

          {/* Calendar */}
          <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', overflow: 'hidden' }}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', borderBottom: '1px solid var(--border)' }}>
              {DAYS_SHORT.map(d => (
                <div key={d} style={{ padding: '10px 4px', textAlign: 'center', fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase' }}>
                  {d}
                </div>
              ))}
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', padding: 8, gap: 4 }}>
              {Array.from({ length: firstDayOfWeek }).map((_, i) => <div key={`e-${i}`} />)}
              {days.map(day => {
                const dateKey = toDateKey(day);
                const training = hasTraining(day);
                const status = getAttendanceStatus(dateKey);
                const today = isToday(day);

                let cellBg = 'transparent';
                let cellBorder = 'transparent';
                let dayColor = 'var(--text-secondary)';
                let dotContent = null;

                if (status === true) {
                  cellBg = 'rgba(34,197,94,0.15)'; cellBorder = 'rgba(34,197,94,0.4)';
                  dayColor = '#22c55e'; dotContent = '✓';
                } else if (status === false) {
                  cellBg = 'rgba(239,68,68,0.12)'; cellBorder = 'rgba(239,68,68,0.3)';
                  dayColor = '#ef4444'; dotContent = '✗';
                } else if (training) {
                  cellBg = 'rgba(37,99,235,0.08)'; cellBorder = 'rgba(37,99,235,0.2)';
                  dayColor = 'var(--gold)';
                }
                if (today) cellBorder = 'var(--gold)';

                return (
                  <div
                    key={dateKey}
                    onClick={() => handleDayClick(day)}
                    style={{
                      aspectRatio: '1', display: 'flex', flexDirection: 'column',
                      alignItems: 'center', justifyContent: 'center',
                      borderRadius: 8, cursor: 'pointer',
                      background: cellBg, border: `1px solid ${cellBorder}`,
                      transition: 'all 0.15s', gap: 2
                    }}
                    onMouseEnter={e => { if (!status && !training) e.currentTarget.style.background = 'rgba(255,255,255,0.05)'; }}
                    onMouseLeave={e => { if (!status && !training) e.currentTarget.style.background = 'transparent'; }}
                  >
                    <span style={{ fontSize: '0.8rem', fontWeight: today ? 800 : 500, color: today ? 'var(--gold)' : dayColor }}>
                      {day.getDate()}
                    </span>
                    {dotContent && <span style={{ fontSize: '0.65rem', fontWeight: 700, color: dayColor }}>{dotContent}</span>}
                    {!dotContent && training && <span style={{ fontSize: '0.55rem', color: 'var(--gold)' }}>●</span>}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Legend */}
          <div style={{ display: 'flex', gap: 16, marginTop: 14, flexWrap: 'wrap' }}>
            {[
              { color: '#22c55e', bg: 'rgba(34,197,94,0.12)', label: 'Prisutan (✓)' },
              { color: '#ef4444', bg: 'rgba(239,68,68,0.12)', label: 'Odsutan (✗)' },
              { color: 'var(--gold)', bg: 'rgba(37,99,235,0.08)', label: 'Trening (bez evid.)' }
            ].map(item => (
              <div key={item.label} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <div style={{ width: 14, height: 14, borderRadius: 3, background: item.bg, border: `1px solid ${item.color}30` }} />
                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>{item.label}</span>
              </div>
            ))}
          </div>
          <p style={{ fontSize: '0.78rem', color: 'var(--text-muted)', marginTop: 12 }}>
            Klikni na dan da označiš prisutnost → odsutnost → ukloni
          </p>
        </>
      )}

      {/* ── YEAR VIEW ── */}
      {viewMode === 'year' && (
        <>
          {/* Ukupno za godinu */}
          {(() => {
            const prefix = `${year}-`;
            const allAtt = Object.entries(attendances).filter(([k]) => k.startsWith(prefix));
            const totalPresent = allAtt.filter(([, v]) => v.present).length;
            const totalAbsent = allAtt.filter(([, v]) => !v.present).length;
            const total = allAtt.length;
            const pct = total > 0 ? Math.round(totalPresent / total * 100) : 0;
            return (
              <div className="stats-row" style={{ marginBottom: 20 }}>
                <div className="stat-item">
                  <div className="stat-label">Ukupno {year}.</div>
                  <div className="stat-value">{total}</div>
                </div>
                <div className="stat-item">
                  <div className="stat-label">Dolazaka</div>
                  <div className="stat-value success">{totalPresent}</div>
                </div>
                <div className="stat-item">
                  <div className="stat-label">Propuštenih</div>
                  <div className="stat-value error">{totalAbsent}</div>
                </div>
                <div className="stat-item">
                  <div className="stat-label">Procenat</div>
                  <div className="stat-value gold">{pct}%</div>
                </div>
              </div>
            );
          })()}

          {/* 12 meseci grid */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(120px, 1fr))', gap: 10 }}>
            {getYearStats().map(m => {
              const pct = m.percentage;
              const color = m.total === 0 ? 'var(--text-muted)'
                : pct >= 80 ? '#22c55e'
                : pct >= 60 ? '#f59e0b'
                : '#ef4444';
              return (
                <div
                  key={m.index}
                  onClick={() => { setMonth(m.index); setViewMode('month'); }}
                  style={{
                    background: 'var(--bg-card)', border: '1px solid var(--border)',
                    borderRadius: 'var(--radius)', padding: '14px 12px',
                    cursor: 'pointer', transition: 'all 0.15s', textAlign: 'center'
                  }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(37,99,235,0.4)'; e.currentTarget.style.background = 'rgba(37,99,235,0.05)'; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--border)'; e.currentTarget.style.background = 'var(--bg-card)'; }}
                >
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', fontWeight: 600, marginBottom: 8 }}>
                    {m.name}
                  </div>
                  <div style={{ fontSize: '1.4rem', fontWeight: 800, color, marginBottom: 4 }}>
                    {m.total > 0 ? `${pct}%` : '—'}
                  </div>
                  {m.total > 0 && (
                    <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>
                      {m.present}/{m.total}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 12 }}>
            Klikni na mesec da vidiš detalje.
          </p>
        </>
      )}
    </div>
  );
}
