import React from 'react';

export default function Badge({ status, onClick, size = 'sm' }) {
  const configs = {
    paid: {
      label: 'Plaćeno',
      bg: 'rgba(34, 197, 94, 0.12)',
      color: '#22c55e',
      border: 'rgba(34, 197, 94, 0.25)'
    },
    unpaid: {
      label: 'Nije plaćeno',
      bg: 'rgba(239, 68, 68, 0.12)',
      color: '#ef4444',
      border: 'rgba(239, 68, 68, 0.25)'
    },
    pending: {
      label: 'Na čekanju',
      bg: 'rgba(245, 158, 11, 0.12)',
      color: '#f59e0b',
      border: 'rgba(245, 158, 11, 0.25)'
    }
  };

  const config = configs[status] || configs.unpaid;
  const fontSize = size === 'xs' ? '0.7rem' : size === 'sm' ? '0.75rem' : '0.85rem';
  const padding = size === 'xs' ? '2px 7px' : size === 'sm' ? '3px 10px' : '5px 12px';

  return (
    <span
      onClick={onClick}
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 4,
        padding,
        borderRadius: 20,
        fontSize,
        fontWeight: 600,
        background: config.bg,
        color: config.color,
        border: `1px solid ${config.border}`,
        cursor: onClick ? 'pointer' : 'default',
        transition: 'all 0.2s ease',
        userSelect: 'none',
        whiteSpace: 'nowrap'
      }}
    >
      <span style={{ fontSize: '0.6rem' }}>●</span>
      {config.label}
    </span>
  );
}

export function MembershipBadge({ player, onToggle }) {
  const status = player?.membershipStatus || 'unpaid';

  const cycleStatus = () => {
    if (!onToggle) return;
    const next = status === 'paid' ? 'unpaid' : 'paid';
    onToggle(next);
  };

  return <Badge status={status} onClick={onToggle ? cycleStatus : undefined} />;
}

export function PositionBadge({ position }) {
  return (
    <span style={{
      display: 'inline-flex',
      alignItems: 'center',
      padding: '2px 8px',
      borderRadius: 4,
      fontSize: '0.72rem',
      fontWeight: 700,
      background: 'rgba(200, 134, 10, 0.12)',
      color: '#3b82f6',
      border: '1px solid rgba(200, 134, 10, 0.25)',
      letterSpacing: '0.05em'
    }}>
      {position || '—'}
    </span>
  );
}
