import { format, parseISO } from 'date-fns';

/**
 * Get initials from a full name
 */
export function getInitials(name) {
  if (!name) return '?';
  const parts = name.trim().split(/\s+/);
  if (parts.length === 1) return parts[0][0].toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

/**
 * Format date to dd.MM.yyyy
 */
export function formatDate(date) {
  if (!date) return '';
  try {
    if (typeof date === 'string') {
      // Handle ISO strings and simple date strings
      const d = new Date(date);
      if (isNaN(d.getTime())) return date;
      return format(d, 'dd.MM.yyyy');
    }
    if (date instanceof Date) {
      return format(date, 'dd.MM.yyyy');
    }
    return String(date);
  } catch {
    return String(date);
  }
}

/**
 * Format date to dd.MM.yyyy HH:mm
 */
export function formatDateTime(date) {
  if (!date) return '';
  try {
    const d = typeof date === 'string' ? new Date(date) : date;
    return format(d, 'dd.MM.yyyy HH:mm');
  } catch {
    return String(date);
  }
}

/**
 * Get current age from birth year
 */
export function getAge(birthYear) {
  if (!birthYear) return null;
  const currentYear = new Date().getFullYear();
  return currentYear - parseInt(birthYear, 10);
}

/**
 * Get age category from birth year
 */
export function getCategory(birthYear) {
  if (!birthYear) return 'Nepoznato';
  const age = getAge(birthYear);
  if (age <= 10) return 'U10';
  if (age <= 12) return 'U12';
  if (age <= 14) return 'U14';
  if (age <= 15) return 'U15';
  if (age <= 16) return 'U16';
  if (age <= 17) return 'U17';
  if (age <= 19) return 'U19';
  return 'Senior';
}

