/**
 * Calculate attendance stats from attendances object
 */
export function calculateAttendanceStats(attendances) {
  if (!attendances) return { total: 0, present: 0, absent: 0, percentage: 0 };

  const entries = Object.values(attendances);
  const total = entries.length;
  const present = entries.filter(e => e.present === true).length;
  const absent = total - present;
  const percentage = total > 0 ? Math.round((present / total) * 100) : 0;

  return { total, present, absent, percentage };
}

/**
 * Get attendance stats for a specific month
 */
export function getMonthAttendanceStats(attendances, year, month) {
  if (!attendances) return { total: 0, present: 0, absent: 0, percentage: 0 };

  const prefix = `${year}-${String(month + 1).padStart(2, '0')}`;
  const monthEntries = Object.entries(attendances)
    .filter(([key]) => key.startsWith(prefix))
    .map(([, val]) => val);

  const total = monthEntries.length;
  const present = monthEntries.filter(e => e.present === true).length;
  const absent = total - present;
  const percentage = total > 0 ? Math.round((present / total) * 100) : 0;

  return { total, present, absent, percentage };
}

/**
 * Format date key for Firebase (yyyy-MM-dd)
 */
export function toDateKey(date) {
  const d = date instanceof Date ? date : new Date(date);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

/**
 * Get color for score value 1-10
 */
export function getScoreColor(score) {
  if (!score) return 'var(--text-muted)';
  if (score < 4) return 'var(--error)';
  if (score < 7) return 'var(--warning)';
  return 'var(--success)';
}

/**
 * Get average of an array of numbers
 */
export function average(arr) {
  if (!arr || arr.length === 0) return 0;
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

/**
 * Calculate payment stats for a player
 */
export function calculatePaymentStats(payments, monthlyPrice, year) {
  if (!payments || !payments[year]) {
    return { totalPaid: 0, debt: 0, paidMonths: 0, unpaidMonths: 0 };
  }

  const yearPayments = payments[year];
  let paidMonths = 0;
  let unpaidMonths = 0;

  Object.values(yearPayments).forEach(p => {
    if (p.status === 'paid') paidMonths++;
    else if (p.status === 'unpaid') unpaidMonths++;
  });

  const price = parseFloat(monthlyPrice) || 0;
  const totalPaid = paidMonths * price;
  const debt = unpaidMonths * price;

  return { totalPaid, debt, paidMonths, unpaidMonths };
}

/**
 * Get pillar label in Serbian
 */
export function getPillarLabel(pillar) {
  const labels = {
    technical: 'Tehnički',
    tactical: 'Taktički',
    physical: 'Fizički',
    psychological: 'Psihološki'
  };
  return labels[pillar] || pillar;
}

/**
 * Get latest assessment scores for a player
 */
export function getLatestAssessment(assessments, type) {
  if (!assessments) return null;
  const list = Object.values(assessments)
    .filter(a => !type || a.type === type)
    .sort((a, b) => new Date(b.date) - new Date(a.date));
  return list[0] || null;
}

/**
 * Get first/initial assessment for a player
 */
export function getInitialAssessment(assessments, type) {
  if (!assessments) return null;
  const list = Object.values(assessments)
    .filter(a => !type || a.type === type)
    .sort((a, b) => new Date(a.date) - new Date(b.date));
  return list[0] || null;
}

/**
 * Generate unique ID (client-side)
 */
export function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
}

