import { useState, useEffect } from 'react';
import { ref, onValue, set } from 'firebase/database';
import { db } from '../firebase';

export function usePlayerRatings(trainingId, playerId) {
  const [myRating, setMyRating] = useState(null);
  const [allRatings, setAllRatings] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!trainingId) return;
    const r = ref(db, `playerRatings/${trainingId}`);
    return onValue(r, (snap) => {
      const data = snap.val() || {};
      setAllRatings(data);
      setMyRating(playerId ? (data[playerId] || null) : null);
      setLoading(false);
    });
  }, [trainingId, playerId]);

  const submitRating = async (ratingData) => {
    if (!trainingId || !playerId) return;
    const r = ref(db, `playerRatings/${trainingId}/${playerId}`);
    await set(r, { ...ratingData, createdAt: new Date().toISOString() });
  };

  return { myRating, allRatings, loading, submitRating };
}
