import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useTrainings } from '../../hooks/useTrainings';
import { usePlayers } from '../../hooks/usePlayers';
import { usePlayerRatings } from '../../hooks/usePlayerRatings';
import Avatar from '../../components/common/Avatar';
import { formatDate } from '../../utils/helpers';

const STEPS = ['Dolazak', 'Ocene', 'Završi'];
const CRITERIA = ['Tehnika', 'Brzina', 'Taktika', 'Iskoraci', 'Koncentracija'];

export default function TrainingSessionPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { trainings, loading: tLoad, completeTraining } = useTrainings();
  const { players, loading: pLoad, updateAttendance } = usePlayers();

  const [step, setStep] = useState(0);
  const [attendance, setAttendance] = useState({});
  const [ratings, setRatings] = useState({});
  const [note, setNote] = useState('');
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState('');
  const [editing, setEditing] = useState(false);

  const training = trainings.find(t => t.id === id);
  const criteria = CRITERIA;
  const { allRatings: playerRatings } = usePlayerRatings(id, null);

  const sortedTrainings = [...trainings].sort((a, b) => {
    const da = a.date + (a.time || '');
    const db2 = b.date + (b.time || '');
    return db2.localeCompare(da);
  });
  const currentIndex = sortedTrainings.findIndex(t => t.id === id);
  const prevTraining = sortedTrainings[currentIndex + 1] || null;
  const nextTraining = sortedTrainings[currentIndex - 1] || null;
  const trainingPlayers = players.filter(p => (training?.playerIds || []).includes(p.id));

  // Init: svi igrači su prisutni po defaultu
  useEffect(() => {
    if (!training) return;
    if (training.completed) {
      setAttendance(training.attendance || {});
      setRatings(training.ratings || {});
      setNote(training.trainingNote || '');
      return;
    }
    const init = {};
    (training.playerIds || []).forEach(pid => { init[pid] = true; });
    setAttendance(init);

    // Init ocene: 6.5 za svaki kriterij
    const initRatings = {};
    (training.playerIds || []).forEach(pid => {
      initRatings[pid] = {};
      criteria.forEach(c => { initRatings[pid][c] = 6.5; });
    });
    setRatings(initRatings);
  }, [training?.id, criteria.join(',')]); // eslint-disable-line

  if (tLoad || pLoad) return <div className="loading-container"><div className="loading-spinner" /></div>;

  if (!training) {
    return (
      <div className="empty-state">
        <div className="empty-state-icon">❌</div>
        <div className="empty-state-title">Trening nije pronađen</div>
        <button className="btn btn-secondary" onClick={() => navigate('/treninzi')} style={{ marginTop: 16 }}>← Treninzi</button>
      </div>
    );
  }

  const presentPlayers = trainingPlayers.filter(p => attendance[p.id] === true);

  const toggleAttendance = (pid) => {
    if (training.completed) return;
    setAttendance(prev => ({ ...prev, [pid]: !prev[pid] }));
  };

  const setRating = (pid, criterion, value) => {
    const num = Math.min(10, Math.max(1, parseFloat(value) || 6.5));
    setRatings(prev => ({
      ...prev,
      [pid]: { ...(prev[pid] || {}), [criterion]: num }
    }));
  };

  const handleFinish = async () => {
    setSaving(true);
    setSaveError('');
    try {
      // Čuvaj samo prisutne igrače u ocenama
      const finalRatings = {};
      presentPlayers.forEach(p => {
        finalRatings[p.id] = ratings[p.id] || {};
        criteria.forEach(c => {
          if (finalRatings[p.id][c] === undefined) finalRatings[p.id][c] = 6.5;
        });
      });

      await completeTraining(id, {
        attendance,
        ratings: finalRatings,
        trainingNote: note
      });

      // Ažuriraj dolazak za svakog igrača
      await Promise.all(
        trainingPlayers.map(p =>
          updateAttendance(p.id, training.date, attendance[p.id] === true)
            .catch(() => {})
        )
      );

      setEditing(false);
      setStep(0);
      navigate('/treninzi');
    } catch (err) {
      console.error(err);
      setSaveError('Greška: ' + (err?.message || 'Pokušaj ponovo'));
    } finally {
      setSaving(false);
    }
  };

  const isCompleted = !!training.completed && !editing;

  return (
    <div style={{ maxWidth: 680, margin: '0 auto' }}>
      {/* Header */}
      <div style={{ marginBottom: 24 }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
          <button className="btn btn-secondary btn-sm" onClick={() => navigate('/treninzi')}>
            ← Treninzi
          </button>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <button
              className="btn btn-secondary"
              onClick={() => prevTraining && navigate(`/trening/${prevTraining.id}`)}
              disabled={!prevTraining}
              style={{ fontSize: '1.8rem', height: 40, padding: '0 12px', opacity: prevTraining ? 1 : 0.3 }}
            >‹</button>
            <span style={{ fontSize: '0.82rem', color: 'var(--text-muted)', minWidth: 60, textAlign: 'center' }}>
              {currentIndex + 1} / {sortedTrainings.length}
            </span>
            <button
              className="btn btn-secondary"
              onClick={() => nextTraining && navigate(`/trening/${nextTraining.id}`)}
              disabled={!nextTraining}
              style={{ fontSize: '1.8rem', height: 40, padding: '0 12px', opacity: nextTraining ? 1 : 0.3 }}
            >›</button>
          </div>
        </div>
        <div style={{
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius)',
          padding: '16px 20px',
          display: 'flex',
          gap: 20,
          alignItems: 'center',
          flexWrap: 'wrap'
        }}>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 700, fontSize: '1.1rem', marginBottom: 4 }}>{training.name}</div>
            <div style={{ fontSize: '0.82rem', color: 'var(--text-muted)', display: 'flex', gap: 14, flexWrap: 'wrap' }}>
              <span>📅 {formatDate(training.date)}</span>
              {training.time && <span>🕐 {training.time}</span>}
              <span>⏱ {training.duration || 60} min</span>
              <span>👥 {trainingPlayers.length} igrača</span>
            </div>
          </div>
          {training.completed && !editing && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <div style={{
                background: 'rgba(34,197,94,0.12)', border: '1px solid rgba(34,197,94,0.3)',
                borderRadius: 20, padding: '4px 14px', fontSize: '0.8rem', fontWeight: 700, color: '#22c55e'
              }}>
                ✓ Završen
              </div>
              <button
                className="btn btn-secondary btn-sm"
                onClick={() => { setEditing(true); setStep(0); }}
              >
                ✏️ Uredi
              </button>
            </div>
          )}
          {editing && (
            <button
              className="btn btn-secondary btn-sm"
              onClick={() => { setEditing(false); setStep(0); }}
              style={{ color: 'var(--error)', borderColor: 'var(--error)' }}
            >
              ✕ Otkaži
            </button>
          )}
        </div>
      </div>

      {/* Steps */}
      {!isCompleted && (
        <div style={{ display: 'flex', gap: 0, marginBottom: 28, background: 'var(--bg-card)', borderRadius: 'var(--radius)', border: '1px solid var(--border)', overflow: 'hidden' }}>
          {STEPS.map((s, i) => (
            <div
              key={s}
              onClick={() => i < step && setStep(i)}
              style={{
                flex: 1,
                padding: '12px 8px',
                textAlign: 'center',
                fontSize: '0.82rem',
                fontWeight: 600,
                cursor: i < step ? 'pointer' : 'default',
                background: i === step ? 'rgba(37,99,235,0.12)' : 'transparent',
                color: i === step ? 'var(--gold)' : i < step ? 'var(--text-secondary)' : 'var(--text-muted)',
                borderBottom: i === step ? '2px solid var(--gold)' : '2px solid transparent',
                transition: 'all 0.2s'
              }}
            >
              {i < step ? '✓ ' : `${i + 1}. `}{s}
            </div>
          ))}
        </div>
      )}

      {/* STEP 0: Dolazak */}
      {(step === 0 || isCompleted) && (
        <div style={{ marginBottom: isCompleted ? 32 : 0 }}>
          {isCompleted && <h3 style={{ marginBottom: 16 }}>Dolazak</h3>}
          <div style={{
            background: 'var(--bg-card)', border: '1px solid var(--border)',
            borderRadius: 'var(--radius)', overflow: 'hidden', marginBottom: 4
          }}>
            {trainingPlayers.length === 0 && (
              <div style={{ padding: 24, textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.88rem' }}>
                Nema igrača dodeljenih ovom treningu.
              </div>
            )}
            {trainingPlayers.map((p, i) => {
              const present = attendance[p.id] === true;
              const fullName = `${p.firstName || ''} ${p.lastName || ''}`.trim();
              return (
                <div
                  key={p.id}
                  onClick={() => toggleAttendance(p.id)}
                  style={{
                    display: 'flex', alignItems: 'center', gap: 14,
                    padding: '12px 18px',
                    borderBottom: i < trainingPlayers.length - 1 ? '1px solid var(--border)' : 'none',
                    cursor: isCompleted ? 'default' : 'pointer',
                    background: present ? 'rgba(34,197,94,0.04)' : 'transparent',
                    transition: 'background 0.15s'
                  }}
                >
                  <div style={{
                    width: 26, height: 26, borderRadius: 6, flexShrink: 0,
                    border: `2px solid ${present ? '#22c55e' : 'var(--border)'}`,
                    background: present ? 'rgba(34,197,94,0.15)' : 'transparent',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    fontSize: '0.85rem', fontWeight: 900, color: '#22c55e',
                    transition: 'all 0.15s'
                  }}>
                    {present ? '✓' : ''}
                  </div>
                  <Avatar src={p.photoBase64} name={fullName} size="sm" />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 600, fontSize: '0.9rem' }}>{fullName}</div>
                    <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>{p.position || ''} · {p.birthYear || ''}</div>
                  </div>
                  <div style={{ fontSize: '0.8rem', fontWeight: 600, color: present ? '#22c55e' : '#ef4444' }}>
                    {present ? 'Prisutan' : 'Odsutan'}
                  </div>
                </div>
              );
            })}
          </div>

          <div style={{ fontSize: '0.82rem', color: 'var(--text-muted)', marginBottom: 20, padding: '0 4px' }}>
            Prisutno: <strong style={{ color: 'var(--text-primary)' }}>{presentPlayers.length}</strong> / {trainingPlayers.length}
          </div>

          {!isCompleted && (
            <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
              <button className="btn btn-primary" onClick={() => setStep(1)}>
                Nastavi → Ocene
              </button>
            </div>
          )}
        </div>
      )}

      {/* STEP 1: Ocene */}
      {(step === 1 || isCompleted) && (
        <div style={{ marginBottom: isCompleted ? 32 : 0 }}>
          {isCompleted && <h3 style={{ marginBottom: 16 }}>Ocene</h3>}

          {presentPlayers.length === 0 ? (
            <div style={{
              background: 'var(--bg-card)', border: '1px solid var(--border)',
              borderRadius: 'var(--radius)', padding: 24, textAlign: 'center',
              color: 'var(--text-muted)', fontSize: '0.88rem', marginBottom: 20
            }}>
              Nema prisutnih igrača za ocenjivanje.
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12, marginBottom: 20 }}>
              {presentPlayers.map(p => {
                const fullName = `${p.firstName || ''} ${p.lastName || ''}`.trim();
                const pRatings = ratings[p.id] || {};
                return (
                  <div key={p.id} style={{
                    background: 'var(--bg-card)', border: '1px solid var(--border)',
                    borderRadius: 'var(--radius)', padding: '16px 20px'
                  }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14 }}>
                      <Avatar src={p.photoBase64} name={fullName} size="sm" />
                      <div style={{ fontWeight: 700 }}>{fullName}</div>
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 12 }}>
                      {criteria.map(criterion => {
                        const val = pRatings[criterion] !== undefined ? pRatings[criterion] : 6.5;
                        return (
                          <div key={criterion}>
                            <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', fontWeight: 600, marginBottom: 6 }}>
                              {criterion}
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                              {!isCompleted && (
                                <button
                                  onClick={() => setRating(p.id, criterion, val - 0.5)}
                                  style={{ background: 'var(--bg-primary)', border: '1px solid var(--border)', borderRadius: 4, width: 28, height: 28, cursor: 'pointer', color: 'var(--text-secondary)', fontSize: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                                >−</button>
                              )}
                              <div style={{
                                flex: 1, textAlign: 'center', fontFamily: 'monospace',
                                fontSize: '1.1rem', fontWeight: 700,
                                color: val >= 8 ? '#22c55e' : val >= 6 ? 'var(--gold)' : '#ef4444'
                              }}>
                                {val.toFixed(1)}
                              </div>
                              {!isCompleted && (
                                <button
                                  onClick={() => setRating(p.id, criterion, val + 0.5)}
                                  style={{ background: 'var(--bg-primary)', border: '1px solid var(--border)', borderRadius: 4, width: 28, height: 28, cursor: 'pointer', color: 'var(--text-secondary)', fontSize: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                                >+</button>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {!isCompleted && (
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <button className="btn btn-secondary" onClick={() => setStep(0)}>← Dolazak</button>
              <button className="btn btn-primary" onClick={() => setStep(2)}>Nastavi → Završi</button>
            </div>
          )}
        </div>
      )}

      {/* STEP 2: Završi */}
      {(step === 2 || isCompleted) && (
        <div>
          {isCompleted && <h3 style={{ marginBottom: 16 }}>Napomena</h3>}

          <div style={{ marginBottom: 20 }}>
            <label style={{ fontSize: '0.82rem', color: 'var(--text-muted)', fontWeight: 600, display: 'block', marginBottom: 8 }}>
              Opšta napomena o treningu (opciono)
            </label>
            <textarea
              className="input"
              rows={4}
              placeholder="Kako je prošao trening, šta je bilo dobro, šta treba popraviti..."
              value={note}
              onChange={e => setNote(e.target.value)}
              disabled={isCompleted}
              style={{ resize: 'vertical' }}
            />
          </div>

          {!isCompleted && (
            <>
              <div style={{
                background: 'var(--bg-card)', border: '1px solid var(--border)',
                borderRadius: 'var(--radius)', padding: '14px 18px', marginBottom: 20,
                display: 'flex', gap: 24, flexWrap: 'wrap'
              }}>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: '1.4rem', fontWeight: 700, color: '#22c55e' }}>{presentPlayers.length}</div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Prisutno</div>
                </div>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: '1.4rem', fontWeight: 700, color: '#ef4444' }}>{trainingPlayers.length - presentPlayers.length}</div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Odsutno</div>
                </div>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: '1.4rem', fontWeight: 700, color: 'var(--gold)' }}>{criteria.length}</div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Kriterijuma</div>
                </div>
              </div>

              {saveError && (
                <div style={{ color: 'var(--error)', fontSize: '0.82rem', marginBottom: 12 }}>{saveError}</div>
              )}

              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <button className="btn btn-secondary" onClick={() => setStep(1)}>← Ocene</button>
                <button
                  className="btn btn-primary"
                  onClick={handleFinish}
                  disabled={saving}
                  style={{ background: 'linear-gradient(135deg, #166534, #22c55e)', minWidth: 160 }}
                >
                  {saving ? 'Čuvam...' : '✓ Završi trening'}
                </button>
              </div>
            </>
          )}

          {isCompleted && training.trainingNote && (
            <div style={{
              background: 'var(--bg-primary)', border: '1px solid var(--border)',
              borderRadius: 'var(--radius)', padding: '14px 18px',
              fontSize: '0.88rem', color: 'var(--text-secondary)', fontStyle: 'italic'
            }}>
              "{training.trainingNote}"
            </div>
          )}

          {isCompleted && (training.images?.length || training.imageBase64) && (
            <div style={{ marginTop: 20 }}>
              <h3 style={{ marginBottom: 12, fontSize: '0.95rem' }}>Vežbe</h3>
              <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
                {(training.images || (training.imageBase64 ? [training.imageBase64] : [])).map((img, i) => (
                  <div key={i} style={{ flex: '1 1 200px', position: 'relative' }}>
                    <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginBottom: 4, fontWeight: 700 }}>Vežba {i + 1}</div>
                    <img src={img} alt={`Vežba ${i + 1}`}
                      style={{ width: '100%', maxHeight: 260, objectFit: 'cover', borderRadius: 'var(--radius)', border: '1px solid var(--border)' }} />
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Player self-ratings */}
          {isCompleted && (() => {
            const ratingEntries = Object.entries(playerRatings);
            if (!ratingEntries.length) return null;
            const PLAYER_CRITERIA = ['Intenzitet', 'Zanimljivost', 'Tehnicko', 'Takticko', 'Brzina'];
            const LABELS = { Intenzitet: 'Intenzitet', Zanimljivost: 'Zanimljivost', Tehnicko: 'Tehničko', Takticko: 'Taktičko', Brzina: 'Brzina' };
            const avgs = {};
            PLAYER_CRITERIA.forEach(k => {
              const vals = ratingEntries.map(([, r]) => r[k]).filter(v => v != null);
              avgs[k] = vals.length ? (vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(1) : '—';
            });
            return (
              <div style={{ marginTop: 24 }}>
                <h3 style={{ marginBottom: 12, fontSize: '0.95rem' }}>
                  ⭐ Ocene igrača ({ratingEntries.length} {ratingEntries.length === 1 ? 'igrač' : 'igrača'})
                </h3>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 16 }}>
                  {PLAYER_CRITERIA.map(k => (
                    <div key={k} style={{
                      background: 'var(--bg-card)',
                      border: '1px solid var(--border)',
                      borderRadius: 'var(--radius-sm)',
                      padding: '8px 14px',
                      textAlign: 'center',
                      minWidth: 80
                    }}>
                      <div style={{ fontSize: '0.65rem', color: 'var(--text-muted)', marginBottom: 4 }}>{LABELS[k]}</div>
                      <div style={{ fontWeight: 700, fontSize: '1.1rem', color: 'var(--gold)' }}>{avgs[k]}</div>
                    </div>
                  ))}
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                  {ratingEntries.map(([pid, r]) => {
                    const pl = trainingPlayers.find(p => p.id === pid);
                    const name = pl ? `${pl.firstName || ''} ${pl.lastName || ''}`.trim() : 'Igrač';
                    return (
                      <div key={pid} style={{
                        background: 'var(--bg-card)',
                        border: '1px solid var(--border)',
                        borderRadius: 'var(--radius-sm)',
                        padding: '8px 14px',
                        display: 'flex',
                        gap: 12,
                        alignItems: 'center',
                        flexWrap: 'wrap'
                      }}>
                        <span style={{ fontSize: '0.85rem', fontWeight: 600, minWidth: 120 }}>{name}</span>
                        {PLAYER_CRITERIA.map(k => (
                          <span key={k} style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>
                            {LABELS[k]}: <strong style={{ color: 'var(--text-primary)' }}>{r[k] ?? '—'}</strong>
                          </span>
                        ))}
                        {r.comment && (
                          <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)', fontStyle: 'italic', width: '100%' }}>
                            "{r.comment}"
                          </span>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })()}
        </div>
      )}
    </div>
  );
}
