import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTrainings } from '../../hooks/useTrainings';
import { usePlayers } from '../../hooks/usePlayers';
import TrainingModal from '../Schedule/TrainingModal';
import {
  getMonthName, getDaysInMonth, getFirstDayOfWeek,
  toDateKey, formatDate, DAYS_SHORT
} from '../../utils/helpers';

function generateSlots(startH, endH) {
  const slots = [];
  for (let h = startH; h < endH; h++) {
    slots.push(`${String(h).padStart(2, '0')}:00`);
    slots.push(`${String(h).padStart(2, '0')}:30`);
  }
  slots.push(`${String(endH).padStart(2, '0')}:00`);
  return slots;
}

function loadWorkHours() {
  try {
    const saved = JSON.parse(localStorage.getItem('workHours'));
    if (saved && saved.start >= 0 && saved.end <= 23 && saved.start < saved.end) return saved;
  } catch(e) {}
  return { start: 8, end: 20 };
}

export default function TrainingsListPage() {
  const { trainings, loading, addTraining, deleteTraining } = useTrainings();
  const { updateAttendance } = usePlayers();
  const navigate = useNavigate();

  const now = new Date();
  const [year, setYear] = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth());
  const [modalOpen, setModalOpen] = useState(false);
  const [modalDate, setModalDate] = useState(null);
  const [modalTime, setModalTime] = useState('10:00');
  const [selectedDay, setSelectedDay] = useState(toDateKey(now));

  const [workHours, setWorkHours] = useState(loadWorkHours);
  const [editingHours, setEditingHours] = useState(false);
  const [hoursInput, setHoursInput] = useState(loadWorkHours);

  const TIME_SLOTS = generateSlots(workHours.start, workHours.end);

  if (loading) return <div className="loading-container"><div className="loading-spinner" /></div>;

  const days = getDaysInMonth(year, month);
  const firstDayOfWeek = getFirstDayOfWeek(year, month);
  const today = toDateKey(now);

  const saveWorkHours = () => {
    const s = parseInt(hoursInput.start);
    const e = parseInt(hoursInput.end);
    if (isNaN(s) || isNaN(e) || s >= e || s < 0 || e > 23) return;
    const wh = { start: s, end: e };
    setWorkHours(wh);
    localStorage.setItem('workHours', JSON.stringify(wh));
    setEditingHours(false);
  };

  const prevMonth = () => {
    if (month === 0) { setMonth(11); setYear(y => y - 1); }
    else setMonth(m => m - 1);
  };
  const nextMonth = () => {
    if (month === 11) { setMonth(0); setYear(y => y + 1); }
    else setMonth(m => m + 1);
  };

  const getTrainingsForDay = (dateKey) =>
    trainings
      .filter(t => t.date === dateKey)
      .sort((a, b) => (a.time || '').localeCompare(b.time || ''));

  const handleSaveTraining = async (data) => {
    const id = await addTraining(data);
    await Promise.all(
      (data.playerIds || []).map(pid =>
        updateAttendance(pid, data.date, null).catch(() => {})
      )
    );
    return id;
  };

  const handleTimeSlotClick = (slot) => {
    setModalDate(selectedDay ? new Date(selectedDay + 'T12:00:00') : now);
    setModalTime(slot);
    setModalOpen(true);
  };

  const handleDeleteTraining = async (trainingId, e) => {
    e.stopPropagation();
    if (window.confirm('Obrisati ovaj trening?')) {
      await deleteTraining(trainingId);
    }
  };

  const prefix = `${year}-${String(month + 1).padStart(2, '0')}`;
  const monthCount = trainings.filter(t => t.date && t.date.startsWith(prefix)).length;
  const monthPending = trainings.filter(t => t.date && t.date.startsWith(prefix) && !t.completed).length;

  const selectedDayTrainings = selectedDay ? getTrainingsForDay(selectedDay) : [];

  return (
    <div>
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Planer</h1>
          <p className="page-subtitle">
            {monthCount} u {getMonthName(month)} {year}
            {monthPending > 0 && (
              <span style={{ color: '#f59e0b', marginLeft: 8 }}>· {monthPending} čeka završetak</span>
            )}
          </p>
        </div>
        <button className="btn btn-secondary btn-sm" onClick={() => {
          setYear(now.getFullYear());
          setMonth(now.getMonth());
          setSelectedDay(today);
        }}>
          Danas
        </button>
      </div>

      {/* Month navigation */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16 }}>
        <button className="btn btn-secondary btn-sm btn-icon" onClick={prevMonth}>‹</button>
        <h2 style={{ margin: 0, fontSize: '1.2rem', minWidth: 180, textAlign: 'center' }}>
          {getMonthName(month)} {year}
        </h2>
        <button className="btn btn-secondary btn-sm btn-icon" onClick={nextMonth}>›</button>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 280px', gap: 20 }}>

        {/* Kalendar */}
        <div style={{
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius-lg)',
          overflow: 'hidden'
        }}>
          {/* Nazivi dana */}
          <div style={{
            display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)',
            borderBottom: '1px solid var(--border)',
            background: 'var(--bg-primary)'
          }}>
            {DAYS_SHORT.map(d => (
              <div key={d} style={{
                padding: '10px 4px', textAlign: 'center',
                fontSize: '0.72rem', fontWeight: 700,
                color: 'var(--text-muted)', textTransform: 'uppercase'
              }}>{d}</div>
            ))}
          </div>

          {/* Dani */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 1, background: 'var(--border)' }}>
            {Array.from({ length: firstDayOfWeek }).map((_, i) => (
              <div key={`e-${i}`} style={{ background: 'var(--bg-card)', minHeight: 80 }} />
            ))}

            {days.map(day => {
              const dateKey = toDateKey(day);
              const dayTrainings = getTrainingsForDay(dateKey);
              const isToday = dateKey === today;
              const isSelected = dateKey === selectedDay;

              return (
                <div
                  key={dateKey}
                  onClick={() => setSelectedDay(dateKey)}
                  style={{
                    background: isSelected
                      ? 'rgba(37,99,235,0.14)'
                      : isToday
                      ? 'rgba(37,99,235,0.05)'
                      : 'var(--bg-card)',
                    minHeight: 80,
                    padding: '6px',
                    cursor: 'pointer',
                    transition: 'background 0.12s',
                    borderTop: isToday ? '2px solid var(--gold)' : isSelected ? '2px solid var(--gold)' : '2px solid transparent',
                  }}
                  onMouseEnter={e => { if (!isSelected) e.currentTarget.style.background = 'rgba(255,255,255,0.04)'; }}
                  onMouseLeave={e => {
                    if (!isSelected) e.currentTarget.style.background = isToday ? 'rgba(37,99,235,0.05)' : 'var(--bg-card)';
                  }}
                >
                  <div style={{
                    fontSize: '0.82rem',
                    fontWeight: isToday || isSelected ? 800 : 500,
                    color: isToday || isSelected ? 'var(--gold)' : 'var(--text-secondary)',
                    marginBottom: 3
                  }}>
                    {day.getDate()}
                  </div>

                  {/* Training pills */}
                  {dayTrainings.slice(0, 2).map(t => (
                    <div key={t.id} style={{
                      background: t.completed ? 'rgba(34,197,94,0.15)' : 'rgba(245,158,11,0.15)',
                      border: `1px solid ${t.completed ? 'rgba(34,197,94,0.35)' : 'rgba(245,158,11,0.35)'}`,
                      borderRadius: 3,
                      padding: '1px 4px',
                      fontSize: '0.58rem',
                      color: t.completed ? '#22c55e' : '#f59e0b',
                      fontWeight: 600,
                      marginBottom: 2,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap'
                    }}>
                      {t.time} {t.name}
                    </div>
                  ))}
                  {dayTrainings.length > 2 && (
                    <div style={{ fontSize: '0.56rem', color: 'var(--text-muted)' }}>
                      +{dayTrainings.length - 2}
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          {/* Legenda */}
          <div style={{
            display: 'flex', gap: 16, padding: '10px 16px',
            borderTop: '1px solid var(--border)',
            fontSize: '0.75rem', color: 'var(--text-muted)'
          }}>
            <span style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
              <span style={{ width: 10, height: 10, borderRadius: 2, background: 'rgba(34,197,94,0.5)', display: 'inline-block' }} />
              Završen
            </span>
            <span style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
              <span style={{ width: 10, height: 10, borderRadius: 2, background: 'rgba(245,158,11,0.5)', display: 'inline-block' }} />
              Nije završen
            </span>
          </div>
        </div>

        {/* Time slots panel */}
        <div style={{
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius-lg)',
          overflow: 'hidden',
          display: 'flex',
          flexDirection: 'column',
          maxHeight: 620
        }}>
          {/* Panel header */}
          <div style={{ padding: '14px 16px', borderBottom: '1px solid var(--border)' }}>
            <div style={{
              fontWeight: 700,
              fontSize: '0.9rem',
              color: selectedDay === today ? 'var(--gold)' : 'var(--text-primary)',
              marginBottom: 10
            }}>
              {selectedDay
                ? formatDate(selectedDay) + (selectedDay === today ? ' — Danas' : '')
                : 'Izaberi dan'}
              {selectedDay && selectedDayTrainings.length > 0 && (
                <span style={{ fontWeight: 400, fontSize: '0.75rem', color: 'var(--text-muted)', marginLeft: 8 }}>
                  {selectedDayTrainings.length} treninga
                </span>
              )}
            </div>

            {/* Work hours picker */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              {editingHours ? (
                <>
                  <input
                    type="number" min="0" max="22"
                    value={hoursInput.start}
                    onChange={e => setHoursInput(p => ({ ...p, start: e.target.value }))}
                    style={{ width: 44, padding: '3px 6px', background: 'var(--bg-primary)', border: '1px solid var(--border)', borderRadius: 6, color: 'var(--text-primary)', fontSize: '0.78rem', textAlign: 'center' }}
                  />
                  <span style={{ color: 'var(--text-muted)', fontSize: '0.78rem' }}>–</span>
                  <input
                    type="number" min="1" max="23"
                    value={hoursInput.end}
                    onChange={e => setHoursInput(p => ({ ...p, end: e.target.value }))}
                    style={{ width: 44, padding: '3px 6px', background: 'var(--bg-primary)', border: '1px solid var(--border)', borderRadius: 6, color: 'var(--text-primary)', fontSize: '0.78rem', textAlign: 'center' }}
                  />
                  <button className="btn btn-primary btn-sm" onClick={saveWorkHours} style={{ fontSize: '0.72rem', padding: '3px 10px' }}>OK</button>
                  <button className="btn btn-secondary btn-sm" onClick={() => setEditingHours(false)} style={{ fontSize: '0.72rem', padding: '3px 8px' }}>✕</button>
                </>
              ) : (
                <button
                  className="btn btn-secondary btn-sm"
                  onClick={() => { setHoursInput(workHours); setEditingHours(true); }}
                  style={{ fontSize: '0.75rem', padding: '4px 10px' }}
                  title="Uredi radno vreme"
                >
                  🕐 {String(workHours.start).padStart(2,'0')}:00 – {String(workHours.end).padStart(2,'0')}:00
                </button>
              )}
            </div>
          </div>

          {/* Time slots */}
          <div style={{ overflowY: 'auto', flex: 1 }}>
            {TIME_SLOTS.map(slot => {
              const existing = selectedDayTrainings.find(t => t.time === slot);
              return (
                <div
                  key={slot}
                  onClick={() => existing ? navigate(`/trening/${existing.id}`) : handleTimeSlotClick(slot)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                    padding: '8px 16px',
                    borderBottom: '1px solid var(--border)',
                    cursor: 'pointer',
                    transition: 'background 0.12s',
                    background: existing
                      ? existing.completed
                        ? 'rgba(34,197,94,0.05)'
                        : 'rgba(245,158,11,0.05)'
                      : 'transparent'
                  }}
                  onMouseEnter={e => {
                    if (!existing) e.currentTarget.style.background = 'rgba(255,255,255,0.03)';
                  }}
                  onMouseLeave={e => {
                    e.currentTarget.style.background = existing
                      ? existing.completed ? 'rgba(34,197,94,0.05)' : 'rgba(245,158,11,0.05)'
                      : 'transparent';
                  }}
                >
                  <span style={{
                    fontSize: '0.72rem',
                    color: 'var(--text-muted)',
                    width: 38,
                    flexShrink: 0,
                    fontWeight: 600
                  }}>
                    {slot}
                  </span>
                  {existing ? (
                    <div style={{ flex: 1, overflow: 'hidden' }}>
                      <div style={{
                        fontSize: '0.8rem',
                        color: existing.completed ? '#22c55e' : '#f59e0b',
                        fontWeight: 600,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap'
                      }}>
                        {existing.name}
                      </div>
                      <div style={{ fontSize: '0.65rem', color: 'var(--text-muted)' }}>
                        {existing.duration} min · {(existing.playerIds || []).length} igrača
                        {existing.completed && ' · ✓'}
                      </div>
                    </div>
                  ) : (
                    <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                      + Dodaj trening
                    </span>
                  )}
                  {existing && (
                    <button
                      onClick={e => handleDeleteTraining(existing.id, e)}
                      style={{ background: 'none', border: 'none', cursor: 'pointer', padding: '2px 6px', color: 'var(--error)', fontSize: '0.75rem', lineHeight: 1, flexShrink: 0 }}
                      title="Obriši"
                    >✕</button>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <TrainingModal
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        onSave={handleSaveTraining}
        date={modalDate}
        time={modalTime}
        existing={null}
      />
    </div>
  );
}
