import React, { useState, useEffect } from 'react';
import { usePlayers } from '../../../hooks/usePlayers';
import { POSITIONS, FEET_OPTIONS } from '../../../utils/helpers';

export default function PlayerData({ player }) {
  const { updatePlayer } = usePlayers();
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({});

  useEffect(() => {
    setForm({
      firstName: player.firstName || '',
      lastName: player.lastName || '',
      position: player.position || 'ST',
      birthYear: player.birthYear || '',
      club: player.club || '',
      dominantFoot: player.dominantFoot || 'desna',
      height: player.height || '',
      weight: player.weight || '',
      parentContact: player.parentContact || '',
      monthlyPrice: player.monthlyPrice || '',
      playerWishes: player.playerWishes || '',
      trainerWishes: player.trainerWishes || '',
      photoBase64: player.photoBase64 || ''
    });
  }, [player]);

  const handleChange = (e) => {
    setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handlePhotoUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) {
      alert('Slika je prevelika. Maksimalna veličina je 2MB.');
      return;
    }
    const reader = new FileReader();
    reader.onload = (ev) => {
      setForm(prev => ({ ...prev, photoBase64: ev.target.result }));
    };
    reader.readAsDataURL(file);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await updatePlayer(player.id, {
        ...form,
        birthYear: parseInt(form.birthYear) || null,
        height: parseInt(form.height) || null,
        weight: parseInt(form.weight) || null,
        monthlyPrice: parseFloat(form.monthlyPrice) || 0
      });
      setEditing(false);
    } catch (err) {
      console.error('Error saving player data:', err);
    } finally {
      setSaving(false);
    }
  };

  const fieldStyle = {
    background: editing ? 'var(--bg-primary)' : 'transparent',
    border: editing ? '1px solid var(--border)' : '1px solid transparent',
    borderRadius: 'var(--radius-sm)',
    padding: editing ? '10px 14px' : '8px 0',
    color: 'var(--text-primary)',
    fontSize: '0.88rem',
    width: '100%',
    transition: 'all 0.2s ease'
  };

  const readField = (label, value) => (
    <div className="form-group">
      <label className="label">{label}</label>
      <div style={{
        padding: '8px 0',
        fontSize: '0.9rem',
        color: value ? 'var(--text-primary)' : 'var(--text-muted)',
        borderBottom: '1px solid var(--border)'
      }}>
        {value || '—'}
      </div>
    </div>
  );

  return (
    <div>
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: 24
      }}>
        <h3>Podaci igrača</h3>
        {!editing ? (
          <button className="btn btn-secondary btn-sm" onClick={() => setEditing(true)}>
            ✏ Uredi
          </button>
        ) : (
          <div style={{ display: 'flex', gap: 8 }}>
            <button className="btn btn-secondary btn-sm" onClick={() => setEditing(false)}>
              Otkaži
            </button>
            <button className="btn btn-primary btn-sm" onClick={handleSave} disabled={saving}>
              {saving ? 'Čuvam...' : '💾 Sačuvaj'}
            </button>
          </div>
        )}
      </div>

      {/* Photo upload */}
      <div style={{ marginBottom: 24, display: 'flex', gap: 20, alignItems: 'flex-start' }}>
        <div style={{
          width: 80,
          height: 80,
          borderRadius: '50%',
          overflow: 'hidden',
          background: form.photoBase64 ? 'transparent' : 'linear-gradient(135deg, #3b82f6, #1d4ed8)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          border: '2px solid rgba(37,99,235,0.3)',
          flexShrink: 0
        }}>
          {form.photoBase64 ? (
            <img src={form.photoBase64} alt="Player" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          ) : (
            <span style={{ fontSize: '1.5rem', fontWeight: 700, color: '#000' }}>
              {(form.firstName?.[0] || '') + (form.lastName?.[0] || '')}
            </span>
          )}
        </div>

        {editing && (
          <div>
            <label className="label">Slika igrača</label>
            <input
              type="file"
              accept="image/*"
              onChange={handlePhotoUpload}
              style={{
                fontSize: '0.82rem',
                color: 'var(--text-secondary)'
              }}
            />
            {form.photoBase64 && (
              <button
                className="btn btn-sm"
                onClick={() => setForm(prev => ({ ...prev, photoBase64: '' }))}
                style={{ marginTop: 8, color: 'var(--error)', border: '1px solid rgba(239,68,68,0.3)', background: 'var(--error-bg)' }}
              >
                Ukloni sliku
              </button>
            )}
            <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 4 }}>
              Maksimalna veličina: 2MB
            </p>
          </div>
        )}
      </div>

      {/* Fields */}
      {editing ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div className="form-row">
            <div className="form-group">
              <label className="label">Ime</label>
              <input name="firstName" className="input" value={form.firstName} onChange={handleChange} />
            </div>
            <div className="form-group">
              <label className="label">Prezime</label>
              <input name="lastName" className="input" value={form.lastName} onChange={handleChange} />
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="label">Pozicija</label>
              <select name="position" className="input" value={form.position} onChange={handleChange}>
                {POSITIONS.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <div className="form-group">
              <label className="label">Godište</label>
              <input name="birthYear" className="input" type="number" value={form.birthYear} onChange={handleChange} />
            </div>
          </div>

          <div className="form-group">
            <label className="label">Klub</label>
            <input name="club" className="input" value={form.club} onChange={handleChange} />
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="label">Dominantna noga</label>
              <select name="dominantFoot" className="input" value={form.dominantFoot} onChange={handleChange}>
                {FEET_OPTIONS.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
              </select>
            </div>
            <div className="form-group">
              <label className="label">Mesečna cena (RSD)</label>
              <input name="monthlyPrice" className="input" type="number" value={form.monthlyPrice} onChange={handleChange} />
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="label">Visina (cm)</label>
              <input name="height" className="input" type="number" value={form.height} onChange={handleChange} />
            </div>
            <div className="form-group">
              <label className="label">Težina (kg)</label>
              <input name="weight" className="input" type="number" value={form.weight} onChange={handleChange} />
            </div>
          </div>

          <div className="form-group">
            <label className="label">Kontakt roditelja</label>
            <input name="parentContact" className="input" value={form.parentContact} onChange={handleChange} />
          </div>

          <div className="form-group">
            <label className="label">Igračeve želje</label>
            <textarea
              name="playerWishes"
              className="input"
              rows={3}
              placeholder="Šta igrač želi da poboljša..."
              value={form.playerWishes}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label className="label">Naše želje za igrača</label>
            <textarea
              name="trainerWishes"
              className="input"
              rows={3}
              placeholder="Ciljevi i planovi trenera za igrača..."
              value={form.trainerWishes}
              onChange={handleChange}
            />
          </div>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 0 }}>
          <div style={{
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gap: '12px 24px',
            marginBottom: 20
          }}>
            {readField('Ime', form.firstName)}
            {readField('Prezime', form.lastName)}
            {readField('Pozicija', form.position)}
            {readField('Godište', form.birthYear)}
            {readField('Klub', form.club)}
            {readField('Dominantna noga', form.dominantFoot === 'desna' ? 'Desna' : form.dominantFoot === 'leva' ? 'Leva' : 'Obe')}
            {readField('Visina', form.height ? `${form.height} cm` : null)}
            {readField('Težina', form.weight ? `${form.weight} kg` : null)}
            {readField('Kontakt roditelja', form.parentContact)}
            {readField('Mesečna cena', form.monthlyPrice ? `${form.monthlyPrice} RSD` : null)}
          </div>

          {(form.playerWishes || form.trainerWishes) && (
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px 24px' }}>
              <div>
                <label className="label">Igračeve želje</label>
                <div style={{
                  padding: '12px',
                  background: 'var(--bg-primary)',
                  border: '1px solid var(--border)',
                  borderRadius: 'var(--radius-sm)',
                  fontSize: '0.88rem',
                  color: form.playerWishes ? 'var(--text-secondary)' : 'var(--text-muted)',
                  lineHeight: 1.6,
                  minHeight: 60
                }}>
                  {form.playerWishes || '—'}
                </div>
              </div>
              <div>
                <label className="label">Naše želje za igrača</label>
                <div style={{
                  padding: '12px',
                  background: 'var(--bg-primary)',
                  border: '1px solid var(--border)',
                  borderRadius: 'var(--radius-sm)',
                  fontSize: '0.88rem',
                  color: form.trainerWishes ? 'var(--text-secondary)' : 'var(--text-muted)',
                  lineHeight: 1.6,
                  minHeight: 60
                }}>
                  {form.trainerWishes || '—'}
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
