import { useState, useEffect } from 'react';
import { ref, onValue, push, set, update, remove } from 'firebase/database';
import { db } from '../firebase';
import { notifyPlayer } from '../utils/notifications';

export function usePlayerProcena(playerId) {
  const [procenas, setProcenas] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!playerId) return;
    const r = ref(db, `procena/${playerId}`);
    const unsub = onValue(r, (snap) => {
      const data = snap.val();
      if (data) {
        setProcenas(
          Object.entries(data)
            .map(([id, val]) => ({ id, ...val }))
            .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
        );
      } else {
        setProcenas([]);
      }
      setLoading(false);
    });
    return () => unsub();
  }, [playerId]);

  const addProcena = async (data) => {
    const r = ref(db, `procena/${playerId}`);
    const newRef = push(r);
    await set(newRef, { ...data, createdAt: new Date().toISOString() });
    notifyPlayer(playerId, {
      type: 'procena',
      title: 'Nova procena',
      message: 'Trener je dodao novu procenu',
      link: 'procena'
    });
    return newRef.key;
  };

  const updateProcena = async (id, data) => {
    await update(ref(db, `procena/${playerId}/${id}`), data);
  };

  const deleteProcena = async (id) => {
    await remove(ref(db, `procena/${playerId}/${id}`));
  };

  return { procenas, loading, addProcena, updateProcena, deleteProcena };
}

export function usePlayerAnalize(playerId) {
  const [analize, setAnalize] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!playerId) return;
    const r = ref(db, `analize/${playerId}`);
    const unsub = onValue(r, (snap) => {
      const data = snap.val();
      if (data) {
        setAnalize(
          Object.entries(data)
            .map(([id, val]) => ({ id, ...val }))
            .sort((a, b) => b.date.localeCompare(a.date))
        );
      } else {
        setAnalize([]);
      }
      setLoading(false);
    });
    return () => unsub();
  }, [playerId]);

  const addAnaliza = async (data) => {
    const r = ref(db, `analize/${playerId}`);
    const newRef = push(r);
    await set(newRef, { ...data, createdAt: new Date().toISOString() });
    notifyPlayer(playerId, {
      type: 'analiza',
      title: 'Nova analiza',
      message: data.title || 'Trener je dodao novu analizu',
      link: 'analiza'
    });
    return newRef.key;
  };

  const updateAnaliza = async (id, data) => {
    await update(ref(db, `analize/${playerId}/${id}`), data);
  };

  const deleteAnaliza = async (id) => {
    await remove(ref(db, `analize/${playerId}/${id}`));
  };

  return { analize, loading, addAnaliza, updateAnaliza, deleteAnaliza };
}
