import React, { useState, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { usePlayers } from '../../hooks/usePlayers';
import { useTrainings } from '../../hooks/useTrainings';
import PlayerCard from './PlayerCard';
import Avatar from '../../components/common/Avatar';
import Modal from '../../components/common/Modal';
import { FEET_OPTIONS, getCategory, getAge } from '../../utils/helpers';
import { parseExcelImport, exportPlayersToExcel } from '../../utils/excelUtils';

const CATEGORIES = ['U10', 'U11', 'U12', 'U13', 'U14', 'U15', 'U16', 'U17', 'U18', 'U19', 'Senior'];

const EXPORT_FILTERS = [
  { id: 'all', label: 'Svi igrači' },
  { id: 'category', label: 'Po godištu' },
  { id: 'paid', label: 'Plaćena članarina' },
  { id: 'unpaid', label: 'Nije plaćena' },
];

export default function PlayersPage() {
  const navigate = useNavigate();
  const { players, loading, addPlayer } = usePlayers();
  const { trainings } = useTrainings();
  const [search, setSearch] = useState('');
  const [view, setView] = useState('grid'); // 'grid' | 'list'
  const [sortBy, setSortBy] = useState('name');
  const [sortDir, setSortDir] = useState('asc');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    firstName: '', lastName: '', birthYear: '',
    club: '', dominantFoot: 'desna', height: '', weight: '',
    parentContact: '', monthlyPrice: ''
  });

  // Import state
  const importRef = useRef(null);
  const [importResult, setImportResult] = useState(null); // { added, skipped, errors }
  const [importing, setImporting] = useState(false);
  const [showImportResult, setShowImportResult] = useState(false);

  // Export state
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportFilter, setExportFilter] = useState('all');
  const [exportPosition, setExportPosition] = useState('ST');
  const [exportCategory, setExportCategory] = useState('U14');

  const filtered = useMemo(() => {
    return players.filter(p => {
      const name = `${p.firstName || ''} ${p.lastName || ''}`.toLowerCase();
      return !search ||
        name.includes(search.toLowerCase()) ||
        (p.club || '').toLowerCase().includes(search.toLowerCase()) ||
        String(p.birthYear || '').includes(search);
    });
  }, [players, search]);

  // ── Stats helpers ────────────────────────────────────────────────────────────

  const now = new Date();

  const getPlayerStats = (p) => {
    // Dolazak — posjednjih 30 dana
    const cutoff = new Date(now); cutoff.setDate(cutoff.getDate() - 30);
    const recentAtt = Object.entries(p.attendances || {}).filter(([k]) => new Date(k) >= cutoff);
    const attPct = recentAtt.length > 0
      ? Math.round(recentAtt.filter(([, v]) => v.present).length / recentAtt.length * 100)
      : null;

    // Dugovanje ove godine
    const yearPayments = (p.payments || {})[now.getFullYear()] || {};
    const unpaid = Object.values(yearPayments).filter(x => x.status === 'unpaid').length;
    const debt = unpaid * (parseFloat(p.monthlyPrice) || 0);

    // Prosek ocena sa treninga
    const ratedTrainings = trainings.filter(t => t.completed && t.ratings && t.ratings[p.id]);
    let avgRating = null;
    if (ratedTrainings.length > 0) {
      const allScores = ratedTrainings.flatMap(t => Object.values(t.ratings[p.id]));
      avgRating = allScores.reduce((s, v) => s + v, 0) / allScores.length;
    }

    // Napomene
    const notesCount = Object.keys(p.notes || {}).length;

    return { attPct, debt, avgRating, notesCount };
  };

  const handleSort = (col) => {
    if (sortBy === col) setSortDir(d => d === 'asc' ? 'desc' : 'asc');
    else { setSortBy(col); setSortDir('asc'); }
  };

  const sortedFiltered = [...filtered].sort((a, b) => {
    const statsA = getPlayerStats(a);
    const statsB = getPlayerStats(b);
    let valA, valB;

    if (sortBy === 'name') {
      valA = `${a.firstName} ${a.lastName}`.toLowerCase();
      valB = `${b.firstName} ${b.lastName}`.toLowerCase();
    } else if (sortBy === 'category') {
      valA = parseInt(a.birthYear) || 0;
      valB = parseInt(b.birthYear) || 0;
    } else if (sortBy === 'attendance') {
      valA = statsA.attPct ?? -1;
      valB = statsB.attPct ?? -1;
    } else if (sortBy === 'debt') {
      valA = statsA.debt;
      valB = statsB.debt;
    } else if (sortBy === 'rating') {
      valA = statsA.avgRating ?? -1;
      valB = statsB.avgRating ?? -1;
    } else {
      valA = 0; valB = 0;
    }

    if (valA < valB) return sortDir === 'asc' ? -1 : 1;
    if (valA > valB) return sortDir === 'asc' ? 1 : -1;
    return 0;
  });

  // ── Handlers ────────────────────────────────────────────────────────────────

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.firstName.trim() || !form.lastName.trim()) return;
    setSaving(true);
    try {
      await addPlayer({
        ...form,
        position: 'GK',
        birthYear: parseInt(form.birthYear) || null,
        height: parseInt(form.height) || null,
        weight: parseInt(form.weight) || null,
        monthlyPrice: parseFloat(form.monthlyPrice) || 0
      });
      setIsModalOpen(false);
      setForm({ firstName: '', lastName: '', birthYear: '', club: '',
        dominantFoot: 'desna', height: '', weight: '', parentContact: '', monthlyPrice: '' });
    } catch (err) {
      console.error('Error adding player:', err);
    } finally {
      setSaving(false);
    }
  };

  const handleChange = (e) => {
    setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  // ── Import ───────────────────────────────────────────────────────────────────

  const handleImportFile = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    e.target.value = '';
    setImporting(true);
    try {
      const result = await parseExcelImport(file, players);
      // Add all new players to Firebase
      for (const p of result.added) {
        await addPlayer(p);
      }
      setImportResult(result);
      setShowImportResult(true);
    } catch (err) {
      setImportResult({ added: [], skipped: [], errors: [err.message] });
      setShowImportResult(true);
    } finally {
      setImporting(false);
    }
  };

  // ── Export ───────────────────────────────────────────────────────────────────

  const handleExport = () => {
    let exportPlayers = [...players];
    let label = 'Svi';

    if (exportFilter === 'position') {
      exportPlayers = players.filter(p => p.position === exportPosition);
      label = exportPosition;
    } else if (exportFilter === 'category') {
      exportPlayers = players.filter(p => getCategory(p.birthYear) === exportCategory);
      label = exportCategory;
    } else if (exportFilter === 'paid') {
      exportPlayers = players.filter(p => p.membershipStatus === 'paid');
      label = 'Placeno';
    } else if (exportFilter === 'unpaid') {
      exportPlayers = players.filter(p => p.membershipStatus !== 'paid');
      label = 'NijePlaceno';
    }

    exportPlayersToExcel(exportPlayers, label);
    setShowExportModal(false);
  };

  // ── Render ───────────────────────────────────────────────────────────────────

  if (loading) {
    return <div className="loading-container"><div className="loading-spinner" /></div>;
  }

  return (
    <div>
      {/* Page header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Igrači</h1>
          <p className="page-subtitle">
            {players.length} {players.length === 1 ? 'igrač' : 'igrača'} ukupno
          </p>
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          {/* View toggle */}
          <div style={{ display: 'flex', background: 'var(--bg-primary)', border: '1px solid var(--border)', borderRadius: 6, overflow: 'hidden' }}>
            <button
              onClick={() => setView('grid')}
              style={{
                padding: '7px 12px', border: 'none', cursor: 'pointer', fontSize: '0.9rem',
                background: view === 'grid' ? 'var(--gold)' : 'transparent',
                color: view === 'grid' ? '#000' : 'var(--text-muted)',
                transition: 'all 0.15s'
              }}
              title="Grid prikaz"
            >⊞</button>
            <button
              onClick={() => setView('list')}
              style={{
                padding: '7px 12px', border: 'none', cursor: 'pointer', fontSize: '0.9rem',
                background: view === 'list' ? 'var(--gold)' : 'transparent',
                color: view === 'list' ? '#000' : 'var(--text-muted)',
                transition: 'all 0.15s'
              }}
              title="Lista prikaz"
            >☰</button>
          </div>
          <button
            className="btn btn-secondary"
            onClick={() => importRef.current?.click()}
            disabled={importing}
            title="Importuj igrače iz Excel fajla"
          >
            {importing ? '⏳ Uvozim...' : '📥 Import Excel'}
          </button>
          <button
            className="btn btn-secondary"
            onClick={() => setShowExportModal(true)}
            disabled={players.length === 0}
            title="Exportuj igrače u Excel"
          >
            📤 Export Excel
          </button>
          <input
            ref={importRef}
            type="file"
            accept=".xlsx,.xls"
            style={{ display: 'none' }}
            onChange={handleImportFile}
          />
        </div>
      </div>

      {/* Search and filters */}
      <div style={{ marginBottom: 24 }}>
        <input
          type="text"
          className="input"
          placeholder="🔍  Pretraži po imenu, klubu ili godištu..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={{ maxWidth: 420 }}
        />
      </div>

      {/* Players */}
      {filtered.length === 0 ? (
        <div className="empty-state">
          <div className="empty-state-icon">👥</div>
          <div className="empty-state-title">
            {players.length === 0 ? 'Nema dodanih igrača' : 'Nema rezultata'}
          </div>
          <p className="empty-state-text">
            {players.length === 0
              ? 'Klikni na "+" dugme dole desno da dodaš prvog igrača, ili importuj Excel.'
              : 'Pokušaj sa drugačijim pojmom za pretragu.'}
          </p>
        </div>
      ) : view === 'grid' ? (
        <div className="stagger-children" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))', gap: 16 }}>
          {[...filtered].sort((a, b) => (parseInt(a.birthYear) || 9999) - (parseInt(b.birthYear) || 9999)).map(player => (
            <PlayerCard key={player.id} player={player} />
          ))}
        </div>
      ) : (
        /* List view */
        <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', overflow: 'hidden' }}>
          {/* Header */}
          {(() => {
            const SortIcon = ({ col }) => sortBy === col
              ? <span style={{ marginLeft: 3, fontSize: '0.65rem' }}>{sortDir === 'asc' ? '↑' : '↓'}</span>
              : null;
            const Th = ({ col, children }) => (
              <span
                onClick={() => handleSort(col)}
                style={{ cursor: 'pointer', userSelect: 'none', display: 'flex', alignItems: 'center',
                  color: sortBy === col ? 'var(--gold)' : 'var(--text-muted)' }}
              >
                {children}<SortIcon col={col} />
              </span>
            );
            return (
              <div style={{
                display: 'grid',
                gridTemplateColumns: '2fr 80px 90px 100px 80px 60px 32px',
                gap: 8, padding: '10px 16px',
                background: 'var(--bg-primary)', borderBottom: '1px solid var(--border)',
                fontSize: '0.7rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em'
              }}>
                <Th col="name">Igrač</Th>
                <Th col="category">Godište</Th>
                <Th col="attendance">Dolazak</Th>
                <Th col="debt">Dugovanje</Th>
                <Th col="rating">Ocene</Th>
                <span style={{ color: 'var(--text-muted)' }}>Napomene</span>
                <span />
              </div>
            );
          })()}
          {/* Rows */}
          {sortedFiltered.map((player, i) => {
            const fullName = `${player.firstName || ''} ${player.lastName || ''}`.trim();
            const { attPct, debt, avgRating, notesCount } = getPlayerStats(player);
            return (
              <div
                key={player.id}
                onClick={() => navigate(`/igrac/${player.id}`)}
                style={{
                  display: 'grid',
                  gridTemplateColumns: '2fr 80px 90px 100px 80px 60px 32px',
                  gap: 8,
                  padding: '12px 16px',
                  borderBottom: i < sortedFiltered.length - 1 ? '1px solid var(--border)' : 'none',
                  cursor: 'pointer',
                  alignItems: 'center',
                  transition: 'background 0.12s'
                }}
                onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.03)'}
                onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
              >
                {/* Ime */}
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <Avatar src={player.photoBase64} name={fullName} size="sm" />
                  <div>
                    <div style={{ fontWeight: 600, fontSize: '0.9rem' }}>{fullName}</div>
                    {player.club && <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)' }}>{player.club}</div>}
                  </div>
                </div>
                {/* Godište */}
                <div style={{ fontSize: '0.82rem', fontWeight: 700, color: 'var(--text-secondary)' }}>
                  {player.birthYear || '—'}
                </div>
                {/* Dolazak */}
                <div style={{
                  fontSize: '0.88rem', fontWeight: 700,
                  color: attPct === null ? 'var(--text-muted)'
                    : attPct >= 80 ? '#22c55e'
                    : attPct >= 60 ? '#f59e0b'
                    : '#ef4444'
                }}>
                  {attPct !== null ? `${attPct}%` : '—'}
                </div>
                {/* Dugovanje */}
                <div style={{
                  fontSize: '0.85rem', fontWeight: debt > 0 ? 700 : 400,
                  color: debt > 0 ? '#ef4444' : 'var(--text-muted)'
                }}>
                  {debt > 0 ? `${debt.toLocaleString()} RSD` : '—'}
                </div>
                {/* Ocene */}
                <div style={{
                  fontSize: '0.88rem', fontWeight: avgRating ? 700 : 400,
                  color: avgRating === null ? 'var(--text-muted)'
                    : avgRating >= 7.5 ? '#22c55e'
                    : avgRating >= 6 ? 'var(--gold)'
                    : '#ef4444'
                }}>
                  {avgRating !== null ? avgRating.toFixed(1) : '—'}
                </div>
                {/* Napomene */}
                <div style={{ fontSize: '0.82rem', color: notesCount > 0 ? 'var(--text-secondary)' : 'var(--text-muted)' }}>
                  {notesCount > 0 ? `${notesCount}` : '—'}
                </div>
                <span style={{ color: 'var(--text-muted)' }}>›</span>
              </div>
            );
          })}
        </div>
      )}

      {/* FAB */}
      <button className="fab fab-wide" onClick={() => setIsModalOpen(true)} title="Dodaj igrača">
        <span style={{ fontSize: '1.2rem' }}>+</span>
        <span>Dodaj Igrača</span>
      </button>

      {/* ── Add Player Modal ── */}
      <Modal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        title="Dodaj novog igrača"
        width={560}
        footer={
          <>
            <button className="btn btn-secondary" onClick={() => setIsModalOpen(false)}>Otkaži</button>
            <button className="btn btn-primary" onClick={handleSubmit}
              disabled={saving || !form.firstName.trim() || !form.lastName.trim()}>
              {saving ? 'Čuvam...' : 'Dodaj igrača'}
            </button>
          </>
        }
      >
        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div className="form-row">
            <div className="form-group">
              <label className="label">Ime *</label>
              <input name="firstName" className="input" placeholder="npr. Marko" value={form.firstName} onChange={handleChange} required />
            </div>
            <div className="form-group">
              <label className="label">Prezime *</label>
              <input name="lastName" className="input" placeholder="npr. Petrović" value={form.lastName} onChange={handleChange} required />
            </div>
          </div>
          <div className="form-group">
            <label className="label">Godište</label>
            <input name="birthYear" className="input" type="number" placeholder="npr. 2010" min="1990" max="2020" value={form.birthYear} onChange={handleChange} />
          </div>
          <div className="form-group">
            <label className="label">Klub</label>
            <input name="club" className="input" placeholder="Naziv kluba" value={form.club} onChange={handleChange} />
          </div>
          <div className="form-row">
            <div className="form-group">
              <label className="label">Dominantna noga</label>
              <select name="dominantFoot" className="input" value={form.dominantFoot} onChange={handleChange}>
                {FEET_OPTIONS.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
              </select>
            </div>
            <div className="form-group">
              <label className="label">Mesečna cena (RSD)</label>
              <input name="monthlyPrice" className="input" type="number" placeholder="npr. 5000" value={form.monthlyPrice} onChange={handleChange} />
            </div>
          </div>
          <div className="form-row">
            <div className="form-group">
              <label className="label">Visina (cm)</label>
              <input name="height" className="input" type="number" placeholder="npr. 175" value={form.height} onChange={handleChange} />
            </div>
            <div className="form-group">
              <label className="label">Težina (kg)</label>
              <input name="weight" className="input" type="number" placeholder="npr. 65" value={form.weight} onChange={handleChange} />
            </div>
          </div>
          <div className="form-group">
            <label className="label">Kontakt roditelja</label>
            <input name="parentContact" className="input" placeholder="Telefon ili email" value={form.parentContact} onChange={handleChange} />
          </div>
        </form>
      </Modal>

      {/* ── Export Modal ── */}
      <Modal
        isOpen={showExportModal}
        onClose={() => setShowExportModal(false)}
        title="Export igrača"
        width={400}
        footer={
          <>
            <button className="btn btn-secondary" onClick={() => setShowExportModal(false)}>Otkaži</button>
            <button className="btn btn-primary" onClick={handleExport}>📤 Preuzmi Excel</button>
          </>
        }
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div style={{ color: 'var(--text-secondary)', fontSize: '0.88rem' }}>
            Odaberi filter za export:
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {EXPORT_FILTERS.map(f => (
              <label key={f.id} style={{ display: 'flex', alignItems: 'center', gap: 10, cursor: 'pointer', padding: '8px 12px', borderRadius: 8, border: '1px solid', borderColor: exportFilter === f.id ? 'var(--gold)' : 'var(--border)', background: exportFilter === f.id ? 'rgba(37,99,235,0.08)' : 'transparent' }}>
                <input type="radio" name="exportFilter" value={f.id} checked={exportFilter === f.id} onChange={() => setExportFilter(f.id)} style={{ accentColor: 'var(--gold)' }} />
                <span style={{ fontSize: '0.9rem', color: exportFilter === f.id ? 'var(--gold)' : 'var(--text-primary)' }}>{f.label}</span>
              </label>
            ))}
          </div>

          {exportFilter === 'category' && (
            <div className="form-group">
              <label className="label">Kategorija</label>
              <select className="input" value={exportCategory} onChange={e => setExportCategory(e.target.value)}>
                {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
          )}

          <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', padding: '8px 12px', background: 'var(--card)', borderRadius: 8 }}>
            {exportFilter === 'all' && `${players.length} igrača`}
            {exportFilter === 'position' && `${players.filter(p => p.position === exportPosition).length} igrača (${exportPosition})`}
            {exportFilter === 'category' && `${players.filter(p => getCategory(p.birthYear) === exportCategory).length} igrača (${exportCategory})`}
            {exportFilter === 'paid' && `${players.filter(p => p.membershipStatus === 'paid').length} igrača sa plaćenom članarinm`}
            {exportFilter === 'unpaid' && `${players.filter(p => p.membershipStatus !== 'paid').length} igrača bez plaćene članarine`}
          </div>
        </div>
      </Modal>

      {/* ── Import Result Modal ── */}
      <Modal
        isOpen={showImportResult}
        onClose={() => setShowImportResult(false)}
        title="Rezultat importa"
        width={420}
        footer={
          <button className="btn btn-primary" onClick={() => setShowImportResult(false)}>OK</button>
        }
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <div style={{ display: 'flex', gap: 12 }}>
            <div style={{ flex: 1, textAlign: 'center', padding: '16px 8px', background: 'rgba(34,197,94,0.08)', borderRadius: 10, border: '1px solid rgba(34,197,94,0.2)' }}>
              <div style={{ fontSize: '2rem', fontWeight: 800, color: '#22c55e' }}>{importResult?.added?.length ?? 0}</div>
              <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)' }}>Dodato</div>
            </div>
            <div style={{ flex: 1, textAlign: 'center', padding: '16px 8px', background: 'rgba(234,179,8,0.08)', borderRadius: 10, border: '1px solid rgba(234,179,8,0.2)' }}>
              <div style={{ fontSize: '2rem', fontWeight: 800, color: '#eab308' }}>{importResult?.skipped?.length ?? 0}</div>
              <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)' }}>Preskočeno (duplikat)</div>
            </div>
          </div>
          {importResult?.skipped?.length > 0 && (
            <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)' }}>
              <strong style={{ color: 'var(--text-primary)' }}>Preskočeni:</strong>{' '}
              {importResult.skipped.join(', ')}
            </div>
          )}
          {importResult?.errors?.length > 0 && (
            <div style={{ fontSize: '0.82rem', color: '#ef4444' }}>
              {importResult.errors.map((e, i) => <div key={i}>{e}</div>)}
            </div>
          )}
        </div>
      </Modal>
    </div>
  );
}
