import React, { useState } from 'react';
import {
  Chart as ChartJS,
  RadialLinearScale,
  PointElement,
  LineElement,
  Filler,
  Tooltip,
  Legend
} from 'chart.js';
import { Radar } from 'react-chartjs-2';
import { usePlayers } from '../../../hooks/usePlayers';
import { useTrainings } from '../../../hooks/useTrainings';
import Modal from '../../../components/common/Modal';
import { formatDate, PILLARS, getPillarLabel, getScoreColor } from '../../../utils/helpers';

ChartJS.register(RadialLinearScale, PointElement, LineElement, Filler, Tooltip, Legend);

const GOAL_STATUSES = [
  { value: 'active', label: 'Aktivan', color: '#f59e0b' },
  { value: 'completed', label: 'Završen', color: '#22c55e' },
  { value: 'missed', label: 'Propušten', color: '#ef4444' }
];

export default function Progress({ player }) {
  const { addAssessment, addGoal, updateGoal, deleteGoal } = usePlayers();
  const { trainings } = useTrainings();

  // Treninzi gdje je ovaj igrač bio prisutan i ocenjen
  const playerTrainings = trainings
    .filter(t => t.completed && t.ratings && t.ratings[player.id] && t.attendance && t.attendance[player.id] === true)
    .sort((a, b) => (b.date + (b.time || '')).localeCompare(a.date + (a.time || '')));
  const [assessModal, setAssessModal] = useState(false);
  const [goalModal, setGoalModal] = useState(false);
  const [saving, setSaving] = useState(false);

  const [assessForm, setAssessForm] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'trainer',
    technical: 5,
    tactical: 5,
    physical: 5,
    psychological: 5,
    note: ''
  });

  const [goalForm, setGoalForm] = useState({
    title: '',
    targetDate: '',
    status: 'active',
    notes: ''
  });

  const assessments = player.assessments ? Object.entries(player.assessments).map(([id, v]) => ({ id, ...v })) : [];
  const goals = player.goals ? Object.entries(player.goals).map(([id, v]) => ({ id, ...v })) : [];

  const sortedAssessments = [...assessments].sort((a, b) => new Date(a.date) - new Date(b.date));
  const initial = sortedAssessments[0];
  const latest = sortedAssessments[sortedAssessments.length - 1];

  const handleAddAssessment = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      await addAssessment(player.id, {
        ...assessForm,
        technical: parseInt(assessForm.technical),
        tactical: parseInt(assessForm.tactical),
        physical: parseInt(assessForm.physical),
        psychological: parseInt(assessForm.psychological)
      });
      setAssessModal(false);
      setAssessForm({ date: new Date().toISOString().split('T')[0], type: 'trainer', technical: 5, tactical: 5, physical: 5, psychological: 5, note: '' });
    } catch (err) {
      console.error(err);
    } finally {
      setSaving(false);
    }
  };

  const handleAddGoal = async (e) => {
    e.preventDefault();
    if (!goalForm.title.trim()) return;
    setSaving(true);
    try {
      await addGoal(player.id, goalForm);
      setGoalModal(false);
      setGoalForm({ title: '', targetDate: '', status: 'active', notes: '' });
    } catch (err) {
      console.error(err);
    } finally {
      setSaving(false);
    }
  };

  const handleGoalStatusChange = async (goal, newStatus) => {
    try {
      await updateGoal(player.id, goal.id, { ...goal, status: newStatus });
    } catch (err) {
      console.error(err);
    }
  };

  const handleDeleteGoal = async (goalId) => {
    if (!window.confirm('Obrisati ovaj cilj?')) return;
    try {
      await deleteGoal(player.id, goalId);
    } catch (err) {
      console.error(err);
    }
  };

  const radarData = {
    labels: PILLARS.map(p => p.label),
    datasets: [
      ...(initial && initial !== latest ? [{
        label: `Početak (${formatDate(initial.date)})`,
        data: [initial.technical, initial.tactical, initial.physical, initial.psychological],
        backgroundColor: 'rgba(200, 134, 10, 0.1)',
        borderColor: 'rgba(200, 134, 10, 0.6)',
        borderWidth: 2,
        pointBackgroundColor: 'rgba(200, 134, 10, 0.8)',
        pointRadius: 4
      }] : []),
      ...(latest ? [{
        label: `Trenutno (${formatDate(latest.date)})`,
        data: [latest.technical, latest.tactical, latest.physical, latest.psychological],
        backgroundColor: 'rgba(34, 197, 94, 0.1)',
        borderColor: 'rgba(34, 197, 94, 0.7)',
        borderWidth: 2,
        pointBackgroundColor: 'rgba(34, 197, 94, 0.9)',
        pointRadius: 4
      }] : [])
    ]
  };

  const radarOptions = {
    responsive: true,
    maintainAspectRatio: true,
    scales: {
      r: {
        min: 0,
        max: 10,
        ticks: {
          stepSize: 2,
          color: '#606060',
          font: { size: 10 },
          backdropColor: 'transparent'
        },
        grid: { color: '#2a2a2a' },
        angleLines: { color: '#2a2a2a' },
        pointLabels: {
          color: '#a0a0a0',
          font: { size: 12, weight: 'bold' }
        }
      }
    },
    plugins: {
      legend: {
        labels: {
          color: '#a0a0a0',
          font: { size: 11 },
          padding: 16
        }
      }
    }
  };

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
        <h3>Napredak igrača</h3>
        <div style={{ display: 'flex', gap: 8 }}>
          <button className="btn btn-secondary btn-sm" onClick={() => setGoalModal(true)}>
            + Dodaj cilj
          </button>
          <button className="btn btn-primary btn-sm" onClick={() => setAssessModal(true)}>
            + Profilisanje igrača
          </button>
        </div>
      </div>

      {/* Chart */}
      {assessments.length > 0 ? (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 24 }}>
          {/* Radar */}
          <div style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius)',
            padding: 20
          }}>
            <h4 style={{ marginBottom: 16 }}>Graf napretka</h4>
            <div style={{ maxWidth: 300, margin: '0 auto' }}>
              <Radar data={radarData} options={radarOptions} />
            </div>
          </div>

          {/* Scores comparison */}
          <div style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius)',
            padding: 20
          }}>
            <h4 style={{ marginBottom: 16 }}>Poređenje stubova</h4>
            {PILLARS.map(pillar => {
              const initVal = initial?.[pillar.key] || 0;
              const latestVal = latest?.[pillar.key] || 0;
              const diff = latestVal - initVal;
              return (
                <div key={pillar.key} style={{ marginBottom: 14 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                    <span style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                      {pillar.icon} {pillar.label}
                    </span>
                    <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                      {initial && initial !== latest && (
                        <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                          {initVal} →
                        </span>
                      )}
                      <span style={{ fontSize: '0.9rem', fontWeight: 700, color: getScoreColor(latestVal) }}>
                        {latestVal}/10
                      </span>
                      {diff !== 0 && initial !== latest && (
                        <span style={{
                          fontSize: '0.72rem',
                          fontWeight: 700,
                          color: diff > 0 ? 'var(--success)' : 'var(--error)'
                        }}>
                          {diff > 0 ? '+' : ''}{diff}
                        </span>
                      )}
                    </div>
                  </div>
                  <div style={{ height: 6, background: 'var(--border)', borderRadius: 6, overflow: 'hidden' }}>
                    <div style={{
                      width: `${(latestVal / 10) * 100}%`,
                      height: '100%',
                      background: getScoreColor(latestVal),
                      borderRadius: 6,
                      transition: 'width 0.5s ease'
                    }} />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ) : (
        <div className="empty-state" style={{ marginBottom: 24 }}>
          <div className="empty-state-icon">📊</div>
          <div className="empty-state-title">Nema profilisanja</div>
          <p className="empty-state-text">Dodaj prvo profilisanje igrača da počneš da pratiš napredak.</p>
        </div>
      )}

      {/* Assessment history */}
      {assessments.length > 0 && (
        <div style={{ marginBottom: 24 }}>
          <h4 style={{ marginBottom: 12 }}>Istorija profilisanja</h4>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {[...assessments].sort((a, b) => new Date(b.date) - new Date(a.date)).map((a) => (
              <div key={a.id} style={{
                background: 'var(--bg-primary)',
                border: '1px solid var(--border)',
                borderRadius: 'var(--radius-sm)',
                padding: '12px 16px',
                display: 'flex',
                gap: 16,
                alignItems: 'center',
                flexWrap: 'wrap'
              }}>
                <div style={{ minWidth: 100 }}>
                  <div style={{ fontSize: '0.82rem', fontWeight: 700 }}>{formatDate(a.date)}</div>
                  <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)' }}>
                    {a.type === 'trainer' ? '👨‍🏫 Trener' : '👤 Igrač'}
                  </div>
                </div>
                {PILLARS.map(p => (
                  <div key={p.key} style={{ textAlign: 'center' }}>
                    <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>{p.label}</div>
                    <div style={{ fontSize: '1rem', fontWeight: 700, color: getScoreColor(a[p.key]) }}>
                      {a[p.key]}
                    </div>
                  </div>
                ))}
                {a.note && (
                  <div style={{ flex: 1, fontSize: '0.8rem', color: 'var(--text-secondary)', fontStyle: 'italic' }}>
                    "{a.note}"
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Ocene sa treninga */}
      {playerTrainings.length > 0 && (
        <div style={{ marginBottom: 24 }}>
          <h4 style={{ marginBottom: 12 }}>Ocene sa treninga</h4>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {playerTrainings.map(t => {
              const r = t.ratings[player.id];
              const criteria = Object.keys(r);
              const avg = criteria.length > 0
                ? (criteria.reduce((s, c) => s + (parseFloat(r[c]) || 0), 0) / criteria.length).toFixed(1)
                : '-';
              return (
                <div key={t.id} style={{
                  background: 'var(--bg-primary)', border: '1px solid var(--border)',
                  borderRadius: 'var(--radius-sm)', padding: '12px 16px',
                  display: 'flex', gap: 16, alignItems: 'center', flexWrap: 'wrap'
                }}>
                  <div style={{ minWidth: 110 }}>
                    <div style={{ fontSize: '0.82rem', fontWeight: 700 }}>{formatDate(t.date)}</div>
                    <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)' }}>{t.name}</div>
                  </div>
                  <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', flex: 1 }}>
                    {criteria.map(c => (
                      <div key={c} style={{ textAlign: 'center' }}>
                        <div style={{ fontSize: '0.68rem', color: 'var(--text-muted)' }}>{c}</div>
                        <div style={{ fontSize: '0.95rem', fontWeight: 700, color: getScoreColor(r[c]) }}>
                          {parseFloat(r[c]).toFixed(1)}
                        </div>
                      </div>
                    ))}
                  </div>
                  <div style={{ textAlign: 'center', minWidth: 48 }}>
                    <div style={{ fontSize: '0.68rem', color: 'var(--text-muted)' }}>Prosek</div>
                    <div style={{ fontSize: '1.1rem', fontWeight: 700, color: getScoreColor(parseFloat(avg)) }}>
                      {avg}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Goals section */}
      <div>
        <h4 style={{ marginBottom: 12 }}>Ciljevi igrača</h4>
        {goals.length === 0 ? (
          <div style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius)',
            padding: '24px',
            textAlign: 'center',
            color: 'var(--text-muted)',
            fontSize: '0.88rem'
          }}>
            Nema definisanih ciljeva. Dodaj prvi cilj!
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {[...goals].sort((a, b) => {
              const order = { active: 0, pending: 1, completed: 2, missed: 3 };
              return (order[a.status] || 0) - (order[b.status] || 0);
            }).map(goal => {
              const statusCfg = GOAL_STATUSES.find(s => s.value === goal.status) || GOAL_STATUSES[0];
              return (
                <div key={goal.id} style={{
                  background: 'var(--bg-primary)',
                  border: '1px solid var(--border)',
                  borderRadius: 'var(--radius-sm)',
                  padding: '14px 16px',
                  display: 'flex',
                  gap: 12,
                  alignItems: 'flex-start'
                }}>
                  <div style={{
                    width: 8,
                    height: 8,
                    borderRadius: '50%',
                    background: statusCfg.color,
                    marginTop: 6,
                    flexShrink: 0
                  }} />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 600, marginBottom: 4 }}>{goal.title}</div>
                    {goal.targetDate && (
                      <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', marginBottom: 4 }}>
                        📅 Rok: {formatDate(goal.targetDate)}
                      </div>
                    )}
                    {goal.notes && (
                      <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>{goal.notes}</div>
                    )}
                  </div>
                  <div style={{ display: 'flex', gap: 6, flexShrink: 0 }}>
                    <select
                      value={goal.status}
                      onChange={e => handleGoalStatusChange(goal, e.target.value)}
                      style={{
                        background: 'var(--bg-card)',
                        border: '1px solid var(--border)',
                        borderRadius: 4,
                        color: statusCfg.color,
                        fontSize: '0.75rem',
                        padding: '3px 6px',
                        cursor: 'pointer'
                      }}
                    >
                      {GOAL_STATUSES.map(s => (
                        <option key={s.value} value={s.value}>{s.label}</option>
                      ))}
                    </select>
                    <button
                      onClick={() => handleDeleteGoal(goal.id)}
                      style={{
                        background: 'transparent',
                        border: 'none',
                        color: 'var(--text-muted)',
                        cursor: 'pointer',
                        fontSize: '0.9rem',
                        padding: '2px 4px'
                      }}
                    >
                      ✕
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Assessment Modal */}
      <Modal
        isOpen={assessModal}
        onClose={() => setAssessModal(false)}
        title="Profilisanje igrača"
        width={500}
        footer={
          <>
            <button className="btn btn-secondary" onClick={() => setAssessModal(false)}>Otkaži</button>
            <button className="btn btn-primary" onClick={handleAddAssessment} disabled={saving}>
              {saving ? 'Čuvam...' : 'Sačuvaj profil'}
            </button>
          </>
        }
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div className="form-row">
            <div className="form-group">
              <label className="label">Datum</label>
              <input
                type="date"
                className="input"
                value={assessForm.date}
                onChange={e => setAssessForm(p => ({ ...p, date: e.target.value }))}
              />
            </div>
            <div className="form-group">
              <label className="label">Ko procenjuje</label>
              <select
                className="input"
                value={assessForm.type}
                onChange={e => setAssessForm(p => ({ ...p, type: e.target.value }))}
              >
                <option value="trainer">Trener</option>
                <option value="player">Igrač</option>
              </select>
            </div>
          </div>

          {PILLARS.map(pillar => (
            <div key={pillar.key} className="form-group">
              <label className="label">
                {pillar.icon} {pillar.label} - {assessForm[pillar.key]}/10
              </label>
              <input
                type="range"
                min="1"
                max="10"
                value={assessForm[pillar.key]}
                onChange={e => setAssessForm(p => ({ ...p, [pillar.key]: e.target.value }))}
                style={{ width: '100%', accentColor: 'var(--gold)' }}
              />
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.7rem', color: 'var(--text-muted)' }}>
                <span>1 - Osnovno</span>
                <span>5 - Srednje</span>
                <span>10 - Odlično</span>
              </div>
            </div>
          ))}

          <div className="form-group">
            <label className="label">Napomena</label>
            <textarea
              className="input"
              rows={3}
              placeholder="Komentar uz profilisanje..."
              value={assessForm.note}
              onChange={e => setAssessForm(p => ({ ...p, note: e.target.value }))}
            />
          </div>
        </div>
      </Modal>

      {/* Goal Modal */}
      <Modal
        isOpen={goalModal}
        onClose={() => setGoalModal(false)}
        title="Dodaj cilj"
        width={440}
        footer={
          <>
            <button className="btn btn-secondary" onClick={() => setGoalModal(false)}>Otkaži</button>
            <button className="btn btn-primary" onClick={handleAddGoal} disabled={saving || !goalForm.title.trim()}>
              {saving ? 'Čuvam...' : 'Dodaj cilj'}
            </button>
          </>
        }
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <div className="form-group">
            <label className="label">Naziv cilja *</label>
            <input
              className="input"
              placeholder="npr. Poboljšati šut levom nogom"
              value={goalForm.title}
              onChange={e => setGoalForm(p => ({ ...p, title: e.target.value }))}
            />
          </div>
          <div className="form-group">
            <label className="label">Rok (datum)</label>
            <input
              type="date"
              className="input"
              value={goalForm.targetDate}
              onChange={e => setGoalForm(p => ({ ...p, targetDate: e.target.value }))}
            />
          </div>
          <div className="form-group">
            <label className="label">Status</label>
            <select
              className="input"
              value={goalForm.status}
              onChange={e => setGoalForm(p => ({ ...p, status: e.target.value }))}
            >
              {GOAL_STATUSES.map(s => (
                <option key={s.value} value={s.value}>{s.label}</option>
              ))}
            </select>
          </div>
          <div className="form-group">
            <label className="label">Napomene</label>
            <textarea
              className="input"
              rows={3}
              placeholder="Dodatne napomene o cilju..."
              value={goalForm.notes}
              onChange={e => setGoalForm(p => ({ ...p, notes: e.target.value }))}
            />
          </div>
        </div>
      </Modal>
    </div>
  );
}
