import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../../auth/AuthContext';
import { useTrainings } from '../../hooks/useTrainings';
import { useMyPlayer } from '../../hooks/useMyPlayer';
import { usePlayerRatings } from '../../hooks/usePlayerRatings';
import { notifyCoach } from '../../utils/notifications';
import { formatDate } from '../../utils/helpers';

const RATING_CRITERIA = [
  { key: 'Intenzitet', icon: '⚡', label: 'Intenzitet' },
  { key: 'Zanimljivost', icon: '🎯', label: 'Zanimljivost' },
  { key: 'Tehnicko', icon: '⚽', label: 'Tehničko' },
  { key: 'Takticko', icon: '🧠', label: 'Taktičko' },
  { key: 'Brzina', icon: '💨', label: 'Brzina' },
];

export default function PlayerTrainingRating() {
  const { id } = useParams();
  const { playerId } = useAuth();
  const { trainings, loading: tLoad } = useTrainings();
  const { player } = useMyPlayer(playerId);
  const { myRating, allRatings, loading: rLoad, submitRating } = usePlayerRatings(id, playerId);
  const navigate = useNavigate();

  const [ratings, setRatings] = useState({});
  const [comment, setComment] = useState('');
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  const training = trainings.find(t => t.id === id);

  useEffect(() => {
    if (myRating) {
      setRatings({
        Intenzitet: myRating.Intenzitet || 5,
        Zanimljivost: myRating.Zanimljivost || 5,
        Tehnicko: myRating.Tehnicko || 5,
        Takticko: myRating.Takticko || 5,
        Brzina: myRating.Brzina || 5,
      });
      setComment(myRating.comment || '');
    } else {
      const init = {};
      RATING_CRITERIA.forEach(c => { init[c.key] = 7; });
      setRatings(init);
    }
  }, [myRating]);

  if (tLoad || rLoad) return <div style={{ textAlign: 'center', padding: 20, color: 'var(--text-muted)' }}>Učitavam...</div>;

  if (!training) {
    return (
      <div style={{ textAlign: 'center', padding: 32 }}>
        <div style={{ fontSize: '2rem', marginBottom: 8 }}>❌</div>
        <div style={{ color: 'var(--text-muted)', marginBottom: 16 }}>Trening nije pronađen</div>
        <button className="btn btn-secondary" onClick={() => navigate('/player/planer')}>← Planer</button>
      </div>
    );
  }

  if (!training.completed) {
    return (
      <div style={{ textAlign: 'center', padding: 32 }}>
        <div style={{ fontSize: '2rem', marginBottom: 8 }}>⏳</div>
        <div style={{ color: 'var(--text-muted)', marginBottom: 4 }}>Trening još nije završen</div>
        <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: 16 }}>Ocenjivanje je dostupno nakon što trener završi trening.</div>
        <button className="btn btn-secondary" onClick={() => navigate('/player/planer')}>← Planer</button>
      </div>
    );
  }

  const handleSubmit = async () => {
    setSaving(true);
    try {
      await submitRating({ ...ratings, comment });
      const playerName = `${player?.firstName || ''} ${player?.lastName || ''}`.trim();
      await notifyCoach({
        type: 'player_rating',
        title: 'Igrač ocenio trening',
        message: `${playerName} je ocenio/la trening "${training.name}"`,
        link: `trening:${id}`
      });
      setSaved(true);
    } finally {
      setSaving(false);
    }
  };

  const ratingCount = Object.keys(allRatings).length;

  return (
    <div>
      <button className="btn btn-secondary btn-sm" onClick={() => navigate('/player/planer')} style={{ marginBottom: 16 }}>
        ← Planer
      </button>

      <div style={{
        background: 'var(--bg-card)',
        border: '1px solid var(--border)',
        borderRadius: 'var(--radius-lg)',
        padding: '16px',
        marginBottom: 20
      }}>
        <h1 style={{ fontSize: '1.1rem', fontWeight: 700, margin: '0 0 4px' }}>{training.name}</h1>
        <div style={{ fontSize: '0.82rem', color: 'var(--text-muted)' }}>
          📅 {formatDate(training.date)} {training.time && `• 🕐 ${training.time}`}
        </div>
        <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', marginTop: 4 }}>
          {ratingCount} {ratingCount === 1 ? 'igrač ocenio' : 'igrača ocenilo'} trening
        </div>
      </div>

      {saved || myRating ? (
        <div style={{
          background: 'var(--success-bg)',
          border: '1px solid var(--success)',
          borderRadius: 'var(--radius)',
          padding: '16px',
          textAlign: 'center',
          marginBottom: 16
        }}>
          <div style={{ fontSize: '1.5rem', marginBottom: 6 }}>✅</div>
          <div style={{ color: 'var(--success)', fontWeight: 600 }}>Trening je ocenjen!</div>
          {myRating && (
            <div style={{ marginTop: 12, display: 'flex', flexWrap: 'wrap', gap: 8, justifyContent: 'center' }}>
              {RATING_CRITERIA.map(c => (
                <div key={c.key} style={{
                  background: 'rgba(34,197,94,0.1)',
                  border: '1px solid rgba(34,197,94,0.2)',
                  borderRadius: 8,
                  padding: '6px 12px',
                  textAlign: 'center'
                }}>
                  <div style={{ fontSize: '0.65rem', color: 'var(--text-muted)', marginBottom: 2 }}>{c.icon} {c.label}</div>
                  <div style={{ fontWeight: 700, fontSize: '1rem' }}>{myRating[c.key] || '—'}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      ) : (
        <div>
          <h2 style={{ fontSize: '1rem', fontWeight: 700, marginBottom: 14 }}>⭐ Oceni trening</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {RATING_CRITERIA.map(c => (
              <div key={c.key}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
                  <span style={{ fontSize: '0.9rem', fontWeight: 600 }}>{c.icon} {c.label}</span>
                  <span style={{ fontSize: '1rem', fontWeight: 700, color: 'var(--gold)' }}>{ratings[c.key] || 7}</span>
                </div>
                <input
                  type="range"
                  min={1}
                  max={10}
                  step={1}
                  value={ratings[c.key] || 7}
                  onChange={e => setRatings(prev => ({ ...prev, [c.key]: parseInt(e.target.value) }))}
                  style={{ width: '100%', accentColor: 'var(--gold)', height: 6 }}
                />
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.65rem', color: 'var(--text-muted)', marginTop: 2 }}>
                  <span>1</span><span>5</span><span>10</span>
                </div>
              </div>
            ))}

            <div className="form-group">
              <label className="label">Komentar (opciono)</label>
              <textarea
                className="input"
                rows={2}
                placeholder="Utisak sa treninga..."
                value={comment}
                onChange={e => setComment(e.target.value)}
              />
            </div>

            <button
              className="btn btn-primary"
              onClick={handleSubmit}
              disabled={saving}
              style={{ height: 46, fontSize: '0.95rem' }}
            >
              {saving ? 'Čuvam...' : '⭐ Pošalji ocenu'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
