import { useState, useEffect } from 'react';
import { ref, onValue, update } from 'firebase/database';
import { db } from '../firebase';

export function useMyPlayer(playerId) {
  const [player, setPlayer] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!playerId) { setLoading(false); return; }
    const r = ref(db, `players/${playerId}`);
    return onValue(r, (snap) => {
      setPlayer(snap.val() ? { id: playerId, ...snap.val() } : null);
      setLoading(false);
    });
  }, [playerId]);

  const updateMyPlayer = async (data) => {
    if (!playerId) return;
    await update(ref(db, `players/${playerId}`), data);
  };

  return { player, loading, updateMyPlayer };
}
