import React from 'react';
import { NavLink, useLocation } from 'react-router-dom';

const navItems = [
  { path: '/', label: 'Dashboard', icon: '🏠', exact: true },
  { path: '/golmani', label: 'Golmani', icon: '🧤' },
  { path: '/treninzi', label: 'Planer', icon: '📅' },
  { path: '/vezbe', label: 'Vežbe', icon: '⚽' },
  { path: '/napredak', label: 'Napredak', icon: '📊' },
  { path: '/izvestaji', label: 'Izveštaji', icon: '📋' },
  { path: '/clanarine', label: 'Članarine', icon: '💳' },
  { path: '/podesavanja', label: 'Podešavanja', icon: '⚙️' }
];

export default function Sidebar({ isOpen, onClose }) {
  const location = useLocation();

  return (
    <>
      <aside style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: 'var(--sidebar-width)',
        height: '100vh',
        background: '#111111',
        borderRight: '1px solid var(--border)',
        display: 'flex',
        flexDirection: 'column',
        zIndex: 99,
        transition: 'transform 0.3s ease',
        overflowY: 'auto'
      }}
        className={`sidebar ${isOpen ? 'sidebar-open' : ''}`}
      >
        {/* Logo */}
        <div style={{
          height: 'var(--header-height)',
          padding: '0 20px',
          borderBottom: '1px solid var(--border)',
          display: 'flex',
          alignItems: 'center',
          gap: 12,
          flexShrink: 0
        }}>
          <img
            src={`${process.env.PUBLIC_URL}/logo.png`}
            alt="JGK Logo"
            style={{ width: 38, height: 38, objectFit: 'contain', flexShrink: 0 }}
          />
          <div>
            <div style={{
              fontSize: '0.72rem',
              fontWeight: 800,
              color: '#fff',
              letterSpacing: '0.03em',
              lineHeight: 1.25
            }}>
              JEVRIĆ GOALKEEPER<br />ACADEMY
            </div>
          </div>
        </div>

        {/* Navigation */}
        <nav style={{ padding: '16px 12px', flex: 1 }}>
          <div style={{
            fontSize: '0.68rem',
            color: 'var(--text-muted)',
            fontWeight: 700,
            letterSpacing: '0.1em',
            textTransform: 'uppercase',
            padding: '0 8px',
            marginBottom: 10
          }}>
            Meni
          </div>
          {navItems.map(item => {
            const isActive = item.exact
              ? location.pathname === item.path
              : location.pathname.startsWith(item.path);

            return (
              <NavLink
                key={item.path}
                to={item.path}
                onClick={onClose}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 12,
                  padding: '11px 12px',
                  borderRadius: 8,
                  marginBottom: 2,
                  textDecoration: 'none',
                  transition: 'all 0.2s ease',
                  background: isActive ? 'rgba(37, 99, 235, 0.12)' : 'transparent',
                  color: isActive ? '#60a5fa' : 'var(--text-secondary)',
                  borderLeft: isActive ? '3px solid #2563eb' : '3px solid transparent',
                  fontWeight: isActive ? 600 : 400
                }}
                onMouseEnter={e => {
                  if (!isActive) {
                    e.currentTarget.style.background = 'rgba(255,255,255,0.04)';
                    e.currentTarget.style.color = 'var(--text-primary)';
                  }
                }}
                onMouseLeave={e => {
                  if (!isActive) {
                    e.currentTarget.style.background = 'transparent';
                    e.currentTarget.style.color = 'var(--text-secondary)';
                  }
                }}
              >
                <span style={{ fontSize: '1.1rem', width: 22, textAlign: 'center' }}>
                  {item.icon}
                </span>
                <span style={{ fontSize: '0.88rem' }}>{item.label}</span>
                {isActive && (
                  <span style={{
                    marginLeft: 'auto',
                    width: 6,
                    height: 6,
                    borderRadius: '50%',
                    background: '#2563eb'
                  }} />
                )}
              </NavLink>
            );
          })}
        </nav>

        {/* Footer */}
        <div style={{
          padding: '16px 20px',
          borderTop: '1px solid var(--border)',
          fontSize: '0.72rem',
          color: 'var(--text-muted)',
          textAlign: 'center'
        }}>
          <div style={{ marginBottom: 2 }}>JEVRAGKlab</div>
          <div>v1.0.0 · Individual Training App</div>
        </div>
      </aside>

      <style>{`
        @media (max-width: 768px) {
          .sidebar {
            transform: translateX(-100%);
            width: 260px !important;
          }
          .sidebar.sidebar-open {
            transform: translateX(0);
          }
        }
      `}</style>
    </>
  );
}
