import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { onAuthStateChanged, signInWithEmailAndPassword, signOut } from 'firebase/auth';
import { ref, onValue } from 'firebase/database';
import { auth, db } from '../firebase';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [userRole, setUserRole] = useState(null);
  const [playerId, setPlayerId] = useState(null);
  const [authLoading, setAuthLoading] = useState(true);
  const roleUnsubRef = useRef(null);

  useEffect(() => {
    const authUnsub = onAuthStateChanged(auth, (firebaseUser) => {
      // Očisti prethodni role listener
      if (roleUnsubRef.current) {
        roleUnsubRef.current();
        roleUnsubRef.current = null;
      }

      if (firebaseUser) {
        setUser(firebaseUser);
        // Real-time listener — pokupi ulogu čim se users/{uid} napiše
        roleUnsubRef.current = onValue(ref(db, `users/${firebaseUser.uid}`), (snap) => {
          const data = snap.val();
          if (data?.role === 'player') {
            setUserRole('player');
            setPlayerId(data.playerId);
          } else {
            setUserRole('coach');
            setPlayerId(null);
          }
          setAuthLoading(false);
        });
      } else {
        setUser(null);
        setUserRole(null);
        setPlayerId(null);
        setAuthLoading(false);
      }
    });

    return () => {
      authUnsub();
      if (roleUnsubRef.current) roleUnsubRef.current();
    };
  }, []);

  const login = (email, password) => signInWithEmailAndPassword(auth, email, password);
  const logout = () => signOut(auth);

  return (
    <AuthContext.Provider value={{ user, userRole, playerId, authLoading, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
