import React, { useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';
import { useMyPlayer } from '../hooks/useMyPlayer';
import { useTrainings } from '../hooks/useTrainings';
import { useNotifications } from '../hooks/useNotifications';
import { formatDate } from '../utils/helpers';

function toDateKey(d) {
  const y = d.getFullYear(), m = String(d.getMonth() + 1).padStart(2, '0'), day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

export default function PlayerDashboard() {
  const { playerId } = useAuth();
  const { player, loading: pLoad } = useMyPlayer(playerId);
  const { trainings, loading: tLoad } = useTrainings();
  const { notifications, unreadCount, markRead } = useNotifications(playerId);
  const navigate = useNavigate();

  const today = toDateKey(new Date());
  const in7 = toDateKey(new Date(Date.now() + 7 * 86400000));

  const upcomingTrainings = useMemo(() => {
    return trainings
      .filter(t => t.playerIds?.includes(playerId) && t.date >= today && t.date <= in7)
      .sort((a, b) => (a.date + (a.time || '')).localeCompare(b.date + (b.time || '')));
  }, [trainings, playerId, today, in7]);

  const recentNotifs = notifications.slice(0, 5);

  const handleNotifClick = async (notif) => {
    await markRead(notif.id);
    const link = notif.link || '';
    if (link.startsWith('trening:')) {
      navigate(`/player/trening/${link.replace('trening:', '')}`);
    } else if (link === 'napomene') {
      navigate('/player/napredak');
    } else if (link === 'procena' || link === 'analiza') {
      navigate('/player/napredak');
    } else if (link === 'planer') {
      navigate('/player/planer');
    }
  };

  const attendances = player?.attendances ? Object.values(player.attendances) : [];
  const thisMonth = new Date().toISOString().substring(0, 7);
  const monthAttendances = attendances.filter(a => (a.date || '').startsWith(thisMonth));
  const presentCount = monthAttendances.filter(a => a.present === true).length;

  if (pLoad || tLoad) {
    return <div style={{ padding: 20, textAlign: 'center', color: 'var(--text-muted)' }}>Učitavam...</div>;
  }

  const firstName = player?.firstName || 'Igraču';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      {/* Greeting */}
      <div style={{
        background: 'linear-gradient(135deg, rgba(37,99,235,0.15) 0%, rgba(37,99,235,0.05) 100%)',
        border: '1px solid rgba(37,99,235,0.25)',
        borderRadius: 'var(--radius-lg)',
        padding: '18px 20px'
      }}>
        <h1 style={{ fontSize: '1.3rem', fontWeight: 700, margin: 0 }}>👋 Zdravo, {firstName}!</h1>
        <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginTop: 4, marginBottom: 0 }}>
          {new Date().toLocaleDateString('sr-Latn-RS', { weekday: 'long', day: 'numeric', month: 'long' })}
        </p>
      </div>

      {/* Stats row */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
        <div style={{
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius)',
          padding: '14px 16px',
          textAlign: 'center'
        }}>
          <div style={{ fontSize: '1.6rem', fontWeight: 700, color: 'var(--gold)' }}>{presentCount}</div>
          <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 2 }}>treninga ovog meseca</div>
        </div>
        <div style={{
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius)',
          padding: '14px 16px',
          textAlign: 'center'
        }}>
          <div style={{ fontSize: '1.6rem', fontWeight: 700, color: unreadCount > 0 ? 'var(--warning)' : 'var(--gold)' }}>
            {unreadCount}
          </div>
          <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 2 }}>nepročitanih</div>
        </div>
      </div>

      {/* Upcoming trainings */}
      <div>
        <h2 style={{ fontSize: '0.9rem', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: 10, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
          Predstojeći treninzi
        </h2>
        {upcomingTrainings.length === 0 ? (
          <div style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius)',
            padding: '16px',
            textAlign: 'center',
            color: 'var(--text-muted)',
            fontSize: '0.85rem'
          }}>
            Nema treninga u sledećih 7 dana
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {upcomingTrainings.map(t => {
              const firstImg = t.images?.[0] || t.imageBase64 || null;
              return (
                <div
                  key={t.id}
                  onClick={() => navigate('/player/planer')}
                  style={{
                    background: 'var(--bg-card)',
                    border: '1px solid var(--border)',
                    borderRadius: 'var(--radius)',
                    padding: '12px 14px',
                    cursor: 'pointer'
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 10 }}>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 600, fontSize: '0.95rem' }}>{t.name}</div>
                      <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', marginTop: 2 }}>
                        📅 {formatDate(t.date)} {t.time && `• 🕐 ${t.time}`} {t.duration && `• ${t.duration} min`}
                      </div>
                      {t.note && (
                        <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', marginTop: 5, fontStyle: 'italic' }}>
                          📋 {t.note}
                        </div>
                      )}
                    </div>
                    {firstImg && (
                      <img src={firstImg} alt="" style={{ width: 56, height: 42, objectFit: 'cover', borderRadius: 6, flexShrink: 0, border: '1px solid var(--border)' }} />
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Recent notifications */}
      {recentNotifs.length > 0 && (
        <div>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
            <h2 style={{ fontSize: '0.9rem', fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.05em', margin: 0 }}>
              Obaveštenja
            </h2>
            <button
              onClick={() => navigate('/player/notifikacije')}
              style={{ fontSize: '0.75rem', color: 'var(--gold)', background: 'none', border: 'none', cursor: 'pointer' }}
            >
              Sve →
            </button>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            {recentNotifs.map(n => (
              <div
                key={n.id}
                onClick={() => handleNotifClick(n)}
                style={{
                  background: n.read ? 'var(--bg-card)' : 'rgba(37,99,235,0.07)',
                  border: `1px solid ${n.read ? 'var(--border)' : 'rgba(37,99,235,0.25)'}`,
                  borderRadius: 'var(--radius)',
                  padding: '10px 12px',
                  cursor: 'pointer',
                  display: 'flex',
                  gap: 10,
                  alignItems: 'flex-start'
                }}
              >
                <span style={{ fontSize: '1.1rem', flexShrink: 0 }}>
                  {n.type === 'training_completed' ? '⭐' :
                   n.type === 'new_training' ? '📅' :
                   n.type === 'training_note' ? '📝' :
                   n.type === 'procena' ? '📋' :
                   n.type === 'analiza' ? '🎬' : '🔔'}
                </span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontWeight: n.read ? 500 : 700, fontSize: '0.88rem' }}>{n.title}</div>
                  <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {n.message}
                  </div>
                </div>
                {!n.read && (
                  <div style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--gold)', flexShrink: 0, marginTop: 4 }} />
                )}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
