import React from 'react';
import { Routes, Route, NavLink, Navigate, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';
import { useNotifications } from '../hooks/useNotifications';
import PlayerDashboard from './PlayerDashboard';
import PlayerPlaner from './screens/PlayerPlaner';
import PlayerNapredak from './screens/PlayerNapredak';
import PlayerMyProfile from './screens/PlayerMyProfile';
import PlayerNotifications from './screens/PlayerNotifications';
import PlayerTrainingRating from './screens/PlayerTrainingRating';
import PlayerClanarina from './screens/PlayerClanarina';

const NAV = [
  { path: 'pocetna', label: 'Početna', icon: '🏠' },
  { path: 'planer', label: 'Planer', icon: '📅' },
  { path: 'napredak', label: 'Napredak', icon: '📊' },
  { path: 'clanarina', label: 'Članarina', icon: '💳' },
  { path: 'profil', label: 'Profil', icon: '👤' },
];

const PLANER_TYPES = ['new_training', 'training_completed'];
const NAPREDAK_TYPES = ['training_note', 'procena', 'analiza'];

export default function PlayerApp() {
  const { playerId, logout } = useAuth();
  const { notifications, unreadCount } = useNotifications(playerId);
  const navigate = useNavigate();

  const unread = notifications.filter(n => !n.read);
  const planerDot = unread.some(n => PLANER_TYPES.includes(n.type));
  const napredakDot = unread.some(n => NAPREDAK_TYPES.includes(n.type));

  const getDot = (path) => {
    if (path === 'planer') return planerDot;
    if (path === 'napredak') return napredakDot;
    return false;
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'var(--bg-primary)',
      paddingBottom: 72,
      maxWidth: 540,
      margin: '0 auto',
      position: 'relative'
    }}>
      {/* Top bar */}
      <div style={{
        position: 'sticky',
        top: 0,
        zIndex: 90,
        background: 'rgba(17,17,17,0.92)',
        backdropFilter: 'blur(10px)',
        borderBottom: '1px solid var(--border)',
        padding: '0 16px',
        height: 52,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between'
      }}>
        <span style={{ fontWeight: 700, fontSize: '1rem', letterSpacing: '0.02em' }}>⚽ JEVRAGKlab</span>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <button
            onClick={() => navigate('/player/notifikacije')}
            style={{
              position: 'relative',
              background: 'transparent',
              border: 'none',
              color: 'var(--text-secondary)',
              fontSize: '1.3rem',
              cursor: 'pointer',
              padding: '4px 8px'
            }}
          >
            🔔
            {unreadCount > 0 && (
              <span style={{
                position: 'absolute',
                top: 0,
                right: 2,
                background: 'var(--error)',
                color: '#fff',
                borderRadius: '50%',
                width: 18,
                height: 18,
                fontSize: '0.65rem',
                fontWeight: 700,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}>
                {unreadCount > 9 ? '9+' : unreadCount}
              </span>
            )}
          </button>
          <button
            onClick={logout}
            style={{
              background: 'transparent',
              border: '1px solid var(--border)',
              borderRadius: 6,
              color: 'var(--text-muted)',
              fontSize: '0.75rem',
              padding: '4px 10px',
              cursor: 'pointer'
            }}
          >
            Odjavi
          </button>
        </div>
      </div>

      {/* Content */}
      <div style={{ padding: '16px' }}>
        <Routes>
          <Route path="pocetna" element={<PlayerDashboard />} />
          <Route path="planer" element={<PlayerPlaner />} />
          <Route path="napredak" element={<PlayerNapredak />} />
          <Route path="clanarina" element={<PlayerClanarina />} />
          <Route path="profil" element={<PlayerMyProfile />} />
          <Route path="notifikacije" element={<PlayerNotifications />} />
          <Route path="trening/:id" element={<PlayerTrainingRating />} />
          <Route path="*" element={<Navigate to="pocetna" replace />} />
        </Routes>
      </div>

      {/* Bottom nav */}
      <nav style={{
        position: 'fixed',
        bottom: 0,
        left: '50%',
        transform: 'translateX(-50%)',
        width: '100%',
        maxWidth: 540,
        height: 64,
        background: 'rgba(26,26,26,0.97)',
        borderTop: '1px solid var(--border)',
        display: 'flex',
        zIndex: 100,
        backdropFilter: 'blur(10px)'
      }}>
        {NAV.map(item => {
          const hasDot = getDot(item.path);
          return (
            <NavLink
              key={item.path}
              to={`/player/${item.path}`}
              style={({ isActive }) => ({
                flex: 1,
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 2,
                textDecoration: 'none',
                color: isActive ? 'var(--gold)' : 'var(--text-muted)',
                fontSize: '0.58rem',
                fontWeight: 600,
                transition: 'color 0.15s',
                borderTop: isActive ? '2px solid var(--gold)' : '2px solid transparent',
                position: 'relative'
              })}
            >
              <span style={{ fontSize: '1.2rem', position: 'relative' }}>
                {item.icon}
                {hasDot && (
                  <span style={{
                    position: 'absolute',
                    top: -2,
                    right: -4,
                    width: 7,
                    height: 7,
                    borderRadius: '50%',
                    background: '#ef4444',
                    border: '1.5px solid var(--bg-primary)'
                  }} />
                )}
              </span>
              <span>{item.label}</span>
            </NavLink>
          );
        })}
      </nav>
    </div>
  );
}
