import { ref, push, set } from 'firebase/database';
import { db } from '../firebase';

export async function notifyPlayer(playerId, { type, title, message, link = '' }) {
  if (!playerId) return;
  try {
    const newRef = push(ref(db, `notifications/${playerId}`));
    await set(newRef, {
      type,
      title,
      message,
      link,
      read: false,
      createdAt: new Date().toISOString()
    });
  } catch (e) {
    console.warn('notifyPlayer failed:', e);
  }
}

