import React, { useState, useEffect } from 'react';
import Modal from '../../components/common/Modal';
import Avatar from '../../components/common/Avatar';
import { usePlayers } from '../../hooks/usePlayers';
import { DURATION_OPTIONS, getCategory, formatDate, toDateKey } from '../../utils/helpers';

const AGE_FILTERS = ['Svi', 'U10', 'U12', 'U14', 'U15', 'U16', 'U17', 'U19', 'Senior'];

async function compressImage(file, maxWidth = 900, quality = 0.75) {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let { width, height } = img;
        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        canvas.getContext('2d').drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', quality));
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}

export default function TrainingModal({ isOpen, onClose, onSave, date, time, existing }) {
  const { players, updateAttendance } = usePlayers();
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState('');
  const [ageFilter, setAgeFilter] = useState('Svi');
  const [images, setImages] = useState([]);
  const [imageLoading, setImageLoading] = useState(false);
  const imgInputRef = React.useRef(null);

  const [form, setForm] = useState({
    name: '',
    duration: 60,
    note: '',
    playerIds: []
  });

  useEffect(() => {
    if (existing) {
      setForm({
        name: existing.name || '',
        duration: existing.duration || 60,
        note: existing.note || '',
        playerIds: existing.playerIds || []
      });
      setImages(existing.images || (existing.imageBase64 ? [existing.imageBase64] : []));
    } else {
      setForm({ name: '', duration: 60, note: '', playerIds: [] });
      setImages([]);
    }
  }, [existing, isOpen]);

  const handleImageChange = async (e) => {
    const files = Array.from(e.target.files);
    if (!files.length) return;
    setImageLoading(true);
    try {
      const compressed = await Promise.all(files.map(f => compressImage(f)));
      setImages(prev => [...prev, ...compressed]);
    } catch (err) {
      console.error('Image error:', err);
    } finally {
      setImageLoading(false);
      if (imgInputRef.current) imgInputRef.current.value = '';
    }
  };

  const removeImage = (idx) => setImages(prev => prev.filter((_, i) => i !== idx));

  const filteredPlayers = players.filter(p => {
    if (ageFilter === 'Svi') return true;
    return getCategory(p.birthYear) === ageFilter;
  });

  const togglePlayer = (playerId) => {
    setForm(prev => ({
      ...prev,
      playerIds: prev.playerIds.includes(playerId)
        ? prev.playerIds.filter(id => id !== playerId)
        : [...prev.playerIds, playerId]
    }));
  };

  const selectAll = () => {
    const visibleIds = filteredPlayers.map(p => p.id);
    setForm(prev => ({ ...prev, playerIds: [...new Set([...prev.playerIds, ...visibleIds])] }));
  };

  const deselectAll = () => {
    const visibleIds = filteredPlayers.map(p => p.id);
    setForm(prev => ({ ...prev, playerIds: prev.playerIds.filter(id => !visibleIds.includes(id)) }));
  };

  const handleSave = async () => {
    if (!form.name.trim()) return;
    setSaving(true);
    setSaveError('');
    try {
      const trainingData = {
        date: toDateKey(date),
        time: time || '10:00',
        name: form.name,
        duration: form.duration,
        note: form.note,
        playerIds: form.playerIds,
        exercises: [],
        ...(images.length ? { images } : {})
      };

      const trainingId = await onSave(trainingData);

      // Mark attendance for all selected players
      const dateKey = toDateKey(date);
      await Promise.all(
        form.playerIds.map(playerId =>
          updateAttendance(playerId, dateKey, null) // null = has training but not yet marked
            .catch(err => console.warn('Could not set attendance for', playerId, err))
        )
      );

      onClose();
    } catch (err) {
      console.error('Error saving training:', err);
      setSaveError('Greška: ' + (err?.message || 'Nepoznata greška'));
    } finally {
      setSaving(false);
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title={existing ? 'Uredi trening' : 'Novi trening'}
      width={600}
      footer={
        <>
          {saveError && (
            <span style={{ color: 'var(--error)', fontSize: '0.78rem', flex: 1 }}>{saveError}</span>
          )}
          <button className="btn btn-secondary" onClick={onClose}>Otkaži</button>
          <button
            className="btn btn-primary"
            onClick={handleSave}
            disabled={saving || !form.name.trim()}
          >
            {saving ? 'Čuvam...' : existing ? 'Sačuvaj izmene' : 'Dodaj trening'}
          </button>
        </>
      }
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        {/* Date/time info */}
        <div style={{
          background: 'rgba(37,99,235,0.08)',
          border: '1px solid rgba(37,99,235,0.2)',
          borderRadius: 8,
          padding: '10px 14px',
          fontSize: '0.88rem',
          color: 'var(--gold)',
          display: 'flex',
          gap: 16
        }}>
          <span>📅 {date ? formatDate(date) : '—'}</span>
          {time && <span>🕐 {time}</span>}
        </div>

        {/* Training name */}
        <div className="form-group">
          <label className="label">Naziv treninga *</label>
          <input
            className="input"
            placeholder="npr. Tehničke vežbe, Taktički trening..."
            value={form.name}
            onChange={e => setForm(p => ({ ...p, name: e.target.value }))}
          />
        </div>

        <div className="form-row">
          <div className="form-group">
            <label className="label">Trajanje</label>
            <select
              className="input"
              value={form.duration}
              onChange={e => setForm(p => ({ ...p, duration: parseInt(e.target.value) }))}
            >
              {DURATION_OPTIONS.map(d => (
                <option key={d.value} value={d.value}>{d.label}</option>
              ))}
            </select>
          </div>
        </div>

        {/* Note */}
        <div className="form-group">
          <label className="label">Napomena</label>
          <textarea
            className="input"
            rows={2}
            placeholder="Opšte napomene o treningu..."
            value={form.note}
            onChange={e => setForm(p => ({ ...p, note: e.target.value }))}
          />
        </div>

        {/* Images upload — svaka slika = jedna vežba */}
        <div className="form-group">
          <label className="label">Slike vežbi ({images.length}) — svaka slika = jedna vežba</label>
          {images.length > 0 && (
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 8 }}>
              {images.map((img, idx) => (
                <div key={idx} style={{ position: 'relative' }}>
                  <img src={img} alt={`Vežba ${idx + 1}`}
                    style={{ width: 100, height: 76, objectFit: 'cover', borderRadius: 6, border: '1px solid var(--border)' }} />
                  <div style={{ position: 'absolute', bottom: 2, left: 4, fontSize: '0.6rem', color: '#fff', fontWeight: 700, textShadow: '0 1px 3px #000' }}>
                    V{idx + 1}
                  </div>
                  <button type="button" onClick={() => removeImage(idx)}
                    style={{ position: 'absolute', top: 3, right: 3, background: 'rgba(0,0,0,0.65)', border: 'none', borderRadius: '50%', width: 20, height: 20, cursor: 'pointer', color: '#fff', fontSize: '0.65rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
                </div>
              ))}
            </div>
          )}
          <label style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', border: '1px dashed var(--border)', borderRadius: 8, cursor: imageLoading ? 'wait' : 'pointer', color: 'var(--text-muted)', fontSize: '0.85rem', transition: 'border-color 0.15s' }}
            onMouseEnter={e => e.currentTarget.style.borderColor = 'var(--gold)'}
            onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}
          >
            <input ref={imgInputRef} type="file" accept="image/*" multiple onChange={handleImageChange} style={{ display: 'none' }} disabled={imageLoading} />
            <span style={{ fontSize: '1.2rem' }}>📷</span>
            <span>{imageLoading ? 'Učitavam...' : '+ Dodaj slike vežbi'}</span>
          </label>
        </div>

        {/* Player selection */}
        <div>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
            <label className="label" style={{ margin: 0 }}>
              Igrači ({form.playerIds.length} odabrano)
            </label>
            <div style={{ display: 'flex', gap: 6 }}>
              <button className="btn btn-sm btn-secondary" onClick={selectAll} style={{ fontSize: '0.75rem', padding: '4px 10px' }}>
                Sve
              </button>
              <button className="btn btn-sm btn-secondary" onClick={deselectAll} style={{ fontSize: '0.75rem', padding: '4px 10px' }}>
                Poništi
              </button>
            </div>
          </div>

          {/* Age filter tabs */}
          <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', marginBottom: 12 }}>
            {AGE_FILTERS.map(f => (
              <button
                key={f}
                onClick={() => setAgeFilter(f)}
                style={{
                  padding: '3px 10px',
                  borderRadius: 20,
                  border: '1px solid',
                  borderColor: ageFilter === f ? 'var(--gold)' : 'var(--border)',
                  background: ageFilter === f ? 'rgba(37,99,235,0.15)' : 'transparent',
                  color: ageFilter === f ? 'var(--gold)' : 'var(--text-muted)',
                  fontSize: '0.75rem',
                  fontWeight: 600,
                  cursor: 'pointer'
                }}
              >
                {f}
              </button>
            ))}
          </div>

          {players.length === 0 ? (
            <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
              Nema dodanih igrača.
            </div>
          ) : filteredPlayers.length === 0 ? (
            <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
              Nema igrača u ovoj kategoriji.
            </div>
          ) : (
            <div style={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: 8,
              maxHeight: 200,
              overflowY: 'auto',
              padding: 4
            }}>
              {filteredPlayers.map(p => {
                const fullName = `${p.firstName || ''} ${p.lastName || ''}`.trim();
                const selected = form.playerIds.includes(p.id);
                return (
                  <div
                    key={p.id}
                    onClick={() => togglePlayer(p.id)}
                    title={fullName}
                    style={{
                      position: 'relative',
                      cursor: 'pointer',
                      transition: 'transform 0.15s ease'
                    }}
                    onMouseEnter={e => e.currentTarget.style.transform = 'scale(1.05)'}
                    onMouseLeave={e => e.currentTarget.style.transform = 'scale(1)'}
                  >
                    <div style={{
                      border: selected ? '2px solid var(--gold)' : '2px solid var(--border)',
                      borderRadius: '50%',
                      padding: 2,
                      transition: 'border-color 0.15s ease'
                    }}>
                      <Avatar src={p.photoBase64} name={fullName} size="sm" />
                    </div>
                    {selected && (
                      <div style={{
                        position: 'absolute',
                        bottom: -2,
                        right: -2,
                        width: 16,
                        height: 16,
                        background: 'var(--gold)',
                        borderRadius: '50%',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontSize: '0.6rem',
                        color: '#000',
                        fontWeight: 900,
                        border: '1.5px solid var(--bg-card)'
                      }}>
                        ✓
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Exercises placeholder */}
        <div style={{
          background: 'rgba(37,99,235,0.06)',
          border: '1px dashed rgba(37,99,235,0.3)',
          borderRadius: 8,
          padding: '14px 16px',
          fontSize: '0.82rem',
          color: 'var(--text-muted)',
          textAlign: 'center'
        }}>
          ⚽ <strong style={{ color: 'var(--gold)' }}>Lista vežbi</strong> — Integracija sa filter app-om dolazi uskoro
        </div>
      </div>
    </Modal>
  );
}
