import React, { useState } from 'react';
import { useTrainings } from '../../hooks/useTrainings';
import TrainingModal from './TrainingModal';
import {
  getMonthName,
  getDaysInMonth,
  getFirstDayOfWeek,
  toDateKey,
  DAYS_SHORT,
  formatDate
} from '../../utils/helpers';

function generateSlots(startH, endH) {
  const slots = [];
  for (let h = startH; h < endH; h++) {
    slots.push(`${String(h).padStart(2, '0')}:00`);
    slots.push(`${String(h).padStart(2, '0')}:30`);
  }
  slots.push(`${String(endH).padStart(2, '0')}:00`);
  return slots;
}

function loadWorkHours() {
  try {
    const saved = JSON.parse(localStorage.getItem('workHours'));
    if (saved && saved.start >= 0 && saved.end <= 23 && saved.start < saved.end) return saved;
  } catch(e) {}
  return { start: 8, end: 20 };
}

export default function SchedulePage() {
  const now = new Date();
  const [year, setYear] = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth());
  const [selectedDay, setSelectedDay] = useState(null);
  const [showTimeSlots, setShowTimeSlots] = useState(false);
  const [selectedTime, setSelectedTime] = useState(null);
  const [trainingModal, setTrainingModal] = useState(false);
  const [editingTraining, setEditingTraining] = useState(null);
  const [workHours, setWorkHours] = useState(loadWorkHours);
  const [editingHours, setEditingHours] = useState(false);
  const [hoursInput, setHoursInput] = useState(loadWorkHours);

  const TIME_SLOTS = generateSlots(workHours.start, workHours.end);

  const saveWorkHours = () => {
    const s = parseInt(hoursInput.start);
    const e = parseInt(hoursInput.end);
    if (isNaN(s) || isNaN(e) || s >= e || s < 0 || e > 23) return;
    const wh = { start: s, end: e };
    setWorkHours(wh);
    localStorage.setItem('workHours', JSON.stringify(wh));
    setEditingHours(false);
  };

  const { trainings, addTraining, updateTraining, deleteTraining } = useTrainings();

  const days = getDaysInMonth(year, month);
  const firstDayOfWeek = getFirstDayOfWeek(year, month);

  const prevMonth = () => {
    if (month === 0) { setMonth(11); setYear(y => y - 1); }
    else setMonth(m => m - 1);
  };

  const nextMonth = () => {
    if (month === 11) { setMonth(0); setYear(y => y + 1); }
    else setMonth(m => m + 1);
  };

  const goToToday = () => {
    setYear(now.getFullYear());
    setMonth(now.getMonth());
  };

  const getTrainingsForDay = (day) => {
    const key = toDateKey(day);
    return trainings.filter(t => t.date === key).sort((a, b) => (a.time || '').localeCompare(b.time || ''));
  };

  const isToday = (day) => {
    return day.getDate() === now.getDate() &&
      day.getMonth() === now.getMonth() &&
      day.getFullYear() === now.getFullYear();
  };

  const handleDayClick = (day) => {
    setSelectedDay(day);
    setShowTimeSlots(true);
    setSelectedTime(null);
  };

  const handleTimeSlotClick = (time) => {
    setSelectedTime(time);
    setEditingTraining(null);
    setTrainingModal(true);
  };

  const handleSaveTraining = async (data) => {
    if (editingTraining) {
      await updateTraining(editingTraining.id, data);
    } else {
      return await addTraining(data);
    }
  };

  const handleEditTraining = (training, e) => {
    e.stopPropagation();
    setEditingTraining(training);
    setSelectedDay(new Date(training.date + 'T12:00:00'));
    setSelectedTime(training.time);
    setTrainingModal(true);
  };

  const handleDeleteTraining = async (trainingId, e) => {
    e.stopPropagation();
    if (window.confirm('Obrisati ovaj trening?')) {
      await deleteTraining(trainingId);
    }
  };

  // Count trainings for month
  const monthTrainingCount = trainings.filter(t => {
    if (!t.date) return false;
    const prefix = `${year}-${String(month + 1).padStart(2, '0')}`;
    return t.date.startsWith(prefix);
  }).length;

  return (
    <div>
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Raspored treninga</h1>
          <p className="page-subtitle">{monthTrainingCount} treninga u {getMonthName(month)} {year}</p>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          {editingHours ? (
            <>
              <input
                type="number" min="0" max="22"
                value={hoursInput.start}
                onChange={e => setHoursInput(p => ({ ...p, start: e.target.value }))}
                style={{ width: 52, padding: '4px 8px', background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 6, color: 'var(--text-primary)', fontSize: '0.82rem', textAlign: 'center' }}
              />
              <span style={{ color: 'var(--text-muted)', fontSize: '0.82rem' }}>—</span>
              <input
                type="number" min="1" max="23"
                value={hoursInput.end}
                onChange={e => setHoursInput(p => ({ ...p, end: e.target.value }))}
                style={{ width: 52, padding: '4px 8px', background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 6, color: 'var(--text-primary)', fontSize: '0.82rem', textAlign: 'center' }}
              />
              <button className="btn btn-primary btn-sm" onClick={saveWorkHours}>Sačuvaj</button>
              <button className="btn btn-secondary btn-sm" onClick={() => setEditingHours(false)}>Otkaži</button>
            </>
          ) : (
            <button
              className="btn btn-secondary btn-sm"
              onClick={() => { setHoursInput(workHours); setEditingHours(true); }}
              title="Uredi radne sate"
            >
              🕐 {String(workHours.start).padStart(2,'0')}:00 – {String(workHours.end).padStart(2,'0')}:00
            </button>
          )}
          <button className="btn btn-secondary btn-sm" onClick={goToToday}>Danas</button>
        </div>
      </div>

      {/* Month navigation */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 20 }}>
        <button className="btn btn-secondary btn-sm btn-icon" onClick={prevMonth}>‹</button>
        <h2 style={{ margin: 0, fontSize: '1.3rem', minWidth: 200, textAlign: 'center' }}>
          {getMonthName(month)} {year}
        </h2>
        <button className="btn btn-secondary btn-sm btn-icon" onClick={nextMonth}>›</button>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: showTimeSlots ? '1fr 280px' : '1fr', gap: 20 }}>
        {/* Calendar */}
        <div style={{
          background: 'var(--bg-card)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius-lg)',
          overflow: 'hidden'
        }}>
          {/* Day headers */}
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, 1fr)',
            borderBottom: '1px solid var(--border)',
            background: 'var(--bg-primary)'
          }}>
            {DAYS_SHORT.map(d => (
              <div key={d} style={{
                padding: '12px 4px',
                textAlign: 'center',
                fontSize: '0.75rem',
                fontWeight: 700,
                color: 'var(--text-muted)',
                textTransform: 'uppercase'
              }}>
                {d}
              </div>
            ))}
          </div>

          {/* Days grid */}
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, 1fr)',
            gap: 1,
            background: 'var(--border)'
          }}>
            {Array.from({ length: firstDayOfWeek }).map((_, i) => (
              <div key={`empty-${i}`} style={{ background: 'var(--bg-card)', minHeight: 90 }} />
            ))}

            {days.map(day => {
              const dayTrainings = getTrainingsForDay(day);
              const today = isToday(day);
              const selected = selectedDay && toDateKey(selectedDay) === toDateKey(day);

              return (
                <div
                  key={day.toISOString()}
                  onClick={() => handleDayClick(day)}
                  style={{
                    background: selected
                      ? 'rgba(37,99,235,0.1)'
                      : today
                      ? 'rgba(37,99,235,0.05)'
                      : 'var(--bg-card)',
                    minHeight: 90,
                    padding: '8px',
                    cursor: 'pointer',
                    transition: 'background 0.15s ease',
                    position: 'relative',
                    borderTop: today ? '2px solid var(--gold)' : '2px solid transparent'
                  }}
                  onMouseEnter={e => {
                    if (!selected) e.currentTarget.style.background = 'rgba(255,255,255,0.03)';
                  }}
                  onMouseLeave={e => {
                    if (!selected) e.currentTarget.style.background = today ? 'rgba(37,99,235,0.05)' : 'var(--bg-card)';
                  }}
                >
                  <div style={{
                    fontSize: '0.85rem',
                    fontWeight: today ? 800 : 500,
                    color: today ? 'var(--gold)' : selected ? 'var(--gold)' : 'var(--text-secondary)',
                    marginBottom: 4
                  }}>
                    {day.getDate()}
                  </div>

                  {/* Training pills */}
                  {dayTrainings.slice(0, 2).map(t => (
                    <div
                      key={t.id}
                      style={{
                        background: 'rgba(37,99,235,0.15)',
                        border: '1px solid rgba(37,99,235,0.3)',
                        borderRadius: 3,
                        padding: '2px 5px',
                        fontSize: '0.65rem',
                        color: 'var(--gold)',
                        fontWeight: 600,
                        marginBottom: 2,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        gap: 2
                      }}
                    >
                      <span style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>
                        {t.time} {t.name}
                      </span>
                      <div style={{ display: 'flex', gap: 2, flexShrink: 0 }}>
                        <button
                          onClick={e => handleEditTraining(t, e)}
                          style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0, color: 'var(--gold)', fontSize: '0.65rem' }}
                        >
                          ✏
                        </button>
                        <button
                          onClick={e => handleDeleteTraining(t.id, e)}
                          style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0, color: 'var(--error)', fontSize: '0.65rem' }}
                        >
                          ✕
                        </button>
                      </div>
                    </div>
                  ))}
                  {dayTrainings.length > 2 && (
                    <div style={{ fontSize: '0.6rem', color: 'var(--text-muted)' }}>
                      +{dayTrainings.length - 2} više
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Time slot panel */}
        {showTimeSlots && selectedDay && (
          <div style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius-lg)',
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column'
          }}>
            <div style={{
              padding: '16px',
              borderBottom: '1px solid var(--border)',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}>
              <div>
                <div style={{ fontWeight: 700 }}>{formatDate(selectedDay)}</div>
                <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>
                  {getTrainingsForDay(selectedDay).length} treninga
                </div>
              </div>
              <button
                onClick={() => setShowTimeSlots(false)}
                style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: '1.1rem' }}
              >
                ✕
              </button>
            </div>

            <div style={{ overflowY: 'auto', flex: 1 }}>
              {TIME_SLOTS.map(slot => {
                const dayTrainings = getTrainingsForDay(selectedDay);
                const existing = dayTrainings.find(t => t.time === slot);
                return (
                  <div
                    key={slot}
                    onClick={() => handleTimeSlotClick(slot)}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: 10,
                      padding: '10px 16px',
                      borderBottom: '1px solid var(--border)',
                      cursor: 'pointer',
                      transition: 'background 0.15s ease',
                      background: existing ? 'rgba(37,99,235,0.08)' : 'transparent'
                    }}
                    onMouseEnter={e => {
                      if (!existing) e.currentTarget.style.background = 'rgba(255,255,255,0.03)';
                    }}
                    onMouseLeave={e => {
                      e.currentTarget.style.background = existing ? 'rgba(37,99,235,0.08)' : 'transparent';
                    }}
                  >
                    <span style={{
                      fontSize: '0.78rem',
                      color: 'var(--text-muted)',
                      width: 45,
                      flexShrink: 0,
                      fontWeight: 600
                    }}>
                      {slot}
                    </span>
                    {existing ? (
                      <div style={{ flex: 1 }}>
                        <div style={{ fontSize: '0.82rem', color: 'var(--gold)', fontWeight: 600 }}>
                          {existing.name}
                        </div>
                        <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>
                          {existing.duration} min · {(existing.playerIds || []).length} igrača
                        </div>
                      </div>
                    ) : (
                      <span style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>
                        + Dodaj trening
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* Training Modal */}
      <TrainingModal
        isOpen={trainingModal}
        onClose={() => {
          setTrainingModal(false);
          setEditingTraining(null);
        }}
        onSave={handleSaveTraining}
        date={selectedDay}
        time={selectedTime}
        existing={editingTraining}
      />
    </div>
  );
}
