import { useState, useEffect } from 'react';
import { ref, onValue, set } from 'firebase/database';
import { db } from '../firebase';

export const DEFAULT_CRITERIA = ['Tehnika', 'Brzina', 'Taktika', 'Komunikacija', 'Stav'];

export function useSettings() {
  const [settings, setSettings] = useState({ ratingCriteria: DEFAULT_CRITERIA });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const r = ref(db, 'settings');
    const unsub = onValue(r, (snap) => {
      const data = snap.val();
      setSettings({
        ratingCriteria: DEFAULT_CRITERIA,
        ...(data || {})
      });
      setLoading(false);
    });
    return () => unsub();
  }, []);

  const updateRatingCriteria = async (criteria) => {
    await set(ref(db, 'settings/ratingCriteria'), criteria);
  };

  return { settings, loading, updateRatingCriteria };
}
