import React, { useState } from 'react';
import { usePlayers } from '../../hooks/usePlayers';
import { useTrainings } from '../../hooks/useTrainings';
import { generatePlayerReport } from './generatePDF';
import Avatar from '../../components/common/Avatar';
import { PositionBadge } from '../../components/common/Badge';
import { getAge, calculateAttendanceStats, getLatestAssessment } from '../../utils/helpers';

export default function ReportsPage() {
  const { players, loading: loadingPlayers } = usePlayers();
  const { trainings, loading: loadingTrainings } = useTrainings();
  const [selectedPlayerId, setSelectedPlayerId] = useState('');
  const [period, setPeriod] = useState('3m');
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState('');

  const selectedPlayer = players.find(p => p.id === selectedPlayerId);

  const handleGenerate = async () => {
    if (!selectedPlayer) return;
    setGenerating(true);
    setError('');
    try {
      await generatePlayerReport(selectedPlayer, trainings, period);
    } catch (err) {
      console.error('PDF generation error:', err);
      setError('Greška pri generisanju PDF-a. Pokušajte ponovo.');
    } finally {
      setGenerating(false);
    }
  };

  const stats = selectedPlayer ? calculateAttendanceStats(selectedPlayer.attendances) : null;
  const latestAssessment = selectedPlayer ? getLatestAssessment(selectedPlayer.assessments) : null;
  const goalsCount = selectedPlayer?.goals ? Object.keys(selectedPlayer.goals).length : 0;
  const notesCount = selectedPlayer?.trainingNotes ? Object.keys(selectedPlayer.trainingNotes).length : 0;

  if (loadingPlayers || loadingTrainings) {
    return <div className="loading-container"><div className="loading-spinner" /></div>;
  }

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">Izveštaji</h1>
          <p className="page-subtitle">Generiši PDF izveštaj za igrača</p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24, maxWidth: 900 }}>
        {/* Left: Configuration */}
        <div>
          {/* Player selection */}
          <div style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius)',
            padding: 20,
            marginBottom: 16
          }}>
            <h3 style={{ marginBottom: 16 }}>1. Odaberi igrača</h3>

            {players.length === 0 ? (
              <p style={{ color: 'var(--text-muted)', fontSize: '0.88rem' }}>
                Nema dodanih igrača.
              </p>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                {players.map(player => {
                  const fullName = `${player.firstName || ''} ${player.lastName || ''}`.trim() || 'Nepoznat';
                  const selected = player.id === selectedPlayerId;
                  return (
                    <div
                      key={player.id}
                      onClick={() => setSelectedPlayerId(player.id)}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 12,
                        padding: '10px 14px',
                        borderRadius: 8,
                        border: '1px solid',
                        borderColor: selected ? 'var(--gold)' : 'var(--border)',
                        background: selected ? 'rgba(37,99,235,0.08)' : 'var(--bg-primary)',
                        cursor: 'pointer',
                        transition: 'all 0.15s ease'
                      }}
                      onMouseEnter={e => {
                        if (!selected) e.currentTarget.style.borderColor = '#3a3a3a';
                      }}
                      onMouseLeave={e => {
                        if (!selected) e.currentTarget.style.borderColor = 'var(--border)';
                      }}
                    >
                      <Avatar src={player.photoBase64} name={fullName} size="sm" />
                      <div style={{ flex: 1 }}>
                        <div style={{ fontWeight: 600, fontSize: '0.88rem' }}>{fullName}</div>
                        <div style={{ display: 'flex', gap: 6, marginTop: 3 }}>
                          <PositionBadge position={player.position} />
                          {player.club && (
                            <span style={{ fontSize: '0.72rem', color: 'var(--text-muted)' }}>{player.club}</span>
                          )}
                        </div>
                      </div>
                      {selected && (
                        <span style={{ color: 'var(--gold)', fontSize: '1.1rem' }}>✓</span>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          {/* Period selection */}
          <div style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius)',
            padding: 20,
            marginBottom: 16
          }}>
            <h3 style={{ marginBottom: 16 }}>2. Odaberi period</h3>
            <div style={{ display: 'flex', gap: 10 }}>
              {[
                { value: '3m', label: '3 meseca', desc: 'Kratkoročni pregled' },
                { value: '6m', label: '6 meseci', desc: 'Dugoročni pregled' }
              ].map(opt => (
                <div
                  key={opt.value}
                  onClick={() => setPeriod(opt.value)}
                  style={{
                    flex: 1,
                    padding: '14px 16px',
                    borderRadius: 8,
                    border: '1px solid',
                    borderColor: period === opt.value ? 'var(--gold)' : 'var(--border)',
                    background: period === opt.value ? 'rgba(37,99,235,0.08)' : 'var(--bg-primary)',
                    cursor: 'pointer',
                    transition: 'all 0.15s ease',
                    textAlign: 'center'
                  }}
                >
                  <div style={{
                    fontSize: '1.1rem',
                    fontWeight: 800,
                    color: period === opt.value ? 'var(--gold)' : 'var(--text-primary)',
                    marginBottom: 4
                  }}>
                    {opt.label}
                  </div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                    {opt.desc}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Generate button */}
          <button
            className="btn btn-primary btn-lg"
            onClick={handleGenerate}
            disabled={!selectedPlayer || generating}
            style={{
              width: '100%',
              fontSize: '1rem',
              fontWeight: 700,
              padding: '16px',
              opacity: !selectedPlayer ? 0.5 : 1
            }}
          >
            {generating ? (
              <>
                <div style={{
                  width: 20,
                  height: 20,
                  border: '2px solid rgba(0,0,0,0.3)',
                  borderTop: '2px solid #000',
                  borderRadius: '50%',
                  animation: 'spin 0.8s linear infinite'
                }} />
                Generišem PDF...
              </>
            ) : (
              <>
                <span>📋</span>
                Generiši PDF Izveštaj
              </>
            )}
          </button>

          {error && (
            <div style={{
              background: 'var(--error-bg)',
              border: '1px solid rgba(239,68,68,0.3)',
              borderRadius: 8,
              padding: '12px 16px',
              marginTop: 12,
              fontSize: '0.85rem',
              color: 'var(--error)'
            }}>
              {error}
            </div>
          )}
        </div>

        {/* Right: Preview */}
        <div>
          <div style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius)',
            padding: 20,
            position: 'sticky',
            top: 84
          }}>
            <h3 style={{ marginBottom: 16 }}>Pregled izveštaja</h3>

            {!selectedPlayer ? (
              <div className="empty-state" style={{ padding: '40px 20px' }}>
                <div className="empty-state-icon">📄</div>
                <div className="empty-state-title">Odaberi igrača</div>
                <p className="empty-state-text">Izaberi igrača sa leve strane da vidiš šta će biti uključeno u izveštaj.</p>
              </div>
            ) : (
              <div>
                {/* Player summary */}
                <div style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 12,
                  padding: '12px',
                  background: 'rgba(37,99,235,0.07)',
                  border: '1px solid rgba(37,99,235,0.2)',
                  borderRadius: 8,
                  marginBottom: 16
                }}>
                  <Avatar src={selectedPlayer.photoBase64} name={`${selectedPlayer.firstName} ${selectedPlayer.lastName}`} size="md" />
                  <div>
                    <div style={{ fontWeight: 700 }}>{`${selectedPlayer.firstName || ''} ${selectedPlayer.lastName || ''}`.trim()}</div>
                    <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                      {selectedPlayer.position} · {selectedPlayer.club || 'bez kluba'}
                    </div>
                  </div>
                </div>

                {/* What's included */}
                <div style={{ marginBottom: 16 }}>
                  <div style={{ fontSize: '0.8rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', marginBottom: 10 }}>
                    Šta će biti uključeno:
                  </div>

                  {[
                    {
                      icon: '👤',
                      label: 'Podaci igrača',
                      detail: `${selectedPlayer.position || '—'} · ${selectedPlayer.birthYear || '—'}`
                    },
                    {
                      icon: '📅',
                      label: 'Statistike treninga',
                      detail: stats ? `${stats.present} dolazaka / ${stats.total} ukupno (${stats.percentage}%)` : 'Nema podataka',
                      ok: stats && stats.total > 0
                    },
                    {
                      icon: '📊',
                      label: 'Napredak po stubovima',
                      detail: latestAssessment ? `Poslednja procena: ${latestAssessment.date}` : 'Nema procena',
                      ok: !!latestAssessment
                    },
                    {
                      icon: '🎯',
                      label: 'Ciljevi igrača',
                      detail: `${goalsCount} ciljeva definisano`,
                      ok: goalsCount > 0
                    },
                    {
                      icon: '📝',
                      label: 'Napomene trenera',
                      detail: `${notesCount} napomena (prikazuje se poslednjih 10)`,
                      ok: notesCount > 0
                    }
                  ].map(item => (
                    <div key={item.label} style={{
                      display: 'flex',
                      gap: 10,
                      padding: '8px 0',
                      borderBottom: '1px solid var(--border)'
                    }}>
                      <span style={{ width: 20, textAlign: 'center' }}>{item.icon}</span>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontSize: '0.85rem', fontWeight: 600 }}>{item.label}</div>
                        <div style={{
                          fontSize: '0.75rem',
                          color: item.ok === false ? 'var(--text-muted)' : item.ok ? 'var(--success)' : 'var(--text-muted)'
                        }}>
                          {item.detail}
                        </div>
                      </div>
                      {item.ok !== undefined && (
                        <span style={{
                          fontSize: '0.9rem',
                          color: item.ok ? 'var(--success)' : 'var(--text-muted)'
                        }}>
                          {item.ok ? '✓' : '○'}
                        </span>
                      )}
                    </div>
                  ))}
                </div>

                <div style={{
                  background: 'rgba(37,99,235,0.07)',
                  border: '1px solid rgba(37,99,235,0.2)',
                  borderRadius: 6,
                  padding: '10px 12px',
                  fontSize: '0.78rem',
                  color: 'var(--text-muted)',
                  lineHeight: 1.5
                }}>
                  📎 PDF će biti preuzet automatski. Naziv fajla: <span style={{ color: 'var(--gold)' }}>IzvestajIgraca_{`${selectedPlayer.firstName || 'Igrac'}`}_{new Date().toISOString().split('T')[0]}.pdf</span>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
